// 文法速查表資料（草稿，待老師審核）。t=標題 d=說明 ex=例句；k=搜尋用關鍵字（自動產生，不顯示）；簡體由繁體自動轉換（OpenCC tw2s，保留台灣用語）
window.GRAMMAR={"books":{"1":"A1–A2","2":"A2–B1","3":"B1","4":"B1–B2"},"lessons":{"1-1":{"tc":"歡迎你來台灣！","sc":"欢迎你来台湾！"},"1-2":{"tc":"我的家人","sc":"我的家人"},"1-3":{"tc":"週末做什麼？","sc":"周末做什么？"},"1-4":{"tc":"請問一共多少錢？","sc":"请问一共多少钱？"},"1-5":{"tc":"牛肉麵真好吃","sc":"牛肉面真好吃"},"1-6":{"tc":"他們學校在山上","sc":"他们学校在山上"},"1-7":{"tc":"早上九點去 KTV","sc":"早上九点去 KTV"},"1-8":{"tc":"坐火車去台南","sc":"坐火车去台南"},"1-9":{"tc":"放假去哪裡玩？","sc":"放假去哪里玩？"},"1-10":{"tc":"台灣的水果很好吃","sc":"台湾的水果很好吃"},"1-11":{"tc":"我要租房子","sc":"我要租房子"},"1-12":{"tc":"你在台灣學多久的中文？","sc":"你在台湾学多久的中文？"},"1-13":{"tc":"生日快樂","sc":"生日快乐"},"1-14":{"tc":"天氣這麼冷！","sc":"天气这么冷！"},"1-15":{"tc":"我很不舒服","sc":"我很不舒服"},"2-1":{"tc":"請問，到師到怎麼走？","sc":"请问，到师到怎么走？"},"2-2":{"tc":"還是坐捷運吧！","sc":"还是坐捷运吧！"},"2-3":{"tc":"你的中文進步了！","sc":"你的中文进步了！"},"2-4":{"tc":"我打工，我教法文","sc":"我打工，我教法文"},"2-5":{"tc":"吃喜酒","sc":"吃喜酒"},"2-6":{"tc":"我打算搬到學校附近","sc":"我打算搬到学校附近"},"2-7":{"tc":"垃圾車來了！","sc":"垃圾车来了！"},"2-8":{"tc":"學功夫","sc":"学功夫"},"2-9":{"tc":"那個城市好漂亮","sc":"那个城市好漂亮"},"2-10":{"tc":"歡迎到我家來包餃子","sc":"欢迎到我家来包饺子"},"2-11":{"tc":"台灣好玩的地方真多","sc":"台湾好玩的地方真多"},"2-12":{"tc":"怎麼吃才健康？","sc":"怎么吃才健康？"},"2-13":{"tc":"我的手機掉了","sc":"我的手机掉了"},"2-14":{"tc":"我要開始工作了","sc":"我要开始工作了"},"2-15":{"tc":"過春節","sc":"过春节"},"3-1":{"tc":"開學了","sc":"开学了"},"3-2":{"tc":"八折起","sc":"八折起"},"3-3":{"tc":"外套帶了沒有？","sc":"外套带了没有？"},"3-4":{"tc":"我愛台灣的人情味","sc":"我爱台湾的人情味"},"3-5":{"tc":"現在流行什麼？","sc":"现在流行什么？"},"3-6":{"tc":"到鄉下住一晚！","sc":"到乡下住一晚！"},"3-7":{"tc":"我最親的家「人」","sc":"我最亲的家「人」"},"3-8":{"tc":"我想做自己","sc":"我想做自己"},"3-9":{"tc":"網購時代","sc":"网购时代"},"3-10":{"tc":"我住院了","sc":"我住院了"},"3-11":{"tc":"台灣故事","sc":"台湾故事"},"3-12":{"tc":"我要去投票","sc":"我要去投票"},"4-1":{"tc":"十七歲還是二十五歲？","sc":"十七岁还是二十五岁？"},"4-2":{"tc":"眼睛、耳朵的饗宴","sc":"眼睛、耳朵的飨宴"},"4-3":{"tc":"雲端科技","sc":"云端科技"},"4-4":{"tc":"床該擺哪裡？","sc":"床该摆哪里？"},"4-5":{"tc":"有夢最美","sc":"有梦最美"},"4-6":{"tc":"天搖地動","sc":"天摇地动"},"4-7":{"tc":"大學生的事","sc":"大学生的事"},"4-8":{"tc":"他們的選擇","sc":"他们的选择"},"4-9":{"tc":"再談台灣故事","sc":"再谈台湾故事"},"4-10":{"tc":"應徵","sc":"应征"},"4-11":{"tc":"文化、種族的大熔爐","sc":"文化、种族的大熔炉"},"4-12":{"tc":"期待美好的未來","sc":"期待美好的未来"}},"points":[{"id":"1-1-0","b":1,"l":1,"k":"pregunta preguntar interrogativa question ask 疑問 問句 提問 pregunta preguntar interrogativa question ask 疑问 问句 提问","t":{"es":"Preguntas con 嗎","en":"Ways to Ask Questions in Chinese / Asking Questions with 嗎 ma","ens":"Ways to Ask Questions in Chinese / Asking Questions with 吗 ma","tc":"用「嗎」問問題","sc":"用「吗」问问题"},"d":{"es":"Para preguntas de sí/no: añade 嗎 al final de una oración afirmativa. También puedes usar la forma A-no-A (verbo + 不 + verbo).","en":"For yes/no questions, add 嗎 at the end of a statement. You can also use the A-not-A pattern (verb + 不 + verb).","tc":"問是不是、有沒有的問題時，在句子最後加「嗎」。也可以用「A 不 A」的方式問，例如「是不是」。","sc":"问是不是、有没有的问题时，在句子最后加「吗」。也可以用「A 不 A」的方式问，例如「是不是」。"},"ex":[{"c":"你是學生嗎？","s":"你是学生吗？","es":"¿Eres estudiante?","en":"Are you a student?","p":"nǐ shì xué shēng ma?"},{"c":"你是不是學生？","s":"你是不是学生？","es":"¿Eres o no eres estudiante?","en":"Are you a student or not?","p":"nǐ shì bú shì xué shēng?"}]},{"id":"1-1-1","b":1,"l":1,"k":"pregunta preguntar interrogativa question ask 疑問 問句 提問 negación negar negativa negation negative 否定 pregunta preguntar interrogativa question ask 疑问 问句 提问 negación negar negativa negation negative 否定","t":{"es":"Cómo responder: 是 / 不是","en":"Answering Questions in Chinese / Affirmative Answers / Negative Replies with 不 bù","ens":"Answering Questions in Chinese / Affirmative Answers / Negative Replies with 不 bù","tc":"回答問題：是／不是","sc":"回答问题：是／不是"},"d":{"es":"Se responde repitiendo el verbo: 是 / 不是. La negación 不 va justo antes del verbo o adjetivo. No se contesta con un simple «sí/no».","en":"Answer by repeating the verb: 是 / 不是. 不 goes right before the verb or adjective. Don't answer with a bare 'yes' or 'no'.","tc":"回答時重複問句裡的動詞，例如「是」或「不是」。「不」放在動詞或形容詞前面，不要只回答 yes 或 no。","sc":"回答时重复问句里的动词，例如「是」或「不是」。「不」放在动词或形容词前面，不要只回答 yes 或 no。"},"ex":[{"c":"你是老師嗎？——不是，我不是老師。","s":"你是老师吗？——不是，我不是老师。","es":"¿Eres profesor? — No, no soy profesor.","en":"Are you a teacher? — No, I'm not a teacher.","p":"nǐ shì lǎo shī ma? — bú shì, wǒ bú shì lǎo shī."}]},{"id":"1-1-2","b":1,"l":1,"k":"","t":{"es":"Adjetivos con 很","en":"Modification Marker 很 hěn","ens":"Modification Marker 很 hěn","tc":"形容詞前面的「很」","sc":"形容词前面的「很」"},"d":{"es":"Con adjetivos (verbos estativos) se pone 很 antes del adjetivo. Aquí 很 casi no significa «muy»; sin él, la oración suena a comparación.","en":"When an adjective is the predicate, put 很 before it. Here 很 usually doesn't mean 'very'; without it the sentence sounds like a comparison.","tc":"形容詞當謂語時，前面通常要加「很」。這裡的「很」不一定是「非常」的意思，沒有它句子會像在做比較。","sc":"形容词当谓语时，前面通常要加「很」。这里的「很」不一定是「非常」的意思，没有它句子会像在做比较。"},"ex":[{"c":"我很忙。","s":"我很忙。","es":"Estoy ocupado.","en":"I'm busy.","p":"wǒ hěn máng."}]},{"id":"1-1-3","b":1,"l":1,"k":"pregunta preguntar interrogativa question ask 疑問 問句 提問 pregunta preguntar interrogativa question ask 疑问 问句 提问","t":{"es":"¿Y tú? con 呢","en":"Contrastive Questions with 呢 ne","ens":"Contrastive Questions with 呢 ne","tc":"用「呢」反問","sc":"用「呢」反问"},"d":{"es":"呢 devuelve la misma pregunta al otro: «¿y tú?», «¿y …?».","en":"呢 turns the same question back to the other person: 'And you?', 'What about …?'.","tc":"「呢」可以把同樣的問題丟給對方，意思是「那你呢？」「那……呢？」。","sc":"「呢」可以把同样的问题丢给对方，意思是「那你呢？」「那……呢？」。"},"ex":[{"c":"我很好，你呢？","s":"我很好，你呢？","es":"Yo estoy bien, ¿y tú?","en":"I'm fine, and you?","p":"wǒ hěn hǎo, nǐ ne?"}]},{"id":"1-2-0","b":1,"l":2,"k":"","t":{"es":"Posesión con 的","en":"的 de possessive","ens":"的 de possessive","tc":"表示擁有的「的」","sc":"表示拥有的「的」"},"d":{"es":"Sustantivo/pronombre + 的 + sustantivo expresa posesión. Con familiares o personas muy cercanas se suele omitir 的.","en":"Noun/pronoun + 的 + noun shows possession. With family or very close people, 的 is often left out.","tc":"「名詞或代名詞＋的＋名詞」表示誰的東西。家人或很親近的人，常常可以省略「的」。","sc":"「名词或代名词＋的＋名词」表示谁的东西。家人或很亲近的人，常常可以省略「的」。"},"ex":[{"c":"這是我的書。","s":"这是我的书。","es":"Este es mi libro.","en":"This is my book.","p":"zhè shì wǒ de shū."},{"c":"我媽媽很忙。","s":"我妈妈很忙。","es":"Mi mamá está ocupada.","en":"My mom is very busy.","p":"wǒ mā ma hěn máng."}]},{"id":"1-2-1","b":1,"l":2,"k":"","t":{"es":"Modificador + 的","en":"Modifier Marker 的 de","ens":"Modifier Marker 的 de","tc":"修飾名詞的「的」","sc":"修饰名词的「的」"},"d":{"es":"的 une un modificador (adjetivo o frase) con el sustantivo que describe. El modificador siempre va delante del sustantivo.","en":"的 links a modifier (an adjective or a phrase) to the noun it describes. The modifier always comes before the noun.","tc":"「的」連接修飾語（形容詞或一段話）和它說明的名詞。修飾語一定放在名詞前面。","sc":"「的」连接修饰语（形容词或一段话）和它说明的名词。修饰语一定放在名词前面。"},"ex":[{"c":"她是一個很好的老師。","s":"她是一个很好的老师。","es":"Ella es una muy buena profesora.","en":"She is a very good teacher.","p":"tā shì yí ge hěn hǎo de lǎo shī."}]},{"id":"1-2-2","b":1,"l":2,"k":"","t":{"es":"Tener con 有","en":"有 yǒu possessive","ens":"有 yǒu possessive","tc":"「有」：擁有","sc":"「有」：拥有"},"d":{"es":"有 = tener. Su negación es 沒有 (nunca 不有).","en":"有 means 'to have'. Its negation is 沒有 (never 不有).","tc":"「有」是「擁有」的意思。否定要說「沒有」，不能說「不有」。","sc":"「有」是「拥有」的意思。否定要说「没有」，不能说「不有」。"},"ex":[{"c":"我有兩個姐姐，沒有哥哥。","s":"我有两个姐姐，没有哥哥。","es":"Tengo dos hermanas mayores y ningún hermano mayor.","en":"I have two older sisters and no older brother.","p":"wǒ yǒu liǎng ge jiě jie, méi yǒu gē ge."}]},{"id":"1-2-3","b":1,"l":2,"k":"","t":{"es":"Todos con 都","en":"都 dōu totality","ens":"都 dōu totality","tc":"「都」：全部","sc":"「都」：全部"},"d":{"es":"都 = todos / ambos. Va antes del verbo y se refiere a lo que aparece antes de él.","en":"都 means 'all' or 'both'. It goes before the verb and refers to what comes before it.","tc":"「都」是「全部」「都是」的意思。放在動詞前面，指的是它前面提到的人或事。","sc":"「都」是「全部」「都是」的意思。放在动词前面，指的是它前面提到的人或事。"},"ex":[{"c":"我們都是學生。","s":"我们都是学生。","es":"Todos somos estudiantes.","en":"We are all students.","p":"wǒ men dōu shì xué shēng."}]},{"id":"1-2-4","b":1,"l":2,"k":"clasificador clasificadores medida contar cantidad measure word classifier counter 量詞 clasificador clasificadores medida contar cantidad measure word classifier counter 量词","t":{"es":"Clasificadores 個 y 張","en":"Measures 個 ge and 張 zhāng","ens":"Measures 个 ge and 张 zhāng","tc":"量詞：個、張","sc":"量词：个、张"},"d":{"es":"Estructura: número + clasificador + sustantivo. 個 es el clasificador más general; 張 se usa para cosas planas (papel, mesa, boleto, foto).","en":"Pattern: number + measure word + noun. 個 is the most general measure word; 張 is for flat things (paper, tables, tickets, photos).","tc":"句型是「數字＋量詞＋名詞」。「個」最常用；「張」用在平平的東西，例如紙、桌子、票、照片。","sc":"句型是「数字＋量词＋名词」。「个」最常用；「张」用在平平的东西，例如纸、桌子、票、照片。"},"ex":[{"c":"三個人、一張桌子","s":"三个人、一张桌子","es":"tres personas, una mesa","en":"three people, one table","p":"sān ge rén, yì zhāng zhuō zi"}]},{"id":"1-3-0","b":1,"l":3,"k":"tiempo momento orden secuencia time order sequence 時間 順序 lugar ubicación dónde existencia hay location place existence where 地點 位置 存在 tiempo momento orden secuencia time order sequence 时间 顺序 lugar ubicación dónde existencia hay location place existence where 地点 位置 存在","t":{"es":"Palabras de tiempo","en":"Placement of Time Words","ens":"Placement of Time Words","tc":"時間詞的位置","sc":"时间词的位置"},"d":{"es":"Las palabras de tiempo van antes del verbo (después del sujeto o al inicio de la oración), nunca al final.","en":"Time words go before the verb (after the subject or at the start of the sentence), never at the end.","tc":"時間詞放在動詞前面（主詞後面或句首），不放在句尾。","sc":"时间词放在动词前面（主词后面或句首），不放在句尾。"},"ex":[{"c":"我明天去台北。","s":"我明天去台北。","es":"Mañana voy a Taipéi.","en":"I'm going to Taipei tomorrow.","p":"wǒ míng tiān qù tái běi."}]},{"id":"1-3-1","b":1,"l":3,"k":"dirección movimiento direction movement 方向 趨向 dirección movimiento direction movement 方向 趋向","t":{"es":"Ir a hacer algo con 去","en":"To Go Do Something with 去 qù","ens":"To Go Do Something with 去 qù","tc":"「去」＋地方＋動作","sc":"「去」＋地方＋动作"},"d":{"es":"去 + lugar + verbo: ir a un lugar para hacer algo.","en":"去 + place + verb means going somewhere to do something.","tc":"「去＋地方＋動詞」表示到某個地方做某件事。","sc":"「去＋地方＋动词」表示到某个地方做某件事。"},"ex":[{"c":"我去圖書館看書。","s":"我去图书馆看书。","es":"Voy a la biblioteca a leer.","en":"I'm going to the library to read.","p":"wǒ qù tú shū guǎn kàn shū."}]},{"id":"1-3-2","b":1,"l":3,"k":"","t":{"es":"Oraciones con tema","en":"Topic Sentences","ens":"Topic Sentences","tc":"主題句","sc":"主题句"},"d":{"es":"Se puede poner primero el tema (algo ya conocido) y luego comentarlo. El objeto pasa al inicio de la oración.","en":"You can start with the topic (something already known) and then comment on it. The object moves to the front of the sentence.","tc":"可以先說出大家已經知道的話題，再說明它。這時受詞會移到句子前面。","sc":"可以先说出大家已经知道的话题，再说明它。这时受词会移到句子前面。"},"ex":[{"c":"中文我會說，日文我不會說。","s":"中文我会说，日文我不会说。","es":"El chino sí sé hablarlo; el japonés no.","en":"Chinese I can speak; Japanese I can't.","p":"zhōng wén wǒ huì shuō, rì wén wǒ bú huì shuō."}]},{"id":"1-3-3","b":1,"l":3,"k":"","t":{"es":"Orden de 也, 都, 常","en":"The Word Order of Adverbs 也 yě,都 dōu and 常 cháng","ens":"The Word Order of Adverbs 也 yě,都 dōu and 常 cháng","tc":"副詞順序：也、都、常","sc":"副词顺序：也、都、常"},"d":{"es":"Los adverbios 也, 都 y 常 van después del sujeto y antes del verbo. Si aparecen 也 y 都 juntos, 也 va primero.","en":"The adverbs 也, 都 and 常 go after the subject and before the verb. When 也 and 都 appear together, 也 comes first.","tc":"「也」「都」「常」放在主詞後面、動詞前面。「也」和「都」一起用時，「也」在前面。","sc":"「也」「都」「常」放在主词后面、动词前面。「也」和「都」一起用时，「也」在前面。"},"ex":[{"c":"我們也都喜歡吃麵。","s":"我们也都喜欢吃面。","es":"A nosotros también nos gusta a todos comer fideos.","en":"We all like eating noodles too.","p":"wǒ men yě dōu xǐ huān chī miàn."}]},{"id":"1-3-4","b":1,"l":3,"k":"sugerencia proposición suggestion 建議 sugerencia proposición suggestion 建议","t":{"es":"Sugerencias con 吧","en":"Making Suggestions 吧 ba","ens":"Making Suggestions 吧 ba","tc":"用「吧」提出建議","sc":"用「吧」提出建议"},"d":{"es":"吧 al final de la oración hace una sugerencia o invitación suave: «vamos a…», «¿qué tal si…?».","en":"Adding 吧 at the end makes a gentle suggestion or invitation: 'let's …', 'how about …?'.","tc":"句尾加「吧」，語氣比較輕，是在提議或邀請：「我們……吧」。","sc":"句尾加「吧」，语气比较轻，是在提议或邀请：「我们……吧」。"},"ex":[{"c":"我們去吃飯吧。","s":"我们去吃饭吧。","es":"Vamos a comer.","en":"Let's go eat.","p":"wǒ men qù chī fàn ba."}]},{"id":"1-4-0","b":1,"l":4,"k":"clasificador clasificadores medida contar cantidad measure word classifier counter 量詞 clasificador clasificadores medida contar cantidad measure word classifier counter 量词","t":{"es":"Clasificadores 塊, 杯, 支, 種","en":"Measures 塊 kuài, 杯 bēi,支 zhī and 種 zhǒng","ens":"Measures 块 kuài, 杯 bēi,支 zhī and 种 zhǒng","tc":"量詞：塊、杯、支、種","sc":"量词：块、杯、支、种"},"d":{"es":"塊 para dinero; 杯 para bebidas en vaso o taza; 支 para objetos largos y delgados (lápiz, bolígrafo); 種 = tipo, clase.","en":"塊 is for money; 杯 for drinks in a cup or glass; 支 for long, thin objects (pens, pencils); 種 means 'kind, type'.","tc":"「塊」用在錢；「杯」用在杯子裝的飲料；「支」用在細長的東西（筆）；「種」是「種類」。","sc":"「块」用在钱；「杯」用在杯子装的饮料；「支」用在细长的东西（笔）；「种」是「种类」。"},"ex":[{"c":"一杯咖啡、兩支筆、三種水果、五十塊","s":"一杯咖啡、两支笔、三种水果、五十块","es":"una taza de café, dos bolígrafos, tres tipos de fruta, cincuenta dólares","en":"a cup of coffee, two pens, three kinds of fruit, fifty dollars","p":"yì bēi kā fēi, liǎng zhī bǐ, sān zhǒng shuǐ guǒ, wǔ shí kuài"}]},{"id":"1-4-1","b":1,"l":4,"k":"","t":{"es":"Hacer algo por alguien: 幫","en":"Preposition 幫 bāng on behalf of","ens":"Preposition 帮 bāng on behalf of","tc":"「幫」：替別人做","sc":"「帮」：替别人做"},"d":{"es":"幫 + persona + verbo = hacer algo por alguien / en su lugar.","en":"幫 + person + verb means doing something for someone.","tc":"「幫＋人＋動詞」表示替某人做某件事。","sc":"「帮＋人＋动词」表示替某人做某件事。"},"ex":[{"c":"我幫你買咖啡。","s":"我帮你买咖啡。","es":"Te compro el café.","en":"I'll buy you a coffee.","p":"wǒ bāng nǐ mǎi kā fēi."}]},{"id":"1-4-2","b":1,"l":4,"k":"","t":{"es":"Omitir el sustantivo: …的","en":"的 De-phrase with the Head Noun Omitted","ens":"的 De-phrase with the Head Noun Omitted","tc":"省略名詞的「的」","sc":"省略名词的「的」"},"d":{"es":"Cuando ya se sabe de qué sustantivo se habla, se omite y queda «modificador + 的»: «el/la/los de…».","en":"When it's clear what noun is meant, you can drop it and keep 'modifier + 的': 'the one that is …'.","tc":"已經知道在說什麼東西時，可以把名詞省略，只留下「修飾語＋的」，意思是「……的那個」。","sc":"已经知道在说什么东西时，可以把名词省略，只留下「修饰语＋的」，意思是「……的那个」。"},"ex":[{"c":"這杯是我的。","s":"这杯是我的。","es":"Esta taza es la mía.","en":"This cup is mine.","p":"zhè bēi shì wǒ de."},{"c":"紅色的比較貴。","s":"红色的比较贵。","es":"El rojo es más caro.","en":"The red one is more expensive.","p":"hóng sè de bǐ jiào guì."}]},{"id":"1-4-3","b":1,"l":4,"k":"","t":{"es":"Demasiado: 太…了","en":"太…了 tài…le overly","ens":"太…了 tài…le overly","tc":"太……了","sc":"太……了"},"d":{"es":"太 + adjetivo + 了 = demasiado… (a veces solo exclamación: «¡qué… !»).","en":"太 + adjective + 了 means 'too …' (sometimes just an exclamation: 'so …!').","tc":"「太＋形容詞＋了」是「太……了」，有時只是感嘆，意思是「真是……啊」。","sc":"「太＋形容词＋了」是「太……了」，有时只是感叹，意思是「真是……啊」。"},"ex":[{"c":"這個太貴了！","s":"这个太贵了！","es":"¡Esto es demasiado caro!","en":"This is too expensive!","p":"zhè ge tài guì le!"}]},{"id":"1-4-4","b":1,"l":4,"k":"poder saber habilidad capacidad permiso posibilidad ability can permission possibility 能力 可能 許可 poder saber habilidad capacidad permiso posibilidad ability can permission possibility 能力 可能 许可","t":{"es":"Poder con 能","en":"能 néng capability","ens":"能 néng capability","tc":"「能」：可以、有能力","sc":"「能」：可以、有能力"},"d":{"es":"能 expresa capacidad o posibilidad: «puedo», «es posible». Negación: 不能.","en":"能 expresses ability or possibility ('can'). The negative is 不能.","tc":"「能」表示有能力或有可能做某件事。否定是「不能」。","sc":"「能」表示有能力或有可能做某件事。否定是「不能」。"},"ex":[{"c":"你明天能來嗎？","s":"你明天能来吗？","es":"¿Puedes venir mañana?","en":"Can you come tomorrow?","p":"nǐ míng tiān néng lái ma?"}]},{"id":"1-4-5","b":1,"l":4,"k":"","t":{"es":"Y pico: 多","en":"多 duō …and more","ens":"多 duō …and more","tc":"數字後面的「多」","sc":"数字后面的「多」"},"d":{"es":"Después de un número, 多 significa «y pico, más de». También se usa en preguntas de grado: 多大, 多高, 多久.","en":"After a number, 多 means 'more than'. It is also used in degree questions: 多大, 多高, 多久.","tc":"數字後面加「多」，意思是「超過」。也用在問程度的問句：多大、多高、多久。","sc":"数字后面加「多」，意思是「超过」。也用在问程度的问句：多大、多高、多久。"},"ex":[{"c":"我有三十多本書。","s":"我有三十多本书。","es":"Tengo más de treinta libros.","en":"I have more than thirty books.","p":"wǒ yǒu sān shí duō běn shū."}]},{"id":"1-5-0","b":1,"l":5,"k":"","t":{"es":"Un poco: 有一點","en":"有一點 yǒu yìdiǎn slightly","ens":"有一点 yǒu yìdiǎn slightly","tc":"有一點","sc":"有一点"},"d":{"es":"有一點 + adjetivo = un poco, algo. Suele expresar algo que no es del todo agradable.","en":"有一點 + adjective means 'a little, somewhat', usually about something not quite pleasant.","tc":"「有一點＋形容詞」是「有點……」，通常表示不太滿意的感覺。","sc":"「有一点＋形容词」是「有点……」，通常表示不太满意的感觉。"},"ex":[{"c":"今天有一點冷。","s":"今天有一点冷。","es":"Hoy hace un poco de frío.","en":"It's a little cold today.","p":"jīn tiān yǒu yì diǎn lěng."}]},{"id":"1-5-1","b":1,"l":5,"k":"complemento resultado potencial complement result potential 補語 結果補語 可能補語 complemento resultado potencial complement result potential 补语 结果补语 可能补语","t":{"es":"Verbo + 得 + adjetivo","en":"Complement Marker 得 de","ens":"Complement Marker 得 de","tc":"程度補語「得」","sc":"程度补语「得」"},"d":{"es":"Verbo + 得 + adjetivo describe cómo se hace la acción. Si hay objeto, se repite el verbo.","en":"Verb + 得 + adjective describes how an action is done. If there is an object, the verb is repeated.","tc":"「動詞＋得＋形容詞」說明動作做得怎麼樣。如果有受詞，要先重複一次動詞。","sc":"「动词＋得＋形容词」说明动作做得怎么样。如果有受词，要先重复一次动词。"},"ex":[{"c":"他跑得很快。","s":"他跑得很快。","es":"Corre muy rápido.","en":"He runs very fast.","p":"tā pǎo de hěn kuài."},{"c":"他說中文說得很好。","s":"他说中文说得很好。","es":"Habla muy bien el chino.","en":"He speaks Chinese very well.","p":"tā shuō zhōng wén shuō de hěn hǎo."}]},{"id":"1-5-2","b":1,"l":5,"k":"poder saber habilidad capacidad permiso posibilidad ability can permission possibility 能力 可能 許可 poder saber habilidad capacidad permiso posibilidad ability can permission possibility 能力 可能 许可","t":{"es":"Saber hacer: 會","en":"Acquired Skills 會 huì","ens":"Acquired Skills 会 huì","tc":"「會」：學會的能力","sc":"「会」：学会的能力"},"d":{"es":"會 = saber hacer algo (habilidad aprendida). Negación: 不會.","en":"會 means knowing how to do something (a learned skill). The negative is 不會.","tc":"「會」表示學過、懂得怎麼做。否定是「不會」。","sc":"「会」表示学过、懂得怎么做。否定是「不会」。"},"ex":[{"c":"我會說中文。","s":"我会说中文。","es":"Sé hablar chino.","en":"I can speak Chinese.","p":"wǒ huì shuō zhōng wén."}]},{"id":"1-5-3","b":1,"l":5,"k":"","t":{"es":"Destino con 到","en":"Destination Marker 到 dào","ens":"Destination Marker 到 dào","tc":"「到」：到達的地方","sc":"「到」：到达的地方"},"d":{"es":"Verbo de movimiento + 到 + lugar: llegar hasta / ir hasta. 到 marca el destino.","en":"Movement verb + 到 + place means reaching or going as far as a place; 到 marks the destination.","tc":"「移動動詞＋到＋地方」表示去到、走到某個地方，「到」標示目的地。","sc":"「移动动词＋到＋地方」表示去到、走到某个地方，「到」标示目的地。"},"ex":[{"c":"他們開車到高雄。","s":"他们开车到高雄。","es":"Ellos van en coche hasta Kaohsiung.","en":"They drive to Kaohsiung.","p":"tā men kāi chē dào gāo xióng."}]},{"id":"1-6-0","b":1,"l":6,"k":"progresivo continuo estar haciendo presente progressive continuous ongoing 進行 持續 lugar ubicación dónde existencia hay location place existence where 地點 位置 存在 progresivo continuo estar haciendo presente progressive continuous ongoing 进行 持续 lugar ubicación dónde existencia hay location place existence where 地点 位置 存在","t":{"es":"Ubicación con 在","en":"Locative Marker 在 zài","ens":"Locative Marker 在 zài","tc":"「在」：在哪裡","sc":"「在」：在哪里"},"d":{"es":"Sujeto + 在 + lugar indica dónde está algo o alguien (algo que ya se conoce).","en":"Subject + 在 + place tells where someone or something is (something already known).","tc":"「主詞＋在＋地方」說明某人或某物在哪裡（說的是已經知道的人或東西）。","sc":"「主词＋在＋地方」说明某人或某物在哪里（说的是已经知道的人或东西）。"},"ex":[{"c":"我的手機在桌子上。","s":"我的手机在桌子上。","es":"Mi celular está sobre la mesa.","en":"My phone is on the table.","p":"wǒ de shǒu jī zài zhuō zi shàng."}]},{"id":"1-6-1","b":1,"l":6,"k":"lugar ubicación dónde existencia hay location place existence where 地點 位置 存在 lugar ubicación dónde existencia hay location place existence where 地点 位置 存在","t":{"es":"Hay: lugar + 有","en":"Existential Sentence with 有 yǒu","ens":"Existential Sentence with 有 yǒu","tc":"「有」：存在句","sc":"「有」：存在句"},"d":{"es":"Lugar + 有 + cosa/persona = en ese lugar hay algo. Contraste: 在 (algo conocido está en…) vs. 有 (en un lugar hay algo).","en":"Place + 有 + thing/person means 'there is …' in that place. Contrast: 在 (a known thing is at …) vs. 有 (a place has …).","tc":"「地方＋有＋東西／人」表示那裡有什麼。比較：「在」是已知的東西在哪裡；「有」是某個地方有什麼。","sc":"「地方＋有＋东西／人」表示那里有什么。比较：「在」是已知的东西在哪里；「有」是某个地方有什么。"},"ex":[{"c":"桌子上有一本書。","s":"桌子上有一本书。","es":"Sobre la mesa hay un libro.","en":"There is a book on the table.","p":"zhuō zi shàng yǒu yì běn shū."}]},{"id":"1-6-2","b":1,"l":6,"k":"","t":{"es":"Suavizar: V(一)V","en":"Softened Action V（一）V","ens":"Softened Action V（一）V","tc":"動詞重複：V(一)V","sc":"动词重复：V(一)V"},"d":{"es":"Repetir el verbo (V一V / VV) suaviza la acción: «un poquito», «probar». Se usa con acciones cortas.","en":"Repeating the verb (V一V / VV) softens the action: 'a little', 'give it a try'. It is used with short actions.","tc":"動詞重複（V一V、VV）讓語氣變輕，意思是「稍微做一下」「試試看」，多用在短短的動作。","sc":"动词重复（V一V、VV）让语气变轻，意思是「稍微做一下」「试试看」，多用在短短的动作。"},"ex":[{"c":"你看(一)看。","s":"你看(一)看。","es":"Echa un vistazo.","en":"Take a look.","p":"nǐ kàn (yī) kàn."},{"c":"讓我想一想。","s":"让我想一想。","es":"Déjame pensarlo un momento.","en":"Let me think about it for a moment.","p":"ràng wǒ xiǎng yì xiǎng."}]},{"id":"1-6-3","b":1,"l":6,"k":"negación negar negativa negation negative 否定 negación negar negativa negation negative 否定","t":{"es":"Negar con 不是","en":"不是 búshì Negation","ens":"不是 búshì Negation","tc":"「不是」：否定名詞","sc":"「不是」：否定名词"},"d":{"es":"不是 niega 是 y sirve para corregir: «no es X (sino Y)». Se usa para negar sustantivos.","en":"不是 negates 是 and is used to correct: 'it's not X, it's Y'. It negates nouns.","tc":"「不是」否定「是」，也用來更正：「不是 X，是 Y」。用來否定名詞。","sc":"「不是」否定「是」，也用来更正：「不是 X，是 Y」。用来否定名词。"},"ex":[{"c":"我不是老師，我是學生。","s":"我不是老师，我是学生。","es":"No soy profesor, soy estudiante.","en":"I'm not a teacher, I'm a student.","p":"wǒ bú shì lǎo shī, wǒ shì xué shēng."}]},{"id":"1-6-4","b":1,"l":6,"k":"lugar ubicación dónde existencia hay location place existence where 地點 位置 存在 lugar ubicación dónde existencia hay location place existence where 地点 位置 存在","t":{"es":"Lugar de la actividad","en":"Location of an Activity","ens":"Location of an Activity","tc":"動作發生的地點","sc":"动作发生的地点"},"d":{"es":"El lugar donde ocurre la actividad va con 在 antes del verbo: 在 + lugar + verbo.","en":"The place where an activity happens is marked with 在 + place, before the verb.","tc":"動作發生的地點用「在＋地方」，放在動詞前面。","sc":"动作发生的地点用「在＋地方」，放在动词前面。"},"ex":[{"c":"我在家看書。","s":"我在家看书。","es":"Leo en casa.","en":"I read at home.","p":"wǒ zài jiā kàn shū."}]},{"id":"1-7-0","b":1,"l":7,"k":"tiempo momento orden secuencia time order sequence 時間 順序 lugar ubicación dónde existencia hay location place existence where 地點 位置 存在 tiempo momento orden secuencia time order sequence 时间 顺序 lugar ubicación dónde existencia hay location place existence where 地点 位置 存在","t":{"es":"Tiempo y lugar","en":"Time and Place of Events","ens":"Time and Place of Events","tc":"時間和地點的順序","sc":"时间和地点的顺序"},"d":{"es":"Orden básico: sujeto + tiempo + lugar + verbo.","en":"Basic order: subject + time + place + verb.","tc":"基本順序是：主詞＋時間＋地點＋動詞。","sc":"基本顺序是：主词＋时间＋地点＋动词。"},"ex":[{"c":"我昨天在家看電影。","s":"我昨天在家看电影。","es":"Ayer vi una película en casa.","en":"I watched a movie at home yesterday.","p":"wǒ zuó tiān zài jiā kàn diàn yǐng."}]},{"id":"1-7-1","b":1,"l":7,"k":"lugar ubicación dónde existencia hay location place existence where 地點 位置 存在 lugar ubicación dónde existencia hay location place existence where 地点 位置 存在","t":{"es":"De A a B: 從…到…","en":"從 cóng…到 dào… from A to B","ens":"从 cóng…到 dào… from A to B","tc":"從……到……","sc":"从……到……"},"d":{"es":"從 A 到 B = de A a B (para lugares o tiempos).","en":"從 A 到 B means 'from A to B', for places or times.","tc":"「從 A 到 B」表示從 A 到 B，可以用在地點或時間。","sc":"「从 A 到 B」表示从 A 到 B，可以用在地点或时间。"},"ex":[{"c":"從台北到高雄","s":"从台北到高雄","es":"de Taipéi a Kaohsiung","en":"from Taipei to Kaohsiung","p":"cóng tái běi dào gāo xióng"},{"c":"我從九點到十二點上課。","s":"我从九点到十二点上课。","es":"Tengo clase de nueve a doce.","en":"I have class from nine to twelve.","p":"wǒ cóng jiǔ diǎn dào shí èr diǎn shàng kè."}]},{"id":"1-7-2","b":1,"l":7,"k":"progresivo continuo estar haciendo presente progressive continuous ongoing 進行 持續 progresivo continuo estar haciendo presente progressive continuous ongoing 进行 持续","t":{"es":"Acción en curso: 在","en":"Progressive, On-going Actions 在 zài","ens":"Progressive, On-going Actions 在 zài","tc":"正在做：在","sc":"正在做：在"},"d":{"es":"(正)在 + verbo = estar haciendo algo (acción en curso). Puede terminar con 呢.","en":"(正)在 + verb shows an action in progress ('be doing'). 呢 can be added at the end.","tc":"「(正)在＋動詞」表示動作正在進行。句尾可以加「呢」。","sc":"「(正)在＋动词」表示动作正在进行。句尾可以加「呢」。"},"ex":[{"c":"我在吃飯。","s":"我在吃饭。","es":"Estoy comiendo.","en":"I'm eating.","p":"wǒ zài chī fàn."}]},{"id":"1-7-3","b":1,"l":7,"k":"siempre nunca frecuencia always never frequency 經常 從來 siempre nunca frecuencia always never frequency 经常 从来","t":{"es":"Cada: 每","en":"每 měi each and every","ens":"每 měi each and every","tc":"「每」：每一個","sc":"「每」：每一个"},"d":{"es":"每 + clasificador / palabra de tiempo = cada, todos los. Suele ir con 都 antes del verbo.","en":"每 + measure word/time word means 'every, each'. It often goes with 都 before the verb.","tc":"「每＋量詞／時間詞」是「每一……」。常常和「都」一起放在動詞前面。","sc":"「每＋量词／时间词」是「每一……」。常常和「都」一起放在动词前面。"},"ex":[{"c":"我每天都喝咖啡。","s":"我每天都喝咖啡。","es":"Tomo café todos los días.","en":"I drink coffee every day.","p":"wǒ měi tiān dōu hē kā fēi."}]},{"id":"1-7-4","b":1,"l":7,"k":"poder saber habilidad capacidad permiso posibilidad ability can permission possibility 能力 可能 許可 poder saber habilidad capacidad permiso posibilidad ability can permission possibility 能力 可能 许可","t":{"es":"Permiso con 可以","en":"可以 kěyǐ permission","ens":"可以 kěyǐ permission","tc":"「可以」：許可","sc":"「可以」：许可"},"d":{"es":"可以 = permiso: «se puede / puedo». Para pedir permiso: 可以…嗎？ Prohibición: 不可以.","en":"可以 expresses permission ('may, can'). To ask for permission: 可以…嗎？ Prohibition: 不可以.","tc":"「可以」表示可以做某事（許可）。問許可：「可以……嗎？」。不可以：「不可以」。","sc":"「可以」表示可以做某事（许可）。问许可：「可以……吗？」。不可以：「不可以」。"},"ex":[{"c":"這裡可以拍照嗎？","s":"这里可以拍照吗？","es":"¿Se pueden tomar fotos aquí?","en":"Can we take photos here?","p":"zhè lǐ kě yǐ pāi zhào ma?"}]},{"id":"1-8-0","b":1,"l":8,"k":"","t":{"es":"Compañía con 跟","en":"Companionship with 跟 gēn","ens":"Companionship with 跟 gēn","tc":"「跟」：一起做","sc":"「跟」：一起做"},"d":{"es":"A 跟 B 一起 + verbo = hacer algo con B.","en":"A 跟 B 一起 + verb means doing something together with B.","tc":"「A 跟 B 一起＋動詞」表示和 B 一起做某件事。","sc":"「A 跟 B 一起＋动词」表示和 B 一起做某件事。"},"ex":[{"c":"我跟朋友一起去看電影。","s":"我跟朋友一起去看电影。","es":"Voy al cine con mis amigos.","en":"I go to the movies with my friends.","p":"wǒ gēn péng yǒu yì qǐ qù kàn diàn yǐng."}]},{"id":"1-8-1","b":1,"l":8,"k":"pregunta preguntar interrogativa question ask 疑問 問句 提問 pregunta preguntar interrogativa question ask 疑问 问句 提问","t":{"es":"Cómo con 怎麼","en":"Asking How with 怎麼 zěnme","ens":"Asking How with 怎么 zěnme","tc":"「怎麼」：怎樣做","sc":"「怎么」：怎样做"},"d":{"es":"怎麼 + verbo pregunta por la manera o el método de hacer algo.","en":"怎麼 + verb asks how to do something (the method).","tc":"「怎麼＋動詞」問做某件事的方法或方式。","sc":"「怎么＋动词」问做某件事的方法或方式。"},"ex":[{"c":"這個字怎麼念？","s":"这个字怎么念？","es":"¿Cómo se pronuncia este carácter?","en":"How do you pronounce this character?","p":"zhè ge zì zěn me niàn?"},{"c":"去台北車站怎麼走？","s":"去台北车站怎么走？","es":"¿Cómo se va a la estación de Taipéi?","en":"How do I get to Taipei Main Station?","p":"qù tái běi chē zhàn zěn me zǒu?"}]},{"id":"1-8-2","b":1,"l":8,"k":"comparar comparación comparativo más menos igual semejante comparison compare comparative 比較 比較級 comparar comparación comparativo más menos igual semejante comparison compare comparative 比较 比较级","t":{"es":"Comparación con 比較","en":"Implicit Comparison with 比較 bǐjiào","ens":"Implicit Comparison with 比较 bǐjiào","tc":"「比較」：比較級","sc":"「比较」：比较级"},"d":{"es":"比較 + adjetivo/verbo = «más» o «relativamente»; es una comparación implícita, sin decir con qué se compara.","en":"比較 + adjective/verb means 'more …' or 'relatively …'. It is an implicit comparison; you don't say what it's compared to.","tc":"「比較＋形容詞／動詞」是「比較……」，不用說出跟誰比，是隱含的比較。","sc":"「比较＋形容词／动词」是「比较……」，不用说出跟谁比，是隐含的比较。"},"ex":[{"c":"我比較喜歡喝茶。","s":"我比较喜欢喝茶。","es":"Prefiero tomar té.","en":"I prefer drinking tea.","p":"wǒ bǐ jiào xǐ huān hē chá."}]},{"id":"1-8-3","b":1,"l":8,"k":"","t":{"es":"Ambas cualidades: 又…又…","en":"又 yòu…又 yòu…… both A and B","ens":"又 yòu…又 yòu…… both A and B","tc":"又……又……","sc":"又……又……"},"d":{"es":"又 A 又 B = a la vez A y B (dos cualidades juntas).","en":"又 A 又 B means both A and B at the same time (two qualities together).","tc":"「又 A 又 B」表示同時有 A 和 B 兩個特點。","sc":"「又 A 又 B」表示同时有 A 和 B 两个特点。"},"ex":[{"c":"這家的菜又好吃又便宜。","s":"这家的菜又好吃又便宜。","es":"La comida de este lugar es rica y barata.","en":"The food at this place is both tasty and cheap.","p":"zhè jiā de cài yòu hǎo chī yòu pián yí."}]},{"id":"1-8-4","b":1,"l":8,"k":"comparar comparación comparativo más menos igual semejante comparison compare comparative 比較 比較級 comparar comparación comparativo más menos igual semejante comparison compare comparative 比较 比较级","t":{"es":"Comparar con 比","en":"Comparison with 比 bǐ","ens":"Comparison with 比 bǐ","tc":"比較句：A 比 B","sc":"比较句：A 比 B"},"d":{"es":"A 比 B + adjetivo = A es más… que B. Con 比 no se usa 很. Para indicar la diferencia: 一點 / 多了 / 三歲, etc.","en":"A 比 B + adjective means A is more … than B. Don't use 很 with 比. To say how much the difference is, add 一點 / 多了 / an amount.","tc":"「A 比 B＋形容詞」表示 A 比 B 更……。用「比」的時候不加「很」。要說差多少，可以加「一點」「多了」或數量。","sc":"「A 比 B＋形容词」表示 A 比 B 更……。用「比」的时候不加「很」。要说差多少，可以加「一点」「多了」或数量。"},"ex":[{"c":"哥哥比我高。","s":"哥哥比我高。","es":"Mi hermano mayor es más alto que yo.","en":"My older brother is taller than I am.","p":"gē ge bǐ wǒ gāo."},{"c":"他比我大三歲。","s":"他比我大三岁。","es":"Es tres años mayor que yo.","en":"He is three years older than I am.","p":"tā bǐ wǒ dà sān suì."}]},{"id":"1-9-0","b":1,"l":9,"k":"tiempo momento orden secuencia time order sequence 時間 順序 tiempo momento orden secuencia time order sequence 时间 顺序","t":{"es":"Momento vs. duración","en":"Time-When vs. Time-Duration","ens":"Time-When vs. Time-Duration","tc":"時間點和時間長度","sc":"时间点和时间长度"},"d":{"es":"El momento (cuándo) va antes del verbo; la duración (cuánto tiempo) va después del verbo.","en":"When something happens (a point in time) goes before the verb; how long it lasts (duration) goes after the verb.","tc":"「什麼時候」（時間點）放在動詞前面；「多久」（時間長度）放在動詞後面。","sc":"「什么时候」（时间点）放在动词前面；「多久」（时间长度）放在动词后面。"},"ex":[{"c":"我八點上課。","s":"我八点上课。","es":"Tengo clase a las ocho.","en":"I have class at eight.","p":"wǒ bā diǎn shàng kè."},{"c":"我每天睡八個小時。","s":"我每天睡八个小时。","es":"Duermo ocho horas al día.","en":"I sleep eight hours a day.","p":"wǒ měi tiān shuì bā ge xiǎo shí."}]},{"id":"1-9-1","b":1,"l":9,"k":"tiempo momento orden secuencia time order sequence 時間 順序 tiempo momento orden secuencia time order sequence 时间 顺序","t":{"es":"Duración de la acción","en":"Time-Duration ‘for a period of time’","ens":"Time-Duration ‘for a period of time’","tc":"動作持續的時間","sc":"动作持续的时间"},"d":{"es":"Verbo + duración (+ 的 + objeto) indica cuánto tiempo dura la acción.","en":"Verb + duration (+ 的 + object) tells how long the action lasts.","tc":"「動詞＋時間長度（＋的＋受詞）」表示動作持續多久。","sc":"「动词＋时间长度（＋的＋受词）」表示动作持续多久。"},"ex":[{"c":"我想在台灣住三個月。","s":"我想在台湾住三个月。","es":"Quiero vivir tres meses en Taiwán.","en":"I'd like to live in Taiwan for three months.","p":"wǒ xiǎng zài tái wān zhù sān ge yuè."}]},{"id":"1-9-2","b":1,"l":9,"k":"tiempo momento orden secuencia time order sequence 時間 順序 tiempo momento orden secuencia time order sequence 时间 顺序","t":{"es":"Cuando: …的時候","en":"…的時候 de shíhòu when","ens":"…的时候 de shíhòu when","tc":"「……的時候」","sc":"「……的时候」"},"d":{"es":"Frase + 的時候 = cuando… (en el momento en que ocurre algo).","en":"Clause + 的時候 means 'when …' (at the time the action happens).","tc":"「一段話＋的時候」表示「當……的時候」，說明動作發生的那段時間。","sc":"「一段话＋的时候」表示「当……的时候」，说明动作发生的那段时间。"},"ex":[{"c":"我吃飯的時候不看手機。","s":"我吃饭的时候不看手机。","es":"Cuando como no miro el celular.","en":"I don't look at my phone when I eat.","p":"wǒ chī fàn de shí hòu bú kàn shǒu jī."}]},{"id":"1-9-3","b":1,"l":9,"k":"tiempo momento orden secuencia time order sequence 時間 順序 tiempo momento orden secuencia time order sequence 时间 顺序","t":{"es":"A veces… a veces…","en":"有時候 yǒu shíhòu…有時候 yǒu shíhòu… sometimes … sometimes …","ens":"有时候 yǒu shíhòu…有时候 yǒu shíhòu… sometimes … sometimes …","tc":"有時候……有時候……","sc":"有时候……有时候……"},"d":{"es":"有時候 A，有時候 B = a veces A, a veces B.","en":"有時候 A，有時候 B means 'sometimes A, sometimes B'.","tc":"「有時候 A，有時候 B」表示有時候做 A，有時候做 B。","sc":"「有时候 A，有时候 B」表示有时候做 A，有时候做 B。"},"ex":[{"c":"我有時候喝茶，有時候喝咖啡。","s":"我有时候喝茶，有时候喝咖啡。","es":"A veces tomo té y a veces café.","en":"Sometimes I drink tea and sometimes coffee.","p":"wǒ yǒu shí hòu hē chá, yǒu shí hòu hē kā fēi."}]},{"id":"1-9-4","b":1,"l":9,"k":"tiempo momento orden secuencia time order sequence 時間 順序 condicional condición si conditional condition if 條件 假設 如果 causa razón porque consecuencia resultado cause reason because consequence result 原因 結果 因果 tiempo momento orden secuencia time order sequence 时间 顺序 condicional condición si conditional condition if 条件 假设 如果 causa razón porque consecuencia resultado cause reason because consequence result 原因 结果 因果","t":{"es":"Si…, entonces: 要是…就","en":"Condition and Consequence with 要是 yaoshi…就 jiu…","ens":"Condition and Consequence with 要是 yaoshi…就 jiu…","tc":"要是……就……","sc":"要是……就……"},"d":{"es":"要是 + condición，就 + resultado = si…, entonces…. 就 va antes del verbo.","en":"要是 + condition, 就 + result means 'if …, then …'. 就 goes before the verb.","tc":"「要是＋條件，就＋結果」表示「如果……就……」。「就」放在動詞前面。","sc":"「要是＋条件，就＋结果」表示「如果……就……」。「就」放在动词前面。"},"ex":[{"c":"要是下雨，我就不去。","s":"要是下雨，我就不去。","es":"Si llueve, no voy.","en":"If it rains, I won't go.","p":"yào shì xià yǔ, wǒ jiù bú qù."}]},{"id":"1-10-0","b":1,"l":10,"k":"","t":{"es":"Probar: V V 看","en":"V V 看 kàn to try and see","ens":"V V 看 kàn to try and see","tc":"動詞重複＋「看」","sc":"动词重复＋「看」"},"d":{"es":"Verbo repetido + 看 = probar a hacer algo para ver qué tal.","en":"Repeated verb + 看 means 'try doing it and see how it goes'.","tc":"「動詞重複＋看」表示試試看，看看會怎麼樣。","sc":"「动词重复＋看」表示试试看，看看会怎么样。"},"ex":[{"c":"這個很好吃，你吃吃看。","s":"这个很好吃，你吃吃看。","es":"Esto está muy rico, pruébalo.","en":"This is very tasty, try it.","p":"zhè ge hěn hǎo chī, nǐ chī chī kàn."}]},{"id":"1-10-1","b":1,"l":10,"k":"reduplicación repetición reduplication repetition 重疊 reduplicación repetición reduplication repetition 重叠","t":{"es":"Adjetivos duplicados","en":"Intensification with Reduplicated State Verbs","ens":"Intensification with Reduplicated State Verbs","tc":"形容詞重疊","sc":"形容词重叠"},"d":{"es":"Duplicar un adjetivo (AA) lo hace más vívido; ya no se le pone 很. Para adjetivos de dos sílabas se usa AABB.","en":"Doubling an adjective (AA) makes it more vivid and no 很 is added. Two-syllable adjectives are doubled as AABB.","tc":"形容詞重疊（AA）會更生動，不再加「很」。兩個字的形容詞要重疊成 AABB。","sc":"形容词重叠（AA）会更生动，不再加「很」。两个字的形容词要重叠成 AABB。"},"ex":[{"c":"她的眼睛大大的。","s":"她的眼睛大大的。","es":"Tiene los ojos bien grandes.","en":"Her eyes are big and round.","p":"tā de yǎn jīng dà dà de."}]},{"id":"1-10-2","b":1,"l":10,"k":"","t":{"es":"Oración como modificador","en":"Clause as Modifiers of Nouns","ens":"Clause as Modifiers of Nouns","tc":"用一句話修飾名詞","sc":"用一句话修饰名词"},"d":{"es":"Una frase u oración + 的 + sustantivo: la descripción siempre va antes del sustantivo (como una cláusula de relativo).","en":"Clause + 的 + noun: the description always comes before the noun (like a relative clause).","tc":"「一句話＋的＋名詞」，說明的話一定放在名詞前面（像關係子句）。","sc":"「一句话＋的＋名词」，说明的话一定放在名词前面（像关系子句）。"},"ex":[{"c":"我喜歡的老師很年輕。","s":"我喜欢的老师很年轻。","es":"El profesor que me gusta es muy joven.","en":"The teacher I like is very young.","p":"wǒ xǐ huān de lǎo shī hěn nián qīng."}]},{"id":"1-10-3","b":1,"l":10,"k":"","t":{"es":"Cambio con 了","en":"Change in Situation with Sentential 了 le","ens":"Change in Situation with Sentential 了 le","tc":"句尾「了」：新的狀況","sc":"句尾「了」：新的状况"},"d":{"es":"了 al final de la oración indica un cambio de situación o un estado nuevo: «ya», «ahora ya».","en":"了 at the end of a sentence shows a change of situation or a new state: 'now …', 'already …'.","tc":"句尾的「了」表示情況改變、出現新的狀態：「已經……了」「現在……了」。","sc":"句尾的「了」表示情况改变、出现新的状态：「已经……了」「现在……了」。"},"ex":[{"c":"我現在不累了。","s":"我现在不累了。","es":"Ya no estoy cansado.","en":"I'm not tired anymore.","p":"wǒ xiàn zài bú lèi le."},{"c":"天黑了。","s":"天黑了。","es":"Ya oscureció.","en":"It's gotten dark.","p":"tiān hēi le."}]},{"id":"1-10-4","b":1,"l":10,"k":"causa razón porque consecuencia resultado cause reason because consequence result 原因 結果 因果 causa razón porque consecuencia resultado cause reason because consequence result 原因 结果 因果","t":{"es":"Causa y efecto","en":"Cause and Effect with 因為 yīnwèi，所以 suǒyǐ","ens":"Cause and Effect with 因为 yīnwèi，所以 suǒyǐ","tc":"因為……所以……","sc":"因为……所以……"},"d":{"es":"因為 introduce la causa y 所以 el resultado. En chino se suelen usar juntos.","en":"因為 gives the reason and 所以 the result. In Chinese the two are often used together.","tc":"「因為」說原因，「所以」說結果。中文常常兩個一起用。","sc":"「因为」说原因，「所以」说结果。中文常常两个一起用。"},"ex":[{"c":"因為下雨，所以我不去。","s":"因为下雨，所以我不去。","es":"Como llueve, no voy.","en":"Because it's raining, I'm not going.","p":"yīn wèi xià yǔ, suǒ yǐ wǒ bú qù."}]},{"id":"1-11-0","b":1,"l":11,"k":"dirección movimiento direction movement 方向 趨向 dirección movimiento direction movement 方向 趋向","t":{"es":"Venir a hacer: 來","en":"To Come to Do Something with 來 lái","ens":"To Come to Do Something with 来 lái","tc":"「來」＋動作","sc":"「来」＋动作"},"d":{"es":"來 + verbo = venir a hacer algo (desde el punto de vista del lugar donde se habla).","en":"來 + verb means coming (to where the speaker is) to do something.","tc":"「來＋動詞」表示來到說話的人所在的地方做某件事。","sc":"「来＋动词」表示来到说话的人所在的地方做某件事。"},"ex":[{"c":"他來台灣學中文。","s":"他来台湾学中文。","es":"Él viene a Taiwán a estudiar chino.","en":"He comes to Taiwan to study Chinese.","p":"tā lái tái wān xué zhōng wén."}]},{"id":"1-11-1","b":1,"l":11,"k":"tiempo momento orden secuencia time order sequence 時間 順序 tiempo momento orden secuencia time order sequence 时间 顺序","t":{"es":"Más pronto: 就","en":"Sooner Than Expected with 就 jiù","ens":"Sooner Than Expected with 就 jiù","tc":"「就」：比預期早","sc":"「就」：比预期早"},"d":{"es":"Tiempo + 就 + verbo = la acción ocurre más temprano o más rápido de lo esperado.","en":"Time + 就 + verb shows the action happens earlier or sooner than expected.","tc":"「時間＋就＋動詞」表示動作比預期更早或更快發生。","sc":"「时间＋就＋动词」表示动作比预期更早或更快发生。"},"ex":[{"c":"我六點就起床了。","s":"我六点就起床了。","es":"Me levanté ya a las seis.","en":"I was already up at six.","p":"wǒ liù diǎn jiù qǐ chuáng le."}]},{"id":"1-11-2","b":1,"l":11,"k":"lugar ubicación dónde existencia hay location place existence where 地點 位置 存在 lugar ubicación dónde existencia hay location place existence where 地点 位置 存在","t":{"es":"Hay alguien que…","en":"Existential Subject with 有 yǒu","ens":"Existential Subject with 有 yǒu","tc":"「有」＋不確定的主詞","sc":"「有」＋不确定的主词"},"d":{"es":"有 + sujeto indefinido al inicio: «hay alguien/algo que…».","en":"Starting a sentence with 有 + an indefinite subject means 'there is someone/something that …'.","tc":"句首用「有＋不確定的人或東西」，意思是「有人／有東西……」。","sc":"句首用「有＋不确定的人或东西」，意思是「有人／有东西……」。"},"ex":[{"c":"有人找你。","s":"有人找你。","es":"Alguien te busca.","en":"Someone is looking for you.","p":"yǒu rén zhǎo nǐ."}]},{"id":"1-11-3","b":1,"l":11,"k":"poder saber habilidad capacidad permiso posibilidad ability can permission possibility 能力 可能 許可 poder saber habilidad capacidad permiso posibilidad ability can permission possibility 能力 可能 许可","t":{"es":"Usos de 會","en":"Different Types of 會 huì","ens":"Different Types of 会 huì","tc":"「會」的不同用法","sc":"「会」的不同用法"},"d":{"es":"會 también expresa probabilidad o futuro: «seguramente», «va a». No solo significa «saber hacer».","en":"Besides 'knowing how to', 會 also expresses probability or the future: 'will, is likely to'.","tc":"「會」除了「學會做某事」，也表示可能或將來：「應該會」「一定會」。","sc":"「会」除了「学会做某事」，也表示可能或将来：「应该会」「一定会」。"},"ex":[{"c":"明天會下雨。","s":"明天会下雨。","es":"Mañana va a llover.","en":"It will rain tomorrow.","p":"míng tiān huì xià yǔ."},{"c":"他會來嗎？","s":"他会来吗？","es":"¿Vendrá él?","en":"Will he come?","p":"tā huì lái ma?"}]},{"id":"1-11-4","b":1,"l":11,"k":"","t":{"es":"Omitir sustantivos","en":"Omitting Nouns at 2nd mention","ens":"Omitting Nouns at 2nd mention","tc":"第二次提到時省略名詞","sc":"第二次提到时省略名词"},"d":{"es":"Cuando el sustantivo ya se mencionó, la segunda vez se puede omitir.","en":"A noun that has already been mentioned can be omitted the second time.","tc":"已經提過的名詞，第二次說的時候可以省略。","sc":"已经提过的名词，第二次说的时候可以省略。"},"ex":[{"c":"這件太大了，有小的嗎？","s":"这件太大了，有小的吗？","es":"Esta es demasiado grande, ¿tiene una más pequeña?","en":"This one is too big. Do you have a smaller one?","p":"zhè jiàn tài dà le, yǒu xiǎo de ma?"}]},{"id":"1-12-0","b":1,"l":12,"k":"tiempo momento orden secuencia time order sequence 時間 順序 tiempo momento orden secuencia time order sequence 时间 顺序","t":{"es":"Primero… luego: 先…再…","en":"先 xiān…再 zài… first…, and then …","ens":"先 xiān…再 zài… first…, and then …","tc":"先……再……","sc":"先……再……"},"d":{"es":"先 A，再 B = primero A, luego B.","en":"先 A，再 B means 'first A, then B'.","tc":"「先 A，再 B」表示先做 A，然後做 B。","sc":"「先 A，再 B」表示先做 A，然后做 B。"},"ex":[{"c":"我們先吃飯，再看電影。","s":"我们先吃饭，再看电影。","es":"Primero comemos y luego vemos una película.","en":"Let's eat first and then watch a movie.","p":"wǒ men xiān chī fàn, zài kàn diàn yǐng."}]},{"id":"1-12-1","b":1,"l":12,"k":"","t":{"es":"Enfatizar con 是…的","en":"To Focus with 是 shì…的 de…","ens":"To Focus with 是 shì…的 de…","tc":"是……的","sc":"是……的"},"d":{"es":"是…的 destaca el cuándo, dónde, cómo o con quién de una acción que ya ocurrió.","en":"是…的 emphasizes the time, place, manner or companion of an action that has already happened.","tc":"「是……的」用來強調已經發生的動作的時間、地點、方式或一起去的人。","sc":"「是……的」用来强调已经发生的动作的时间、地点、方式或一起去的人。"},"ex":[{"c":"我是昨天來的。","s":"我是昨天来的。","es":"Vine ayer.","en":"I came yesterday.","p":"wǒ shì zuó tiān lái de."},{"c":"我是坐高鐵來的。","s":"我是坐高铁来的。","es":"Vine en el tren de alta velocidad.","en":"I came by high-speed rail.","p":"wǒ shì zuò gāo tiě lái de."}]},{"id":"1-12-2","b":1,"l":12,"k":"tiempo momento orden secuencia time order sequence 時間 順序 tiempo momento orden secuencia time order sequence 时间 顺序","t":{"es":"Después de: 以後","en":"以後 yǐhòu after…","ens":"以后 yǐhòu after…","tc":"「以後」","sc":"「以后」"},"d":{"es":"Tiempo / frase + 以後 = después de…. Solo, 以後 significa «en el futuro».","en":"Time/clause + 以後 means 'after …'. Used alone, 以後 means 'in the future'.","tc":"「時間／一段話＋以後」表示「在……之後」。單獨說「以後」是「未來」。","sc":"「时间／一段话＋以后」表示「在……之后」。单独说「以后」是「未来」。"},"ex":[{"c":"下課以後，我去吃飯。","s":"下课以后，我去吃饭。","es":"Después de clase voy a comer.","en":"After class, I'm going to eat.","p":"xià kè yǐ hòu, wǒ qù chī fàn."}]},{"id":"1-12-3","b":1,"l":12,"k":"","t":{"es":"好 / 難 + verbo","en":"Special Meanings of 好 hǎo/難 nán +Verbs","ens":"Special Meanings of 好 hǎo/难 nán +Verbs","tc":"「好／難＋動詞」","sc":"「好／难＋动词」"},"d":{"es":"好 + verbo = fácil / agradable de…: 好吃, 好看, 好用. 難 + verbo = difícil / desagradable de…: 難吃, 難看, 難用.","en":"好 + verb means easy or pleasant to … (好吃, 好看, 好用); 難 + verb means hard or unpleasant to … (難吃, 難看, 難用).","tc":"「好＋動詞」表示容易、好用或令人愉快（好吃、好看、好用）；「難＋動詞」表示不容易或不好（難吃、難看、難用）。","sc":"「好＋动词」表示容易、好用或令人愉快（好吃、好看、好用）；「难＋动词」表示不容易或不好（难吃、难看、难用）。"},"ex":[{"c":"這個手機很好用。","s":"这个手机很好用。","es":"Este celular es muy fácil de usar.","en":"This phone is very easy to use.","p":"zhè ge shǒu jī hěn hǎo yòng."},{"c":"這道菜很難吃。","s":"这道菜很难吃。","es":"Este platillo sabe mal.","en":"This dish tastes bad.","p":"zhè dào cài hěn nán chī."}]},{"id":"1-13-0","b":1,"l":13,"k":"tiempo momento orden secuencia time order sequence 時間 順序 tiempo momento orden secuencia time order sequence 时间 顺序","t":{"es":"En cuanto: 一…就…","en":"一 yī…就 jiù… …as soon as…","ens":"一 yī…就 jiù… …as soon as…","tc":"一……就……","sc":"一……就……"},"d":{"es":"一 A 就 B = en cuanto A, B.","en":"一 A 就 B means 'as soon as A, B'.","tc":"「一 A 就 B」表示一做完 A，馬上就 B。","sc":"「一 A 就 B」表示一做完 A，马上就 B。"},"ex":[{"c":"他一下課就回家。","s":"他一下课就回家。","es":"En cuanto termina la clase, se va a casa.","en":"He goes home as soon as class ends.","p":"tā yí xià kè jiù huí jiā."}]},{"id":"1-13-1","b":1,"l":13,"k":"pasado completado terminado past completed finished perfective 完成 過去 pasado completado terminado past completed finished perfective 完成 过去","t":{"es":"Acción completada: 了","en":"Completed Action with Verbal 了 le","ens":"Completed Action with Verbal 了 le","tc":"動作完成：「了」","sc":"动作完成：「了」"},"d":{"es":"Verbo + 了 indica que la acción se completó (no equivale a «pasado»). Suele haber una cantidad o complemento después.","en":"Verb + 了 shows the action is completed (it is not simply 'past tense'). It is usually followed by a quantity or other information.","tc":"「動詞＋了」表示動作已經完成，不等於過去式。後面通常有數量或其他補充說明。","sc":"「动词＋了」表示动作已经完成，不等于过去式。后面通常有数量或其他补充说明。"},"ex":[{"c":"我買了一本書。","s":"我买了一本书。","es":"Compré un libro.","en":"I bought a book.","p":"wǒ mǎi le yì běn shū."}]},{"id":"1-13-2","b":1,"l":13,"k":"negación negar negativa negation negative 否定 negación negar negativa negation negative 否定","t":{"es":"不 vs. 沒","en":"不 Negation vs.沒 Negation","ens":"不 Negation vs.没 Negation","tc":"「不」和「沒」的差別","sc":"「不」和「没」的差别"},"d":{"es":"不 niega hábitos, presente, futuro y voluntad. 沒(有) niega que una acción haya ocurrido, y niega 有. Con 沒 no se usa 了.","en":"不 negates habits, the present, the future and will. 沒(有) negates that an action took place, and negates 有. Don't use 了 with 沒.","tc":"「不」用在習慣、現在、未來和意願；「沒(有)」用在否定過去沒發生的事，也否定「有」。用「沒」的時候不加「了」。","sc":"「不」用在习惯、现在、未来和意愿；「没(有)」用在否定过去没发生的事，也否定「有」。用「没」的时候不加「了」。"},"ex":[{"c":"我不喝咖啡。","s":"我不喝咖啡。","es":"No tomo café.","en":"I don't drink coffee.","p":"wǒ bù hē kā fēi."},{"c":"我昨天沒去學校。","s":"我昨天没去学校。","es":"Ayer no fui a la escuela.","en":"I didn't go to school yesterday.","p":"wǒ zuó tiān méi qù xué xiào."}]},{"id":"1-13-3","b":1,"l":13,"k":"pregunta preguntar interrogativa question ask 疑問 問句 提問 pregunta preguntar interrogativa question ask 疑问 问句 提问","t":{"es":"Pregunta + 都: cualquiera","en":"All-inclusive with Question Words","ens":"All-inclusive with Question Words","tc":"疑問詞＋都：全部","sc":"疑问词＋都：全部"},"d":{"es":"Pregunta + 都 / 也: «cualquiera, todo, nadie…». Con negación: 誰都不 / 什麼都沒.","en":"Question word + 都/也 means 'any, every, no one…'. Negative: 誰都不 / 什麼都沒.","tc":"「疑問詞＋都／也」表示「任何……都」。否定用「誰都不」「什麼都沒」。","sc":"「疑问词＋都／也」表示「任何……都」。否定用「谁都不」「什么都没」。"},"ex":[{"c":"誰都知道。","s":"谁都知道。","es":"Todo el mundo lo sabe.","en":"Everyone knows.","p":"shéi dōu zhī dào."},{"c":"我什麼都吃。","s":"我什么都吃。","es":"Como de todo.","en":"I eat anything.","p":"wǒ shén me dōu chī."}]},{"id":"1-13-4","b":1,"l":13,"k":"","t":{"es":"Más / menos de lo planeado","en":"More/less…Than Planned with 多 duō /少 shǎo＋ Verb…","ens":"More/less…Than Planned with 多 duō /少 shǎo＋ Verb…","tc":"多／少＋動詞","sc":"多／少＋动词"},"d":{"es":"多 / 少 + verbo + cantidad = más / menos de lo planeado (acción ya realizada).","en":"多/少 + verb + quantity means more/less than planned (the action has already happened).","tc":"「多／少＋動詞＋數量」表示比原本計畫的更多／更少（動作已經發生）。","sc":"「多／少＋动词＋数量」表示比原本计划的更多／更少（动作已经发生）。"},"ex":[{"c":"我多買了兩個。","s":"我多买了两个。","es":"Compré dos de más.","en":"I bought two extra.","p":"wǒ duō mǎi le liǎng ge."}]},{"id":"1-13-5","b":1,"l":13,"k":"pregunta preguntar interrogativa question ask 疑問 問句 提問 negación negar negativa negation negative 否定 pregunta preguntar interrogativa question ask 疑问 问句 提问 negación negar negativa negation negative 否定","t":{"es":"¿Verdad? con 是不是","en":"是不是 shìbú shì is it true?","ens":"是不是 shìbú shì is it true?","tc":"是不是","sc":"是不是"},"d":{"es":"是不是 sirve para confirmar algo que se supone: «¿verdad que…?». Va antes del verbo o al final de la oración.","en":"是不是 is used to confirm something you assume: 'is it true that …?'. It goes before the verb or at the end.","tc":"「是不是」用來確認自己猜的事：「是不是……？」放在動詞前面或句尾。","sc":"「是不是」用来确认自己猜的事：「是不是……？」放在动词前面或句尾。"},"ex":[{"c":"你是不是累了？","s":"你是不是累了？","es":"¿Estás cansado, verdad?","en":"You're tired, aren't you?","p":"nǐ shì bú shì lèi le?"}]},{"id":"1-13-6","b":1,"l":13,"k":"comparar comparación comparativo más menos igual semejante comparison compare comparative 比較 比較級 comparar comparación comparativo más menos igual semejante comparison compare comparative 比较 比较级","t":{"es":"Igual que: 跟…一樣","en":"Comparison with 跟 gēn…一樣 yíyàng","ens":"Comparison with 跟 gēn…一样 yíyàng","tc":"跟……一樣","sc":"跟……一样"},"d":{"es":"A 跟 B 一樣 (+ adjetivo) = A es igual que B.","en":"A 跟 B 一樣 (+ adjective) means A is the same as B.","tc":"「A 跟 B 一樣（＋形容詞）」表示 A 和 B 一樣。","sc":"「A 跟 B 一样（＋形容词）」表示 A 和 B 一样。"},"ex":[{"c":"我的手機跟你的一樣。","s":"我的手机跟你的一样。","es":"Mi celular es igual al tuyo.","en":"My phone is the same as yours.","p":"wǒ de shǒu jī gēn nǐ de yí yàng."},{"c":"我跟他一樣高。","s":"我跟他一样高。","es":"Soy tan alto como él.","en":"I'm as tall as he is.","p":"wǒ gēn tā yí yàng gāo."}]},{"id":"1-14-0","b":1,"l":14,"k":"tiempo momento orden secuencia time order sequence 時間 順序 pasado completado terminado past completed finished perfective 完成 過去 tiempo momento orden secuencia time order sequence 时间 顺序 pasado completado terminado past completed finished perfective 完成 过去","t":{"es":"Duración tras 了","en":"Time-Duration after Verbal 了 le","ens":"Time-Duration after Verbal 了 le","tc":"「了」後面的時間長度","sc":"「了」后面的时间长度"},"d":{"es":"Verbo + 了 + duración (+ 的 + objeto) = cuánto tiempo duró una acción ya terminada.","en":"Verb + 了 + duration (+ 的 + object) tells how long a finished action lasted.","tc":"「動詞＋了＋時間長度（＋的＋受詞）」表示已經做完的動作持續了多久。","sc":"「动词＋了＋时间长度（＋的＋受词）」表示已经做完的动作持续了多久。"},"ex":[{"c":"我昨天睡了八個小時。","s":"我昨天睡了八个小时。","es":"Ayer dormí ocho horas.","en":"I slept eight hours yesterday.","p":"wǒ zuó tiān shuì le bā ge xiǎo shí."}]},{"id":"1-14-1","b":1,"l":14,"k":"pasado completado terminado past completed finished perfective 完成 過去 pasado completado terminado past completed finished perfective 完成 过去","t":{"es":"Doble 了: hasta ahora","en":"Completion-to-date with Double 了 le","ens":"Completion-to-date with Double 了 le","tc":"雙「了」：到現在","sc":"双「了」：到现在"},"d":{"es":"Verbo + 了 + cantidad + 了 = la acción lleva esa cantidad hasta ahora y todavía continúa.","en":"Verb + 了 + quantity + 了 means 'up to now' the action has lasted/amounted to that much, and it is still going on.","tc":"「動詞＋了＋數量＋了」表示到現在為止做了這麼久、這麼多，而且還在繼續。","sc":"「动词＋了＋数量＋了」表示到现在为止做了这么久、这么多，而且还在继续。"},"ex":[{"c":"我學中文學了兩年了。","s":"我学中文学了两年了。","es":"Llevo dos años estudiando chino.","en":"I've been studying Chinese for two years.","p":"wǒ xué zhōng wén xué le liǎng nián le."}]},{"id":"1-14-2","b":1,"l":14,"k":"","t":{"es":"Casi: 快…了","en":"快 kuài…了 le about to","ens":"快 kuài…了 le about to","tc":"快……了","sc":"快……了"},"d":{"es":"快 + verbo / adjetivo / hora + 了 = a punto de, ya casi.","en":"快 + verb/adjective/time + 了 means 'about to', 'almost'.","tc":"「快＋動詞／形容詞／時間＋了」表示快要、差不多了。","sc":"「快＋动词／形容词／时间＋了」表示快要、差不多了。"},"ex":[{"c":"快下雨了。","s":"快下雨了。","es":"Ya casi llueve.","en":"It's about to rain.","p":"kuài xià yǔ le."},{"c":"快十二點了。","s":"快十二点了。","es":"Ya casi son las doce.","en":"It's almost twelve o'clock.","p":"kuài shí èr diǎn le."}]},{"id":"1-14-3","b":1,"l":14,"k":"comparar comparación comparativo más menos igual semejante comparison compare comparative 比較 比較級 comparar comparación comparativo más menos igual semejante comparison compare comparative 比较 比较级","t":{"es":"Aún más: 更","en":"Comparison 更 gèng even more so","ens":"Comparison 更 gèng even more so","tc":"「更」：更加","sc":"「更」：更加"},"d":{"es":"更 + adjetivo = todavía más. Se compara con algo ya mencionado.","en":"更 + adjective means 'even more …'. It compares with something already mentioned.","tc":"「更＋形容詞」是「更加……」，是跟前面提過的事物比較。","sc":"「更＋形容词」是「更加……」，是跟前面提过的事物比较。"},"ex":[{"c":"這家比那家更好吃。","s":"这家比那家更好吃。","es":"Este lugar es todavía más rico que aquel.","en":"This place is even tastier than that one.","p":"zhè jiā bǐ nà jiā gèng hǎo chī."}]},{"id":"1-14-4","b":1,"l":14,"k":"comparar comparación comparativo más menos igual semejante comparison compare comparative 比較 比較級 negación negar negativa negation negative 否定 comparar comparación comparativo más menos igual semejante comparison compare comparative 比较 比较级 negación negar negativa negation negative 否定","t":{"es":"No tan…: 沒有","en":"Inferior Comparison 沒有 méiyǒu…","ens":"Inferior Comparison 没有 méiyǒu…","tc":"A 沒有 B（那麼）……","sc":"A 没有 B（那么）……"},"d":{"es":"A 沒有 B (那麼) + adjetivo = A no es tan… como B.","en":"A 沒有 B (那麼) + adjective means A is not as … as B.","tc":"「A 沒有 B（那麼）＋形容詞」表示 A 不如 B。","sc":"「A 没有 B（那么）＋形容词」表示 A 不如 B。"},"ex":[{"c":"我沒有哥哥那麼高。","s":"我没有哥哥那么高。","es":"No soy tan alto como mi hermano.","en":"I'm not as tall as my brother.","p":"wǒ méi yǒu gē ge nà me gāo."}]},{"id":"1-15-0","b":1,"l":15,"k":"pregunta preguntar interrogativa question ask 疑問 問句 提問 pregunta preguntar interrogativa question ask 疑问 问句 提问","t":{"es":"Postura libre: lo que sea","en":"Non-committal Stance with Question Words","ens":"Non-committal Stance with Question Words","tc":"疑問詞：隨你喜歡","sc":"疑问词：随你喜欢"},"d":{"es":"Con pronombres interrogativos se expresa «lo que quieras»: 什麼…就 + verbo. Es una postura sin compromiso.","en":"Question words can express 'whatever you like': 什麼…就…. It signals no particular restriction.","tc":"用疑問詞可以表示「你想……就……」，是沒有特別限制的說法：什麼……就……。","sc":"用疑问词可以表示「你想……就……」，是没有特别限制的说法：什么……就……。"},"ex":[{"c":"你想喝什麼就點什麼。","s":"你想喝什么就点什么。","es":"Pide lo que quieras beber.","en":"Order whatever you'd like to drink.","p":"nǐ xiǎng hē shén me jiù diǎn shén me."}]},{"id":"1-15-1","b":1,"l":15,"k":"disposición objeto complemento disposal object ba 處置 把字句 disposición objeto complemento disposal object ba 处置 把字句","t":{"es":"Disponer con 把","en":"To Dispose of Something with 把 bǎ","ens":"To Dispose of Something with 把 bǎ","tc":"「把」字句","sc":"「把」字句"},"d":{"es":"把 + objeto (ya conocido) + verbo + complemento: se «dispone» del objeto y se dice qué se hace con él. El verbo no puede ir solo.","en":"把 + object (already known) + verb + complement means 'dealing with' the object, saying what is done to it. The verb can't stand alone.","tc":"「把＋受詞（已知的）＋動詞＋補充說明」表示處理某個東西、對它做什麼。動詞後面不能單獨出現。","sc":"「把＋受词（已知的）＋动词＋补充说明」表示处理某个东西、对它做什么。动词后面不能单独出现。"},"ex":[{"c":"請你把窗戶打開。","s":"请你把窗户打开。","es":"Por favor abre la ventana.","en":"Please open the window.","p":"qǐng nǐ bǎ chuāng hù dǎ kāi."}]},{"id":"1-15-2","b":1,"l":15,"k":"tiempo momento orden secuencia time order sequence 時間 順序 tiempo momento orden secuencia time order sequence 时间 顺序","t":{"es":"Apenas hice… : V了…就…","en":"V 了 le…就 jiù… do…right after doing…","ens":"V 了 le…就 jiù… do…right after doing…","tc":"V 了……就……","sc":"V 了……就……"},"d":{"es":"V 了 A 就 B = en cuanto terminé A, hago B.","en":"V 了 A 就 B means 'right after finishing A, do B'.","tc":"「V 了 A 就 B」表示做完 A 以後，馬上做 B。","sc":"「V 了 A 就 B」表示做完 A 以后，马上做 B。"},"ex":[{"c":"我下了課就回家。","s":"我下了课就回家。","es":"En cuanto termine la clase me voy a casa.","en":"I'll go home right after class.","p":"wǒ xià le kè jiù huí jiā."}]},{"id":"1-15-3","b":1,"l":15,"k":"","t":{"es":"Un poco: 一點","en":"一點 yìdiǎn a bit","ens":"一点 yìdiǎn a bit","tc":"「一點」：一些","sc":"「一点」：一些"},"d":{"es":"Adjetivo + 一點 = un poco más (suaviza una petición). Verbo + 一點 = un poco de.","en":"Adjective + 一點 means 'a bit more …' and softens a request. Verb + 一點 means 'a little more'.","tc":"「形容詞＋一點」是「更……一些」，讓請求更客氣。「動詞＋一點」是「做多一些」。","sc":"「形容词＋一点」是「更……一些」，让请求更客气。「动词＋一点」是「做多一些」。"},"ex":[{"c":"這個便宜一點好嗎？","s":"这个便宜一点好吗？","es":"¿Podría ser un poco más barato?","en":"Could it be a little cheaper?","p":"zhè ge pián yí yì diǎn hǎo ma?"},{"c":"你多吃一點。","s":"你多吃一点。","es":"Come un poco más.","en":"Eat a little more.","p":"nǐ duō chī yì diǎn."}]},{"id":"1-15-4","b":1,"l":15,"k":"comparar comparación comparativo más menos igual semejante comparison compare comparative 比較 比較級 complemento resultado potencial complement result potential 補語 結果補語 可能補語 comparar comparación comparativo más menos igual semejante comparison compare comparative 比较 比较级 complemento resultado potencial complement result potential 补语 结果补语 可能补语","t":{"es":"Comparar acciones con 得","en":"Comparing Actions with a 得 de Complement","ens":"Comparing Actions with a 得 de Complement","tc":"用「得」比較動作","sc":"用「得」比较动作"},"d":{"es":"Para comparar acciones con 得: A + verbo + 得 + 比 B + adjetivo, o A 比 B + verbo + 得 + adjetivo.","en":"To compare actions with 得: A + verb + 得 + 比 B + adjective, or A 比 B + verb + 得 + adjective.","tc":"比較動作時：「A＋動詞＋得＋比 B＋形容詞」，或「A 比 B＋動詞＋得＋形容詞」。","sc":"比较动作时：「A＋动词＋得＋比 B＋形容词」，或「A 比 B＋动词＋得＋形容词」。"},"ex":[{"c":"他比我跑得快。","s":"他比我跑得快。","es":"Corre más rápido que yo.","en":"He runs faster than I do.","p":"tā bǐ wǒ pǎo de kuài."}]},{"id":"1-15-5","b":1,"l":15,"k":"comparar comparación comparativo más menos igual semejante comparison compare comparative 比較 比較級 complemento resultado potencial complement result potential 補語 結果補語 可能補語 comparar comparación comparativo más menos igual semejante comparison compare comparative 比较 比较级 complemento resultado potencial complement result potential 补语 结果补语 可能补语","t":{"es":"Grado en comparaciones","en":"Complements of Degree in Comparison Structures","ens":"Complements of Degree in Comparison Structures","tc":"比較句的程度補語","sc":"比较句的程度补语"},"d":{"es":"En la comparación con complemento de grado se puede añadir la diferencia: 一點 (un poco) o 多了 / 得多 (mucho más).","en":"In comparisons with 得 you can add the size of the difference: 一點 (a little) or 多了 / 得多 (much more).","tc":"用「得」比較時，可以再加差別：「一點」（差一些）或「多了／得多」（差很多）。","sc":"用「得」比较时，可以再加差别：「一点」（差一些）或「多了／得多」（差很多）。"},"ex":[{"c":"他說得比我好多了。","s":"他说得比我好多了。","es":"Habla mucho mejor que yo.","en":"He speaks much better than I do.","p":"tā shuō de bǐ wǒ hǎo duō le."}]},{"id":"1-15-6","b":1,"l":15,"k":"","t":{"es":"Verbos separables","en":"Separable Verbs","ens":"Separable Verbs","tc":"離合詞","sc":"离合词"},"d":{"es":"Los verbos separables (吃飯, 睡覺, 游泳, 見面) son verbo + objeto: se pueden separar y la duración o cantidad va en medio. No llevan otro objeto directo.","en":"Separable verbs (吃飯, 睡覺, 游泳, 見面) are verb + object; other words can go in between, such as a duration or quantity. They cannot take another object.","tc":"離合詞（吃飯、睡覺、游泳、見面）是「動詞＋受詞」，中間可以放別的詞，時間長度或數量放在中間。後面不能再接受詞。","sc":"离合词（吃饭、睡觉、游泳、见面）是「动词＋受词」，中间可以放别的词，时间长度或数量放在中间。后面不能再接受词。"},"ex":[{"c":"我們見了三次面。","s":"我们见了三次面。","es":"Nos vimos tres veces.","en":"We met three times.","p":"wǒ men jiàn le sān cì miàn."},{"c":"他游了一個小時的泳。","s":"他游了一个小时的泳。","es":"Nadó una hora.","en":"He swam for an hour.","p":"tā yóu le yí ge xiǎo shí de yǒng."}]},{"id":"2-1-0","b":2,"l":1,"k":"lugar ubicación dónde existencia hay location place existence where 地點 位置 存在 lugar ubicación dónde existencia hay location place existence where 地点 位置 存在","t":{"es":"Desde… hacia con 從…往","en":"從 cóng…往 wǎng… go…from…","ens":"从 cóng…往 wǎng… go…from…","tc":"從…往…","sc":"从…往…"},"d":{"es":"從 + lugar + 往 + dirección + verbo: desde… hacia… (se usa mucho para dar indicaciones).","en":"從 + place + 往 + direction + verb means 'from… toward…'. It is often used to give directions.","tc":"「從＋地點＋往＋方向＋動詞」表示從哪裡往哪個方向去，常用來指路。","sc":"「从＋地点＋往＋方向＋动词」表示从哪里往哪个方向去，常用来指路。"},"ex":[{"c":"從這裡往前走，再往右轉。","s":"从这里往前走，再往右转。","es":"Desde aquí sigue derecho y luego gira a la derecha.","en":"From here go straight, then turn right.","p":"cóng zhè lǐ wǎng qián zǒu, zài wǎng yòu zhuǎn."}]},{"id":"2-1-1","b":2,"l":1,"k":"dirección movimiento direction movement 方向 趨向 dirección movimiento direction movement 方向 趋向","t":{"es":"Juicio con V起來","en":"Judgmental V-起來 qǐlái It’s my assessment that…","ens":"Judgmental V-起来 qǐlái It’s my assessment that…","tc":"V＋起來（看起來、聽起來）","sc":"V＋起来（看起来、听起来）"},"d":{"es":"V + 起來 expresa una evaluación subjetiva: «a juzgar por cómo se ve / se oye / sabe / se siente».","en":"V + 起來 expresses a subjective judgment: 'judging by how it looks / sounds / tastes / feels'.","tc":"「V＋起來」表示說話的人根據看到、聽到、吃到的感覺所做的判斷：從……來看。","sc":"「V＋起来」表示说话的人根据看到、听到、吃到的感觉所做的判断：从……来看。"},"ex":[{"c":"這個菜看起來很好吃。","s":"这个菜看起来很好吃。","es":"Este platillo se ve muy rico.","en":"This dish looks delicious.","p":"zhè ge cài kàn qǐ lái hěn hǎo chī."}]},{"id":"2-1-2","b":2,"l":1,"k":"progresivo continuo estar haciendo presente progressive continuous ongoing 進行 持續 progresivo continuo estar haciendo presente progressive continuous ongoing 进行 持续","t":{"es":"Estado continuo con 著","en":"Ongoing Action with -著 zhe","ens":"Ongoing Action with -着 zhe","tc":"V＋著（狀態持續）","sc":"V＋着（状态持续）"},"d":{"es":"V + 著 indica un estado que continúa (resultado de una acción que permanece). Negación: 沒 + V + 著.","en":"V + 著 shows a state that continues (the result of an action that stays). Negation: 沒 + V + 著.","tc":"「V＋著」表示動作的結果或狀態一直持續著。否定時用「沒＋V＋著」。","sc":"「V＋着」表示动作的结果或状态一直持续着。否定时用「没＋V＋着」。"},"ex":[{"c":"門開著。","s":"门开着。","es":"La puerta está abierta.","en":"The door is open.","p":"mén kāi zhe."},{"c":"他穿著一件藍色的外套。","s":"他穿着一件蓝色的外套。","es":"Lleva puesta una chaqueta azul.","en":"He is wearing a blue jacket.","p":"tā chuān zhe yí jiàn lán sè de wài tào."}]},{"id":"2-1-3","b":2,"l":1,"k":"","t":{"es":"Dos acciones con 一邊…一邊","en":"Two Simultaneously Actions with 一邊 yìbiān…一邊 yìbiān…","ens":"Two Simultaneously Actions with 一边 yìbiān…一边 yìbiān…","tc":"一邊…一邊…","sc":"一边…一边…"},"d":{"es":"一邊 A 一邊 B = hacer A y B al mismo tiempo (el mismo sujeto).","en":"一邊 A 一邊 B means doing A and B at the same time (same subject).","tc":"「一邊 A 一邊 B」表示同一個人同時做 A 和 B 兩件事。","sc":"「一边 A 一边 B」表示同一个人同时做 A 和 B 两件事。"},"ex":[{"c":"他一邊走路一邊聽音樂。","s":"他一边走路一边听音乐。","es":"Camina mientras escucha música.","en":"He listens to music while walking.","p":"tā yì biān zǒu lù yì biān tīng yīn yuè."}]},{"id":"2-1-4","b":2,"l":1,"k":"lugar ubicación dónde existencia hay location place existence where 地點 位置 存在 lugar ubicación dónde existencia hay location place existence where 地点 位置 存在","t":{"es":"Distancia con 離","en":"Distance from with 離 lí…","ens":"Distance from with 离 lí…","tc":"離（距離）","sc":"离（距离）"},"d":{"es":"A 離 B + (很) 遠 / 近 = A está lejos / cerca de B. 離 indica distancia; 從 indica punto de partida.","en":"A 離 B + (很) 遠 / 近 means A is far from / near B. 離 shows distance; 從 shows a starting point.","tc":"「A 離 B ＋（很）遠／近」表示 A 和 B 之間的距離。「離」說的是距離，「從」說的是起點。","sc":"「A 离 B ＋（很）远／近」表示 A 和 B 之间的距离。「离」说的是距离，「从」说的是起点。"},"ex":[{"c":"我家離學校很近。","s":"我家离学校很近。","es":"Mi casa está muy cerca de la escuela.","en":"My home is very close to the school.","p":"wǒ jiā lí xué xiào hěn jìn."}]},{"id":"2-2-0","b":2,"l":2,"k":"negación negar negativa negation negative 否定 énfasis enfático incluso emphasis emphatic even 強調 甚至 negación negar negativa negation negative 否定 énfasis enfático incluso emphasis emphatic even 强调 甚至","t":{"es":"Negación enfática 一點也不","en":"Emphatic Negation with 一點也不 yìdiǎn yě bù V …","ens":"Emphatic Negation with 一点也不 yìdiǎn yě bù V …","tc":"一點也不／一點也沒","sc":"一点也不／一点也没"},"d":{"es":"一點也不 / 一點也沒 + verbo o adjetivo = en absoluto, nada. Es una negación enfática.","en":"一點也不 / 一點也沒 + verb or adjective is an emphatic negation: 'not at all'.","tc":"「一點也不／一點也沒＋動詞或形容詞」是加強語氣的否定，意思是完全不、一點都不。","sc":"「一点也不／一点也没＋动词或形容词」是加强语气的否定，意思是完全不、一点都不。"},"ex":[{"c":"我一點也不累。","s":"我一点也不累。","es":"No estoy nada cansado.","en":"I am not tired at all.","p":"wǒ yì diǎn yě bú lèi."}]},{"id":"2-2-1","b":2,"l":2,"k":"además adición también addition also besides 另外 而且 sugerencia proposición suggestion 建議 además adición también addition also besides 另外 而且 sugerencia proposición suggestion 建议","t":{"es":"Sugerencia con 還是…吧","en":"還是 háishì…吧 ba！ It would be better if …","ens":"还是 háishì…吧 ba！ It would be better if …","tc":"還是…吧","sc":"还是…吧"},"d":{"es":"還是 + sugerencia + 吧 = mejor + (hagamos algo). Se compara y se recomienda una opción.","en":"還是 + suggestion + 吧 means 'it would be better to…' after comparing options.","tc":"「還是＋建議＋吧」表示比較過後，覺得這樣做比較好。","sc":"「还是＋建议＋吧」表示比较过后，觉得这样做比较好。"},"ex":[{"c":"太晚了，我們還是搭計程車吧。","s":"太晚了，我们还是搭计程车吧。","es":"Es muy tarde, mejor tomemos un taxi.","en":"It's too late; we'd better take a taxi.","p":"tài wǎn le, wǒ men hái shì dā jì chéng chē ba."}]},{"id":"2-2-2","b":2,"l":2,"k":"","t":{"es":"Petición con 一點","en":"Form Adverbials with 一點 yìdiǎn","ens":"Form Adverbials with 一点 yìdiǎn","tc":"形容詞＋一點（說慢一點）","sc":"形容词＋一点（说慢一点）"},"d":{"es":"Adjetivo + 一點 + verbo (o verbo + adjetivo + 一點) forma una petición suave: «hazlo un poco más…».","en":"Adjective + 一點 + verb (or verb + adjective + 一點) makes a soft request: 'a little more…'.","tc":"「形容詞＋一點＋動詞」或「動詞＋形容詞＋一點」用來客氣地請對方再怎麼樣一點，語氣比較柔和。","sc":"「形容词＋一点＋动词」或「动词＋形容词＋一点」用来客气地请对方再怎么样一点，语气比较柔和。"},"ex":[{"c":"請你說慢一點。","s":"请你说慢一点。","es":"Por favor habla un poco más despacio.","en":"Please speak a little slower.","p":"qǐng nǐ shuō màn yì diǎn."},{"c":"你早一點來。","s":"你早一点来。","es":"Llega un poco más temprano.","en":"Come a little earlier.","p":"nǐ zǎo yì diǎn lái."}]},{"id":"2-2-3","b":2,"l":2,"k":"reduplicación repetición reduplication repetition 重疊 reduplicación repetición reduplication repetition 重叠","t":{"es":"Reduplicación AABB","en":"Reduplication of Disyllabic Adjectives","ens":"Reduplication of Disyllabic Adjectives","tc":"雙音節形容詞重疊（AABB）","sc":"双音节形容词重叠（AABB）"},"d":{"es":"Los adjetivos de dos sílabas AB se duplican como AABB; resultan más vívidos y ya no llevan 很.","en":"A two-syllable adjective AB can be doubled as AABB to be more vivid. 很 is no longer needed.","tc":"雙音節形容詞 AB 可以重疊成 AABB，讓描述更生動，前面不用再加「很」。","sc":"双音节形容词 AB 可以重叠成 AABB，让描述更生动，前面不用再加「很」。"},"ex":[{"c":"房間乾乾淨淨的。","s":"房间干干净净的。","es":"El cuarto está muy limpio.","en":"The room is nice and clean.","p":"fáng jiān gān gān jìng jìng de."}]},{"id":"2-2-4","b":2,"l":2,"k":"negación negar negativa negation negative 否定 negación negar negativa negation negative 否定","t":{"es":"Negación suave con 不太","en":"不太 bútài not very","ens":"不太 bútài not very","tc":"不太","sc":"不太"},"d":{"es":"不太 + adjetivo / verbo = no muy, no demasiado. Es una negación suave.","en":"不太 + adjective / verb means 'not very, not so much'. It is a softer negation.","tc":"「不太＋形容詞／動詞」表示不是很、不怎麼，語氣比「不」柔和。","sc":"「不太＋形容词／动词」表示不是很、不怎么，语气比「不」柔和。"},"ex":[{"c":"我不太喜歡吃辣。","s":"我不太喜欢吃辣。","es":"No me gusta mucho el picante.","en":"I don't really like spicy food.","p":"wǒ bú tài xǐ huān chī là."}]},{"id":"2-2-5","b":2,"l":2,"k":"lugar ubicación dónde existencia hay location place existence where 地點 位置 存在 lugar ubicación dónde existencia hay location place existence where 地点 位置 存在","t":{"es":"Ubicación con 部 y 邊","en":"Locations with 部 bù /邊 biān","ens":"Locations with 部 bù /边 biān","tc":"方位詞：部、邊","sc":"方位词：部、边"},"d":{"es":"部 se usa para regiones (北部, 南部, 東部, 西部); 邊 para posiciones (上邊, 裡邊, 旁邊, 左邊, 右邊).","en":"部 is used for regions (北部, 南部, 東部, 西部); 邊 for positions (上邊, 裡邊, 旁邊, 左邊, 右邊).","tc":"「部」用在地區，例如北部、南部、東部；「邊」用在位置，例如上邊、旁邊、左邊、右邊。","sc":"「部」用在地区，例如北部、南部、东部；「边」用在位置，例如上边、旁边、左边、右边。"},"ex":[{"c":"台北在台灣的北部。","s":"台北在台湾的北部。","es":"Taipéi está en el norte de Taiwán.","en":"Taipei is in northern Taiwan.","p":"tái běi zài tái wān de běi bù."},{"c":"銀行在郵局的旁邊。","s":"银行在邮局的旁边。","es":"El banco está al lado del correo.","en":"The bank is next to the post office.","p":"yín háng zài yóu jú de páng biān."}]},{"id":"2-3-0","b":2,"l":3,"k":"negación negar negativa negation negative 否定 negación negar negativa negation negative 否定","t":{"es":"Usos de 差不多","en":"Various Functions of 差不 chàbùduō","ens":"Various Functions of 差不 chàbùduō","tc":"差不多","sc":"差不多"},"d":{"es":"差不多 puede ser adjetivo («casi igual»), adverbio («casi») o «más o menos».","en":"差不多 can be an adjective ('almost the same'), an adverb ('almost') or mean 'more or less'.","tc":"「差不多」可以當形容詞（幾乎一樣）、副詞（快要）或表示大概。","sc":"「差不多」可以当形容词（几乎一样）、副词（快要）或表示大概。"},"ex":[{"c":"我們差不多高。","s":"我们差不多高。","es":"Somos casi igual de altos.","en":"We are about the same height.","p":"wǒ men chā bù duō gāo."},{"c":"差不多十二點了。","s":"差不多十二点了。","es":"Son casi las doce.","en":"It is almost twelve o'clock.","p":"chā bù duō shí èr diǎn le."}]},{"id":"2-3-1","b":2,"l":3,"k":"experiencia alguna vez haber experience ever 經驗 經歷 experiencia alguna vez haber experience ever 经验 经历","t":{"es":"Experiencia con 過","en":"Experience Particle 過 guò","ens":"Experience Particle 过 guò","tc":"經驗：V＋過","sc":"经验：V＋过"},"d":{"es":"V + 過 indica experiencia: «alguna vez». Negación: 沒 + V + 過.","en":"V + 過 shows past experience: 'have ever done'. Negation: 沒 + V + 過.","tc":"「V＋過」表示有過這樣的經驗。否定時用「沒＋V＋過」。","sc":"「V＋过」表示有过这样的经验。否定时用「没＋V＋过」。"},"ex":[{"c":"我去過日本。","s":"我去过日本。","es":"He ido a Japón.","en":"I have been to Japan.","p":"wǒ qù guò rì běn."},{"c":"我沒吃過臭豆腐。","s":"我没吃过臭豆腐。","es":"Nunca he comido tofu apestoso.","en":"I have never eaten stinky tofu.","p":"wǒ méi chī guò chòu dòu fǔ."}]},{"id":"2-3-2","b":2,"l":3,"k":"tiempo momento orden secuencia time order sequence 時間 順序 tiempo momento orden secuencia time order sequence 时间 顺序","t":{"es":"Apenas con 才","en":"才 cái merely, only","ens":"才 cái merely, only","tc":"才（只有、剛剛）","sc":"才（只有、刚刚）"},"d":{"es":"才 + cantidad pequeña = apenas, solo.","en":"才 + a small amount means 'only, just'.","tc":"「才＋數量少」表示只有、才剛剛。","sc":"「才＋数量少」表示只有、才刚刚。"},"ex":[{"c":"現在才八點。","s":"现在才八点。","es":"Apenas son las ocho.","en":"It's only eight o'clock now.","p":"xiàn zài cái bā diǎn."},{"c":"我才學了三個月。","s":"我才学了三个月。","es":"Solo llevo tres meses estudiando.","en":"I have only studied for three months.","p":"wǒ cái xué le sān ge yuè."}]},{"id":"2-3-3","b":2,"l":3,"k":"dirección movimiento direction movement 方向 趨向 dirección movimiento direction movement 方向 趋向","t":{"es":"Recordar con 想起來","en":"想起來 xiǎngqǐlái to have remembered","ens":"想起来 xiǎngqǐlái to have remembered","tc":"想起來","sc":"想起来"},"d":{"es":"想起來 = recordar de repente algo que se había olvidado.","en":"想起來 means to suddenly remember something that had been forgotten.","tc":"「想起來」表示突然想到、記起原本忘記的事。","sc":"「想起来」表示突然想到、记起原本忘记的事。"},"ex":[{"c":"我想起來了，他叫王明。","s":"我想起来了，他叫王明。","es":"Ya recordé, se llama Wang Ming.","en":"I remember now, his name is Wang Ming.","p":"wǒ xiǎng qǐ lái le, tā jiào wáng míng."}]},{"id":"2-3-4","b":2,"l":3,"k":"tiempo momento orden secuencia time order sequence 時間 順序 tiempo momento orden secuencia time order sequence 时间 顺序","t":{"es":"Más tarde de lo esperado con 才","en":"Longer/Later Than Expected with 才 cái","ens":"Longer/Later Than Expected with 才 cái","tc":"時間＋才（比預期晚）","sc":"时间＋才（比预期晚）"},"d":{"es":"Tiempo + 才 + verbo = más tarde de lo esperado. Contrasta con 就 (más temprano de lo esperado).","en":"Time + 才 + verb shows something happens later than expected. It is the opposite of 就 (earlier than expected).","tc":"「時間＋才＋動詞」表示比預期的晚。跟「就」相反，「就」表示比預期的早。","sc":"「时间＋才＋动词」表示比预期的晚。跟「就」相反，「就」表示比预期的早。"},"ex":[{"c":"他十點才起床。","s":"他十点才起床。","es":"Se levanta hasta las diez.","en":"He doesn't get up until ten.","p":"tā shí diǎn cái qǐ chuáng."}]},{"id":"2-3-5","b":2,"l":3,"k":"reduplicación repetición reduplication repetition 重疊 reduplicación repetición reduplication repetition 重叠","t":{"es":"Acción suave con ABAB","en":"Tentative Action with Reduplicated Disyllabic Verbs ABAB","ens":"Tentative Action with Reduplicated Disyllabic Verbs ABAB","tc":"雙音節動詞重疊（ABAB）","sc":"双音节动词重叠（ABAB）"},"d":{"es":"Los verbos de dos sílabas AB duplicados como ABAB suavizan la acción: «un poco, para ver».","en":"A two-syllable verb AB can be doubled as ABAB to soften the action: 'do it a little'.","tc":"雙音節動詞 AB 可以重疊成 ABAB，讓動作比較輕鬆，意思是稍微做一下、試試看。","sc":"双音节动词 AB 可以重叠成 ABAB，让动作比较轻松，意思是稍微做一下、试试看。"},"ex":[{"c":"我們討論討論吧。","s":"我们讨论讨论吧。","es":"Hablemos un poco de esto.","en":"Let's discuss it a bit.","p":"wǒ men tǎo lùn tǎo lùn ba."}]},{"id":"2-4-0","b":2,"l":4,"k":"además adición también addition also besides 另外 而且 además adición también addition also besides 另外 而且","t":{"es":"Además de con 除了…還","en":"除了 chúle…，還 hái… in addition to…","ens":"除了 chúle…，还 hái… in addition to…","tc":"除了…，還…","sc":"除了…，还…"},"d":{"es":"除了 A，還 B = además de A, también B.","en":"除了 A，還 B means 'in addition to A, also B'.","tc":"「除了 A，還 B」表示 A 之外，也有 B。","sc":"「除了 A，还 B」表示 A 之外，也有 B。"},"ex":[{"c":"除了英文，他還會說中文。","s":"除了英文，他还会说中文。","es":"Además de inglés, también habla chino.","en":"Besides English, he also speaks Chinese.","p":"chú le yīng wén, tā hái huì shuō zhōng wén."}]},{"id":"2-4-1","b":2,"l":4,"k":"","t":{"es":"Según con 按照","en":"按照…ànzhào… in accordance with","ens":"按照…ànzhào… in accordance with","tc":"按照","sc":"按照"},"d":{"es":"按照 + norma / plan / indicación = según, conforme a.","en":"按照 + rule / plan / instruction means 'according to, in accordance with'.","tc":"「按照＋規定／計畫／說法」表示依照某個標準去做。","sc":"「按照＋规定／计划／说法」表示依照某个标准去做。"},"ex":[{"c":"請按照老師說的做。","s":"请按照老师说的做。","es":"Por favor haz lo que dijo el profesor.","en":"Please do as the teacher said.","p":"qǐng àn zhào lǎo shī shuō de zuò."}]},{"id":"2-4-2","b":2,"l":4,"k":"","t":{"es":"Usos de 跟","en":"Various Meaning of the Preposition 跟 gēn","ens":"Various Meaning of the Preposition 跟 gēn","tc":"跟（多種意思）","sc":"跟（多种意思）"},"d":{"es":"跟 tiene varios usos: «con» (compañía), «de» en 跟…學 / 跟…借, «igual que» en 跟…一樣, y «y» entre sustantivos.","en":"跟 has several uses: 'with' (company), 'from' in 跟…學 / 跟…借, 'the same as' in 跟…一樣, and 'and' between nouns.","tc":"「跟」有很多用法：跟誰一起（陪伴）、跟誰學／借（對象）、跟……一樣（比較），也可以像「和」連接兩個名詞。","sc":"「跟」有很多用法：跟谁一起（陪伴）、跟谁学／借（对象）、跟……一样（比较），也可以像「和」连接两个名词。"},"ex":[{"c":"我跟老師學中文。","s":"我跟老师学中文。","es":"Aprendo chino con el profesor.","en":"I learn Chinese from my teacher.","p":"wǒ gēn lǎo shī xué zhōng wén."}]},{"id":"2-4-3","b":2,"l":4,"k":"","t":{"es":"Usos de 給","en":"Various Meanings of 給 gěi","ens":"Various Meanings of 给 gěi","tc":"給（多種意思）","sc":"给（多种意思）"},"d":{"es":"給 puede ser verbo («dar»), preposición («para») o marcar al destinatario después del verbo (寄給你).","en":"給 can be a verb ('give'), a preposition ('for') or follow a verb to mark the receiver (寄給你).","tc":"「給」可以是動詞（給我一本書）、介詞（給你的禮物），也可以放在動詞後面表示給誰，例如「寄給他」。","sc":"「给」可以是动词（给我一本书）、介词（给你的礼物），也可以放在动词后面表示给谁，例如「寄给他」。"},"ex":[{"c":"我給你一個禮物。","s":"我给你一个礼物。","es":"Te doy un regalo.","en":"I give you a gift.","p":"wǒ gěi nǐ yí ge lǐ wù."},{"c":"我寄給他一封信。","s":"我寄给他一封信。","es":"Le envié una carta.","en":"I sent him a letter.","p":"wǒ jì gěi tā yì fēng xìn."}]},{"id":"2-4-4","b":2,"l":4,"k":"","t":{"es":"Hacia con 對","en":"對 duì… towards…","ens":"对 duì… towards…","tc":"對（對於）","sc":"对（对于）"},"d":{"es":"對 + persona / cosa + adjetivo o verbo = hacia, con respecto a. Es común en 對…有興趣 y 對…很好.","en":"對 + person / thing + adjective or verb means 'toward, regarding'. Common in 對…有興趣 and 對…很好.","tc":"「對＋人／事＋形容詞或動詞」表示針對某個對象，常見的有「對……有興趣」「對……很好」。","sc":"「对＋人／事＋形容词或动词」表示针对某个对象，常见的有「对……有兴趣」「对……很好」。"},"ex":[{"c":"我對台灣文化很有興趣。","s":"我对台湾文化很有兴趣。","es":"Me interesa mucho la cultura de Taiwán.","en":"I am very interested in Taiwanese culture.","p":"wǒ duì tái wān wén huà hěn yǒu xìng qù."}]},{"id":"2-5-0","b":2,"l":5,"k":"además adición también addition also besides 另外 而且 además adición también addition also besides 另外 而且","t":{"es":"Todavía con 還","en":"還 hái still","ens":"还 hái still","tc":"還（仍然）","sc":"还（仍然）"},"d":{"es":"還 = todavía, aún (continúa una situación). 還沒 + verbo = todavía no.","en":"還 means 'still' (the situation continues). 還沒 + verb means 'not yet'.","tc":"「還」表示情況持續，意思是仍然、還在。「還沒＋動詞」表示到現在還沒有。","sc":"「还」表示情况持续，意思是仍然、还在。「还没＋动词」表示到现在还没有。"},"ex":[{"c":"他還在睡覺。","s":"他还在睡觉。","es":"Todavía está durmiendo.","en":"He is still sleeping.","p":"tā hái zài shuì jiào."},{"c":"我還沒吃飯。","s":"我还没吃饭。","es":"Todavía no he comido.","en":"I haven't eaten yet.","p":"wǒ hái méi chī fàn."}]},{"id":"2-5-1","b":2,"l":5,"k":"progresivo continuo estar haciendo presente progressive continuous ongoing 進行 持續 progresivo continuo estar haciendo presente progressive continuous ongoing 进行 持续","t":{"es":"Manera con V著","en":"Manner of an Action with V 著 zhe","ens":"Manner of an Action with V 着 zhe","tc":"V1＋著＋V2（方式）","sc":"V1＋着＋V2（方式）"},"d":{"es":"V1 + 著 + V2: V1 describe la manera en que se realiza V2.","en":"In V1 + 著 + V2, V1 describes the manner in which V2 is done.","tc":"「V1＋著＋V2」中，V1 說明做 V2 時的方式或狀態。","sc":"「V1＋着＋V2」中，V1 说明做 V2 时的方式或状态。"},"ex":[{"c":"他笑著說話。","s":"他笑着说话。","es":"Habla sonriendo.","en":"He speaks with a smile.","p":"tā xiào zhe shuō huà."}]},{"id":"2-5-2","b":2,"l":5,"k":"","t":{"es":"Varios verbos en una oración","en":"Multiple Verb Phrases in a Sentence","ens":"Multiple Verb Phrases in a Sentence","tc":"連動句（多個動詞）","sc":"连动句（多个动词）"},"d":{"es":"En una oración se pueden encadenar varios verbos en el orden en que ocurren.","en":"A sentence can chain several verbs in the order the actions happen.","tc":"一個句子裡可以依照動作發生的順序，連續放好幾個動詞。","sc":"一个句子里可以依照动作发生的顺序，连续放好几个动词。"},"ex":[{"c":"她下班回家做飯。","s":"她下班回家做饭。","es":"Ella sale del trabajo, vuelve a casa y cocina.","en":"She gets off work, goes home and cooks.","p":"tā xià bān huí jiā zuò fàn."}]},{"id":"2-5-3","b":2,"l":5,"k":"tiempo momento orden secuencia time order sequence 時間 順序 tiempo momento orden secuencia time order sequence 时间 顺序","t":{"es":"Cuando… entonces con 等…就","en":"When A Comes, Then B…with 等 děng 就…jiù…","ens":"When A Comes, Then B…with 等 děng 就…jiù…","tc":"等…就…","sc":"等…就…"},"d":{"es":"等 A 就 B = cuando ocurra A, entonces B.","en":"等 A 就 B means 'when A happens, then B'.","tc":"「等 A 就 B」表示等 A 發生之後，就做 B。","sc":"「等 A 就 B」表示等 A 发生之后，就做 B。"},"ex":[{"c":"等你來了，我們就出發。","s":"等你来了，我们就出发。","es":"Cuando llegues, salimos.","en":"When you arrive, we'll set off.","p":"děng nǐ lái le, wǒ men jiù chū fā."}]},{"id":"2-5-4","b":2,"l":5,"k":"tiempo momento orden secuencia time order sequence 時間 順序 progresivo continuo estar haciendo presente progressive continuous ongoing 進行 持續 tiempo momento orden secuencia time order sequence 时间 顺序 progresivo continuo estar haciendo presente progressive continuous ongoing 进行 持续","t":{"es":"De pronto con V著V著就…了","en":"While Doing A, B Happens with V 著 zhe V 著 zhe， 就 jiù…了 le","ens":"While Doing A, B Happens with V 着 zhe V 着 zhe， 就 jiù…了 le","tc":"V著V著就…了","sc":"V着V着就…了"},"d":{"es":"V著V著就…了 = mientras hacía algo, de pronto ocurrió otra cosa.","en":"V著V著就…了 means 'while doing something, suddenly something else happened'.","tc":"「V著V著就…了」表示做著做著，突然出現了另一個情況。","sc":"「V着V着就…了」表示做着做着，突然出现了另一个情况。"},"ex":[{"c":"他看著看著就睡著了。","s":"他看着看着就睡着了。","es":"Mientras miraba, se quedó dormido.","en":"He was watching and fell asleep.","p":"tā kàn zhe kàn zhe jiù shuì zháo le."}]},{"id":"2-6-0","b":2,"l":6,"k":"","t":{"es":"Destino con 到","en":"Destination Marker 到 dào","ens":"Destination Marker 到 dào","tc":"V＋到＋地點","sc":"V＋到＋地点"},"d":{"es":"V + 到 + lugar: la acción llega hasta ese lugar. 到 marca el destino.","en":"V + 到 + place means the action reaches that place. 到 marks the destination.","tc":"「V＋到＋地點」表示動作到達某個地方，「到」標示終點。","sc":"「V＋到＋地点」表示动作到达某个地方，「到」标示终点。"},"ex":[{"c":"我們走到公園吧。","s":"我们走到公园吧。","es":"Caminemos hasta el parque.","en":"Let's walk to the park.","p":"wǒ men zǒu dào gōng yuán ba."}]},{"id":"2-6-1","b":2,"l":6,"k":"","t":{"es":"Dar a alguien con 給","en":"Indirect Object Marker 給 gěi","ens":"Indirect Object Marker 给 gěi","tc":"V＋給＋人","sc":"V＋给＋人"},"d":{"es":"V + 給 + persona: dar o transferir algo a alguien (送給, 寄給, 交給, 借給).","en":"V + 給 + person means giving or passing something to someone (送給, 寄給, 交給, 借給).","tc":"「V＋給＋人」表示把東西送、寄、交給某個人，例如送給、寄給、交給、借給。","sc":"「V＋给＋人」表示把东西送、寄、交给某个人，例如送给、寄给、交给、借给。"},"ex":[{"c":"他送給我一本書。","s":"他送给我一本书。","es":"Me regaló un libro.","en":"He gave me a book as a present.","p":"tā sòng gěi wǒ yì běn shū."}]},{"id":"2-6-2","b":2,"l":6,"k":"progresivo continuo estar haciendo presente progressive continuous ongoing 進行 持續 lugar ubicación dónde existencia hay location place existence where 地點 位置 存在 progresivo continuo estar haciendo presente progressive continuous ongoing 进行 持续 lugar ubicación dónde existencia hay location place existence where 地点 位置 存在","t":{"es":"Lugar resultante con V在","en":"Resultant Location with V+在 zài…","ens":"Resultant Location with V+在 zài…","tc":"V＋在＋地點","sc":"V＋在＋地点"},"d":{"es":"V + 在 + lugar: como resultado de la acción, algo o alguien queda en ese lugar.","en":"V + 在 + place means that, as a result of the action, something or someone ends up in that place.","tc":"「V＋在＋地點」表示動作之後，東西或人留在那個地方。","sc":"「V＋在＋地点」表示动作之后，东西或人留在那个地方。"},"ex":[{"c":"我把車停在學校。","s":"我把车停在学校。","es":"Estaciono el coche en la escuela.","en":"I park my car at the school.","p":"wǒ bǎ chē tíng zài xué xiào."}]},{"id":"2-6-3","b":2,"l":6,"k":"lugar ubicación dónde existencia hay location place existence where 地點 位置 存在 disposición objeto complemento disposal object ba 處置 把字句 lugar ubicación dónde existencia hay location place existence where 地点 位置 存在 disposición objeto complemento disposal object ba 处置 把字句","t":{"es":"Mover con 把","en":"Moving an Object to a Location with 把 bǎ","ens":"Moving an Object to a Location with 把 bǎ","tc":"把＋物＋V＋到／在／給","sc":"把＋物＋V＋到／在／给"},"d":{"es":"把 + objeto + V + 到 / 在 / 給 + lugar o persona: mover un objeto a otro lugar.","en":"把 + object + V + 到 / 在 / 給 + place or person means moving an object somewhere.","tc":"「把＋東西＋動詞＋到／在／給＋地點或人」表示把東西移到某個地方。","sc":"「把＋东西＋动词＋到／在／给＋地点或人」表示把东西移到某个地方。"},"ex":[{"c":"請把書放在桌子上。","s":"请把书放在桌子上。","es":"Por favor pon el libro sobre la mesa.","en":"Please put the book on the table.","p":"qǐng bǎ shū fàng zài zhuō zi shàng."}]},{"id":"2-6-4","b":2,"l":6,"k":"además adición también addition also besides 另外 而且 además adición también addition also besides 另外 而且","t":{"es":"Además con 而且","en":"而且 érqiě furthermore","ens":"而且 érqiě furthermore","tc":"而且","sc":"而且"},"d":{"es":"而且 = además. Añade información que refuerza lo anterior.","en":"而且 means 'furthermore'. It adds information that reinforces the previous point.","tc":"「而且」表示再加上另一個更進一步的情況。","sc":"「而且」表示再加上另一个更进一步的情况。"},"ex":[{"c":"這家餐廳很好吃，而且很便宜。","s":"这家餐厅很好吃，而且很便宜。","es":"Este restaurante es rico y además barato.","en":"This restaurant is delicious, and cheap too.","p":"zhè jiā cān tīng hěn hǎo chī, ér qiě hěn pián yí."}]},{"id":"2-7-0","b":2,"l":7,"k":"dirección movimiento direction movement 方向 趨向 dirección movimiento direction movement 方向 趋向","t":{"es":"Dirección con 來／去","en":"Directional ConstructionsV1V2 and V1V2V3","ens":"Directional ConstructionsV1V2 and V1V2V3","tc":"複合趨向補語（V＋進來、V＋出去）","sc":"复合趋向补语（V＋进来、V＋出去）"},"d":{"es":"Verbo + dirección (上, 下, 進, 出, 回, 過, 起) + 來 / 去: movimiento hacia (來) o lejos (去) del hablante. También V1V2V3.","en":"A verb plus a direction (上, 下, 進, 出, 回, 過, 起) plus 來 or 去 shows movement toward (來) or away from (去) the speaker. V1V2V3 also exists.","tc":"動詞後面加上、下、進、出、回、過、起，再加「來」或「去」，表示動作的方向：朝說話的人是「來」，離開說話的人是「去」。","sc":"动词后面加上、下、进、出、回、过、起，再加「来」或「去」，表示动作的方向：朝说话的人是「来」，离开说话的人是「去」。"},"ex":[{"c":"他走進來了。","s":"他走进来了。","es":"Entró caminando.","en":"He walked in.","p":"tā zǒu jìn lái le."},{"c":"她跑出去了。","s":"她跑出去了。","es":"Salió corriendo.","en":"She ran out.","p":"tā pǎo chū qù le."}]},{"id":"2-7-1","b":2,"l":7,"k":"disposición objeto complemento disposal object ba 處置 把字句 disposición objeto complemento disposal object ba 处置 把字句","t":{"es":"把 con dirección","en":"把 bǎ with V1V2V3","ens":"把 bǎ with V1V2V3","tc":"把＋物＋V＋趨向補語","sc":"把＋物＋V＋趋向补语"},"d":{"es":"把 + objeto + verbo + dirección + 來 / 去: mover el objeto en esa dirección.","en":"把 + object + verb + direction + 來 / 去 means moving the object in that direction.","tc":"「把＋東西＋動詞＋方向＋來／去」表示把東西往某個方向移動。","sc":"「把＋东西＋动词＋方向＋来／去」表示把东西往某个方向移动。"},"ex":[{"c":"請把椅子搬到樓上去。","s":"请把椅子搬到楼上去。","es":"Por favor lleva la silla al piso de arriba.","en":"Please carry the chair upstairs.","p":"qǐng bǎ yǐ zi bān dào lóu shàng qù."}]},{"id":"2-7-2","b":2,"l":7,"k":"pregunta preguntar interrogativa question ask 疑問 問句 提問 pregunta preguntar interrogativa question ask 疑问 问句 提问","t":{"es":"Reproche con 嗎","en":"Confrontation with 嗎?","ens":"Confrontation with 吗?","tc":"用「嗎」表示責備","sc":"用「吗」表示责备"},"d":{"es":"Una pregunta con 嗎 puede expresar reproche o confrontación: «¿no ves que…?».","en":"A question with 嗎 can express reproach or confrontation rather than a real question: 'Can't you see…?'","tc":"用「嗎」的問句有時不是真的在問，而是在責備或表示不滿：你沒看到……嗎？","sc":"用「吗」的问句有时不是真的在问，而是在责备或表示不满：你没看到……吗？"},"ex":[{"c":"你沒看到我在忙嗎？","s":"你没看到我在忙吗？","es":"¿No ves que estoy ocupado?","en":"Can't you see that I'm busy?","p":"nǐ méi kàn dào wǒ zài máng ma?"}]},{"id":"2-7-3","b":2,"l":7,"k":"lugar ubicación dónde existencia hay location place existence where 地點 位置 存在 lugar ubicación dónde existencia hay location place existence where 地点 位置 存在","t":{"es":"Posición con V著","en":"Existential Sentence with Posture Verbs","ens":"Existential Sentence with Posture Verbs","tc":"存在句：地點＋V著＋物","sc":"存在句：地点＋V着＋物"},"d":{"es":"Lugar + verbo de posición (坐, 站, 躺, 放, 掛, 貼) + 著 + persona o cosa: así está colocado.","en":"Place + posture verb (坐, 站, 躺, 放, 掛, 貼) + 著 + person or thing describes how something is placed there.","tc":"「地點＋姿勢動詞（坐、站、躺、放、掛、貼）＋著＋人或東西」表示那裡擺放或存在的狀態。","sc":"「地点＋姿势动词（坐、站、躺、放、挂、贴）＋着＋人或东西」表示那里摆放或存在的状态。"},"ex":[{"c":"桌子上放著一本書。","s":"桌子上放着一本书。","es":"Sobre la mesa hay un libro (puesto).","en":"There is a book lying on the table.","p":"zhuō zi shàng fàng zhe yì běn shū."}]},{"id":"2-7-4","b":2,"l":7,"k":"causa razón porque consecuencia resultado cause reason because consequence result 原因 結果 因果 causa razón porque consecuencia resultado cause reason because consequence result 原因 结果 因果","t":{"es":"Para con 為了","en":"為了 wèile in order to","ens":"为了 wèile in order to","tc":"為了","sc":"为了"},"d":{"es":"為了 + objetivo, + acción = para, con el fin de.","en":"為了 + goal, + action means 'in order to'.","tc":"「為了＋目的，＋動作」表示做某件事的目的。","sc":"「为了＋目的，＋动作」表示做某件事的目的。"},"ex":[{"c":"為了學好中文，我每天聽廣播。","s":"为了学好中文，我每天听广播。","es":"Para aprender bien chino escucho la radio todos los días.","en":"To learn Chinese well, I listen to the radio every day.","p":"wèi le xué hǎo zhōng wén, wǒ měi tiān tīng guǎng bò."}]},{"id":"2-8-0","b":2,"l":8,"k":"","t":{"es":"Percepción con 見","en":"見 jiàn as a Perceptual Result","ens":"见 jiàn as a Perceptual Result","tc":"V＋見（看見、聽見）","sc":"V＋见（看见、听见）"},"d":{"es":"V + 見 expresa que la percepción se logró: 看見 (ver), 聽見 (oír).","en":"V + 見 shows a successful perception: 看見 (see), 聽見 (hear).","tc":"「V＋見」表示感官的結果，例如看見、聽見，真的看到或聽到了。","sc":"「V＋见」表示感官的结果，例如看见、听见，真的看到或听到了。"},"ex":[{"c":"我聽見有人在叫我。","s":"我听见有人在叫我。","es":"Oí que alguien me llamaba.","en":"I heard someone calling me.","p":"wǒ tīng jiàn yǒu rén zài jiào wǒ."}]},{"id":"2-8-1","b":2,"l":8,"k":"","t":{"es":"Comprender con 懂","en":"懂 dǒng as a Cognitive Result","ens":"懂 dǒng as a Cognitive Result","tc":"V＋懂（聽懂、看懂）","sc":"V＋懂（听懂、看懂）"},"d":{"es":"V + 懂 = comprender lo que se escucha o lee: 聽懂, 看懂.","en":"V + 懂 means understanding what you hear or read: 聽懂, 看懂.","tc":"「V＋懂」表示聽或看之後理解了，例如聽懂、看懂。","sc":"「V＋懂」表示听或看之后理解了，例如听懂、看懂。"},"ex":[{"c":"老師說的話我聽得懂。","s":"老师说的话我听得懂。","es":"Entiendo lo que dice el profesor.","en":"I can understand what the teacher says.","p":"lǎo shī shuō de huà wǒ tīng dé dǒng."}]},{"id":"2-8-2","b":2,"l":8,"k":"poder saber habilidad capacidad permiso posibilidad ability can permission possibility 能力 可能 許可 poder saber habilidad capacidad permiso posibilidad ability can permission possibility 能力 可能 许可","t":{"es":"Aprender con 會","en":"會 huìas an Achievement Result","ens":"会 huìas an Achievement Result","tc":"V＋會（學會、教會）","sc":"V＋会（学会、教会）"},"d":{"es":"V + 會 = aprender a hacer algo (logro): 學會, 教會.","en":"V + 會 means to have learned how to do something: 學會, 教會.","tc":"「V＋會」表示學習之後學會了，例如學會、教會。","sc":"「V＋会」表示学习之后学会了，例如学会、教会。"},"ex":[{"c":"我學會了做蛋糕。","s":"我学会了做蛋糕。","es":"Aprendí a hacer pasteles.","en":"I learned how to make a cake.","p":"wǒ xué huì le zuò dàn gāo."}]},{"id":"2-8-3","b":2,"l":8,"k":"negación negar negativa negation negative 否定 complemento resultado potencial complement result potential 補語 結果補語 可能補語 poder saber habilidad capacidad permiso posibilidad ability can permission possibility 能力 可能 許可 negación negar negativa negation negative 否定 complemento resultado potencial complement result potential 补语 结果补语 可能补语 poder saber habilidad capacidad permiso posibilidad ability can permission possibility 能力 可能 许可","t":{"es":"Potencial con 得／不","en":"Potential Capability with -得 de- or -不 bù-","ens":"Potential Capability with -得 de- or -不 bù-","tc":"可能補語（V得＋補語／V不＋補語）","sc":"可能补语（V得＋补语／V不＋补语）"},"d":{"es":"V + 得 + complemento = se puede; V + 不 + complemento = no se puede (por las circunstancias).","en":"V + 得 + complement means can; V + 不 + complement means cannot, depending on the circumstances.","tc":"「V＋得＋補語」表示可以，「V＋不＋補語」表示不能，指在條件上做不做得到。","sc":"「V＋得＋补语」表示可以，「V＋不＋补语」表示不能，指在条件上做不做得到。"},"ex":[{"c":"我看得懂，他看不懂。","s":"我看得懂，他看不懂。","es":"Yo sí lo entiendo al leerlo; él no.","en":"I can understand it, but he can't.","p":"wǒ kàn de dǒng, tā kàn bù dǒng."},{"c":"這麼多菜，我吃不完。","s":"这么多菜，我吃不完。","es":"Con tanta comida, no puedo terminarla.","en":"With so many dishes, I can't finish them.","p":"zhè me duō cài, wǒ chī bù wán."}]},{"id":"2-8-4","b":2,"l":8,"k":"complemento resultado potencial complement result potential 補語 結果補語 可能補語 poder saber habilidad capacidad permiso posibilidad ability can permission possibility 能力 可能 許可 complemento resultado potencial complement result potential 补语 结果补语 可能补语 poder saber habilidad capacidad permiso posibilidad ability can permission possibility 能力 可能 许可","t":{"es":"Capacidad con 了 (liǎo)","en":"Capability Complement 了 liǎo","ens":"Capability Complement 了 liǎo","tc":"V＋得了／不了","sc":"V＋得了／不了"},"d":{"es":"V + 得了 / 不了 = poder / no poder completar o soportar algo. Aquí 了 se lee liǎo.","en":"V + 得了 / 不了 means being able / unable to finish or endure something. Here 了 is read liǎo.","tc":"「V＋得了／不了」表示能不能完成或承受。這裡的「了」唸 liǎo。","sc":"「V＋得了／不了」表示能不能完成或承受。这里的「了」念 liǎo。"},"ex":[{"c":"太多了，我吃不了。","s":"太多了，我吃不了。","es":"Es demasiado, no puedo con todo.","en":"It's too much, I can't finish it.","p":"tài duō le, wǒ chī bù liǎo."}]},{"id":"2-8-5","b":2,"l":8,"k":"complemento resultado potencial complement result potential 補語 結果補語 可能補語 complemento resultado potencial complement result potential 补语 结果补语 可能补语","t":{"es":"Resultado con 得","en":"Vs +得 de + complement so …that…","ens":"Vs +得 de + complement so …that…","tc":"形容詞／動詞＋得＋結果","sc":"形容词／动词＋得＋结果"},"d":{"es":"Adjetivo / verbo + 得 + resultado = tan… que…","en":"Adjective / verb + 得 + result means 'so… that…'.","tc":"「形容詞或動詞＋得＋結果」表示程度很高，高到出現某個結果：……得……。","sc":"「形容词或动词＋得＋结果」表示程度很高，高到出现某个结果：……得……。"},"ex":[{"c":"他高興得跳起來。","s":"他高兴得跳起来。","es":"Estaba tan contento que saltó.","en":"He was so happy that he jumped up.","p":"tā gāo xìng de tiào qǐ lái."}]},{"id":"2-8-6","b":2,"l":8,"k":"dirección movimiento direction movement 方向 趨向 dirección movimiento direction movement 方向 趋向","t":{"es":"Continuar con 下去","en":"To Keep on Doing Something with 下去 xiàqù","ens":"To Keep on Doing Something with 下去 xiàqù","tc":"V＋下去","sc":"V＋下去"},"d":{"es":"V + 下去 = seguir haciendo algo (de ahora en adelante).","en":"V + 下去 means to keep on doing something from now on.","tc":"「V＋下去」表示從現在開始繼續做下去。","sc":"「V＋下去」表示从现在开始继续做下去。"},"ex":[{"c":"你說下去，我在聽。","s":"你说下去，我在听。","es":"Sigue, te estoy escuchando.","en":"Go on, I'm listening.","p":"nǐ shuō xià qù, wǒ zài tīng."}]},{"id":"2-8-7","b":2,"l":8,"k":"pasado completado terminado past completed finished perfective 完成 過去 pasado completado terminado past completed finished perfective 完成 过去","t":{"es":"Terminar con 完","en":"Completion of an Action with V+完 wán","ens":"Completion of an Action with V+完 wán","tc":"V＋完","sc":"V＋完"},"d":{"es":"V + 完 = terminar de hacer algo. Negación: 沒 + V + 完.","en":"V + 完 means to finish doing something. Negation: 沒 + V + 完.","tc":"「V＋完」表示把某件事做完。否定時用「沒＋V＋完」。","sc":"「V＋完」表示把某件事做完。否定时用「没＋V＋完」。"},"ex":[{"c":"我寫完功課了。","s":"我写完功课了。","es":"Terminé la tarea.","en":"I finished my homework.","p":"wǒ xiě wán gōng kè le."}]},{"id":"2-9-0","b":2,"l":9,"k":"complemento resultado potencial complement result potential 補語 結果補語 可能補語 complemento resultado potencial complement result potential 补语 结果补语 可能补语","t":{"es":"Listo con 好","en":"All Set and Ready with Verb Complement 好 hǎo","ens":"All Set and Ready with Verb Complement 好 hǎo","tc":"V＋好","sc":"V＋好"},"d":{"es":"V + 好 = quedar listo o hecho bien: 準備好, 做好, 洗好.","en":"V + 好 means something is done or ready: 準備好, 做好, 洗好.","tc":"「V＋好」表示事情做好了、準備好了，例如準備好、做好、洗好。","sc":"「V＋好」表示事情做好了、准备好了，例如准备好、做好、洗好。"},"ex":[{"c":"飯做好了。","s":"饭做好了。","es":"La comida ya está lista.","en":"The meal is ready.","p":"fàn zuò hǎo le."}]},{"id":"2-9-1","b":2,"l":9,"k":"complemento resultado potencial complement result potential 補語 結果補語 可能補語 complemento resultado potencial complement result potential 补语 结果补语 可能补语","t":{"es":"Lograr con 到","en":"To Be Successful in …with Verb Complement 到 dào","ens":"To Be Successful in …with Verb Complement 到 dào","tc":"V＋到（達成結果）","sc":"V＋到（达成结果）"},"d":{"es":"V + 到 = lograr el resultado esperado: 買到, 找到, 看到.","en":"V + 到 means achieving the intended result: 買到, 找到, 看到.","tc":"「V＋到」表示達到想要的結果，例如買到、找到、看到。","sc":"「V＋到」表示达到想要的结果，例如买到、找到、看到。"},"ex":[{"c":"我買到票了。","s":"我买到票了。","es":"Conseguí el boleto.","en":"I got the ticket.","p":"wǒ mǎi dào piào le."}]},{"id":"2-9-2","b":2,"l":9,"k":"comparar comparación comparativo más menos igual semejante comparison compare comparative 比較 比較級 dirección movimiento direction movement 方向 趨向 comparar comparación comparativo más menos igual semejante comparison compare comparative 比较 比较级 dirección movimiento direction movement 方向 趋向","t":{"es":"Comparar con 比起來","en":"Comparison with 比起來 bǐ qǐlái","ens":"Comparison with 比起来 bǐ qǐlái","tc":"跟…比起來","sc":"跟…比起来"},"d":{"es":"跟 B 比起來，A… / 比起 B，A… = en comparación con B, A…","en":"跟 B 比起來，A… / 比起 B，A… means 'compared with B, A…'.","tc":"「跟 B 比起來，A……」或「比起 B，A……」表示拿 A 跟 B 做比較。","sc":"「跟 B 比起来，A……」或「比起 B，A……」表示拿 A 跟 B 做比较。"},"ex":[{"c":"跟台北比起來，高雄比較熱。","s":"跟台北比起来，高雄比较热。","es":"Comparado con Taipéi, Kaohsiung es más caluroso.","en":"Compared with Taipei, Kaohsiung is hotter.","p":"gēn tái běi bǐ qǐ lái, gāo xióng bǐ jiào rè."}]},{"id":"2-9-3","b":2,"l":9,"k":"comparar comparación comparativo más menos igual semejante comparison compare comparative 比較 比較級 comparar comparación comparativo más menos igual semejante comparison compare comparative 比较 比较级","t":{"es":"Semejanza con 像…一樣","en":"像 xiàng…一樣 yí yàng … is just like…","ens":"像 xiàng…一样 yí yàng … is just like…","tc":"像…一樣","sc":"像…一样"},"d":{"es":"A 像 B 一樣 (+ adjetivo / verbo) = A es como B.","en":"A 像 B 一樣 (+ adjective / verb) means A is like B.","tc":"「A 像 B 一樣（＋形容詞／動詞）」表示 A 跟 B 很相似。","sc":"「A 像 B 一样（＋形容词／动词）」表示 A 跟 B 很相似。"},"ex":[{"c":"他像小孩子一樣愛玩。","s":"他像小孩子一样爱玩。","es":"Le gusta jugar como a un niño.","en":"He loves to play just like a child.","p":"tā xiàng xiǎo hái zi yí yàng ài wán."}]},{"id":"2-9-4","b":2,"l":9,"k":"negación negar negativa negation negative 否定 complemento resultado potencial complement result potential 補語 結果補語 可能補語 negación negar negativa negation negative 否定 complemento resultado potencial complement result potential 补语 结果补语 可能补语","t":{"es":"Extremo con 極了","en":"Adverbial Complements 極了 jíle、得不得了 de bùdéliǎo、得很 de hěn terribly, extremely","ens":"Adverbial Complements 极了 jíle、得不得了 de bùdéliǎo、得很 de hěn terribly, extremely","tc":"形容詞＋極了／得不得了／得很","sc":"形容词＋极了／得不得了／得很"},"d":{"es":"Adjetivo + 極了 / 得不得了 / 得很 = extremadamente. Van después del adjetivo.","en":"Adjective + 極了 / 得不得了 / 得很 goes after the adjective and means 'extremely'.","tc":"「形容詞＋極了／得不得了／得很」放在形容詞後面，表示非常、程度很高。","sc":"「形容词＋极了／得不得了／得很」放在形容词后面，表示非常、程度很高。"},"ex":[{"c":"今天熱極了。","s":"今天热极了。","es":"Hoy hace muchísimo calor.","en":"It is extremely hot today.","p":"jīn tiān rè jí le."},{"c":"她高興得不得了。","s":"她高兴得不得了。","es":"Está contentísima.","en":"She is overjoyed.","p":"tā gāo xìng de bù dé liǎo."}]},{"id":"2-9-5","b":2,"l":9,"k":"complemento resultado potencial complement result potential 補語 結果補語 可能補語 complemento resultado potencial complement result potential 补语 结果补语 可能补语","t":{"es":"Poder permitirse con 起","en":"Verb Complement 起 qǐ to be able to afford","ens":"Verb Complement 起 qǐ to be able to afford","tc":"V＋得起／不起","sc":"V＋得起／不起"},"d":{"es":"V + 得起 / 不起 = poder / no poder permitirse algo (por dinero o categoría).","en":"V + 得起 / 不起 means being able / unable to afford something (usually money).","tc":"「V＋得起／不起」表示有沒有能力負擔，通常指錢夠不夠。","sc":"「V＋得起／不起」表示有没有能力负担，通常指钱够不够。"},"ex":[{"c":"這個包包太貴了，我買不起。","s":"这个包包太贵了，我买不起。","es":"Esta bolsa es muy cara, no me la puedo permitir.","en":"This bag is too expensive; I can't afford it.","p":"zhè ge bāo bāo tài guì le, wǒ mǎi bù qǐ."}]},{"id":"2-10-0","b":2,"l":10,"k":"dirección movimiento direction movement 方向 趨向 complemento resultado potencial complement result potential 補語 結果補語 可能補語 dirección movimiento direction movement 方向 趋向 complemento resultado potencial complement result potential 补语 结果补语 可能补语","t":{"es":"Descubrir con 出來","en":"To Figure out with the Complement 出來 chūlái","ens":"To Figure out with the Complement 出来 chūlái","tc":"V＋出來","sc":"V＋出来"},"d":{"es":"V + 出來 = descubrir, distinguir o llegar a darse cuenta (sacar a la luz).","en":"V + 出來 means to figure out, make out or discover something.","tc":"「V＋出來」表示把原本不清楚的事情找出來、分辨出來或想出來。","sc":"「V＋出来」表示把原本不清楚的事情找出来、分辨出来或想出来。"},"ex":[{"c":"你聽得出來他是誰嗎？","s":"你听得出来他是谁吗？","es":"¿Puedes reconocer quién es por la voz?","en":"Can you tell who he is from his voice?","p":"nǐ tīng dé chū lái tā shì shéi ma?"}]},{"id":"2-10-1","b":2,"l":10,"k":"complemento resultado potencial complement result potential 補語 結果補語 可能補語 complemento resultado potencial complement result potential 补语 结果补语 可能补语","t":{"es":"Caber con 下","en":"Enough Space to Accommodate with Verb Complement 下 xià","ens":"Enough Space to Accommodate with Verb Complement 下 xià","tc":"V＋得下／不下","sc":"V＋得下／不下"},"d":{"es":"V + 得下 / 不下 = hay / no hay espacio suficiente para acomodar algo.","en":"V + 得下 / 不下 means whether there is enough space to hold something.","tc":"「V＋得下／不下」表示空間夠不夠容納。","sc":"「V＋得下／不下」表示空间够不够容纳。"},"ex":[{"c":"這個房間坐得下十個人。","s":"这个房间坐得下十个人。","es":"En este cuarto caben diez personas sentadas.","en":"This room can seat ten people.","p":"zhè ge fáng jiān zuò de xià shí ge rén."}]},{"id":"2-10-2","b":2,"l":10,"k":"disposición objeto complemento disposal object ba 處置 把字句 reduplicación repetición reduplication repetition 重疊 disposición objeto complemento disposal object ba 处置 把字句 reduplicación repetición reduplication repetition 重叠","t":{"es":"把…V(一)V","en":"Disposal Construction 把 bǎ with Verb Reduplication 把 bǎ…V(一)V","ens":"Disposal Construction 把 bǎ with Verb Reduplication 把 bǎ…V(一)V","tc":"把＋物＋V(一)V","sc":"把＋物＋V(一)V"},"d":{"es":"把 + objeto + V(一)V = hacer algo con el objeto de forma breve o ligera.","en":"把 + object + V(一)V means to do something to the object briefly or lightly.","tc":"「把＋東西＋V(一)V」表示稍微處理一下那個東西，語氣輕鬆。","sc":"「把＋东西＋V(一)V」表示稍微处理一下那个东西，语气轻松。"},"ex":[{"c":"請你把房間整理整理。","s":"请你把房间整理整理。","es":"Por favor ordena un poco el cuarto.","en":"Please tidy up the room a bit.","p":"qǐng nǐ bǎ fáng jiān zhěng lǐ zhěng lǐ."}]},{"id":"2-10-3","b":2,"l":10,"k":"disposición objeto complemento disposal object ba 處置 把字句 complemento resultado potencial complement result potential 補語 結果補語 可能補語 disposición objeto complemento disposal object ba 处置 把字句 complemento resultado potencial complement result potential 补语 结果补语 可能补语","t":{"es":"把 con resultado","en":"Disposal Construction 把 bǎ with Resultative Complements","ens":"Disposal Construction 把 bǎ with Resultative Complements","tc":"把＋物＋V＋結果補語","sc":"把＋物＋V＋结果补语"},"d":{"es":"把 + objeto + V + complemento de resultado (完, 好, 乾淨, 壞…): el objeto queda en ese estado.","en":"把 + object + verb + result complement (完, 好, 乾淨, 壞…) shows the state the object ends up in.","tc":"「把＋東西＋動詞＋結果補語（完、好、乾淨、壞……）」表示東西因為這個動作變成某種結果。","sc":"「把＋东西＋动词＋结果补语（完、好、干净、坏……）」表示东西因为这个动作变成某种结果。"},"ex":[{"c":"我把衣服洗乾淨了。","s":"我把衣服洗干净了。","es":"Lavé la ropa y quedó limpia.","en":"I washed the clothes clean.","p":"wǒ bǎ yī fú xǐ gān jìng le."}]},{"id":"2-10-4","b":2,"l":10,"k":"","t":{"es":"Aprovechar con 趁","en":"趁 chèn seize the moment","ens":"趁 chèn seize the moment","tc":"趁","sc":"趁"},"d":{"es":"趁 + oportunidad + verbo = aprovechar el momento para…","en":"趁 + opportunity + verb means 'take advantage of the moment to…'.","tc":"「趁＋機會＋動詞」表示利用某個機會或時間去做事。","sc":"「趁＋机会＋动词」表示利用某个机会或时间去做事。"},"ex":[{"c":"趁天氣好，我們去爬山吧。","s":"趁天气好，我们去爬山吧。","es":"Aprovechemos que hace buen tiempo para ir a la montaña.","en":"Let's go hiking while the weather is nice.","p":"chèn tiān qì hǎo, wǒ men qù pá shān ba."}]},{"id":"2-11-0","b":2,"l":11,"k":"negación negar negativa negation negative 否定 negación negar negativa negation negative 否定","t":{"es":"其他的 vs 別的","en":"The Others 其他 qítā de vs. Other 別的 biéde vs.","ens":"The Others 其他 qítā de vs. Other 别的 biéde vs.","tc":"其他的、別的","sc":"其他的、别的"},"d":{"es":"其他的 = los demás (el resto de un grupo). 別的 = otro, diferente (otra cosa u opción).","en":"其他的 means 'the rest' of a group; 別的 means 'another / something different'.","tc":"「其他的」是一群裡面剩下的人或東西；「別的」是另外不同的東西或選擇。","sc":"「其他的」是一群里面剩下的人或东西；「别的」是另外不同的东西或选择。"},"ex":[{"c":"其他的同學都走了。","s":"其他的同学都走了。","es":"Los demás compañeros ya se fueron.","en":"The other classmates have all left.","p":"qí tā de tóng xué dōu zǒu le."},{"c":"這個我不要，我要別的。","s":"这个我不要，我要别的。","es":"Esto no lo quiero, quiero otra cosa.","en":"I don't want this one; I want something else.","p":"zhè ge wǒ bú yào, wǒ yào bié de."}]},{"id":"2-11-1","b":2,"l":11,"k":"clasificador clasificadores medida contar cantidad measure word classifier counter 量詞 clasificador clasificadores medida contar cantidad measure word classifier counter 量词","t":{"es":"Clasificadores verbales","en":"Verbal Classifiers 下 xià , 趟 tàng ,遍 biàn , and 次 cì","ens":"Verbal Classifiers 下 xià , 趟 tàng ,遍 biàn , and 次 cì","tc":"動量詞：下、趟、遍、次","sc":"动量词：下、趟、遍、次"},"d":{"es":"Clasificadores verbales: 次 = veces; 遍 = de principio a fin; 趟 = viaje de ida y vuelta; 下 = acción breve.","en":"Verbal measure words count actions: 次 = times; 遍 = once from start to finish; 趟 = a round trip; 下 = a short action.","tc":"動量詞用來算動作的次數：「次」是回數；「遍」是從頭到尾一次；「趟」是去一次再回來；「下」是很短的動作。","sc":"动量词用来算动作的次数：「次」是回数；「遍」是从头到尾一次；「趟」是去一次再回来；「下」是很短的动作。"},"ex":[{"c":"我去過兩次。","s":"我去过两次。","es":"He ido dos veces.","en":"I have been there twice.","p":"wǒ qù guò liǎng cì."},{"c":"請你再說一遍。","s":"请你再说一遍。","es":"Por favor dilo una vez más.","en":"Please say it once more.","p":"qǐng nǐ zài shuō yí biàn."}]},{"id":"2-11-2","b":2,"l":11,"k":"tiempo momento orden secuencia time order sequence 時間 順序 dirección movimiento direction movement 方向 趨向 tiempo momento orden secuencia time order sequence 时间 顺序 dirección movimiento direction movement 方向 趋向","t":{"es":"然後、後來、以後","en":"Expressing Next in Sequence with 然後 ránhòu, 後來 hòulái, and 以後 yǐhòu","ens":"Expressing Next in Sequence with 然后 ránhòu, 后来 hòulái, and 以后 yǐhòu","tc":"然後、後來、以後","sc":"然后、后来、以后"},"d":{"es":"然後 = luego (secuencia); 後來 = más tarde (solo para el pasado); 以後 = después (pasado o futuro).","en":"然後 means 'and then' (sequence); 後來 means 'later' (only for the past); 以後 means 'after' (past or future).","tc":"「然後」表示接著；「後來」只能說過去的事；「以後」可以說過去或未來。","sc":"「然后」表示接着；「后来」只能说过去的事；「以后」可以说过去或未来。"},"ex":[{"c":"我先吃飯，然後看電視。","s":"我先吃饭，然后看电视。","es":"Primero como y luego veo televisión.","en":"First I eat, then I watch TV.","p":"wǒ xiān chī fàn, rán hòu kàn diàn shì."},{"c":"後來他搬家了。","s":"后来他搬家了。","es":"Más tarde se mudó.","en":"Later he moved house.","p":"hòu lái tā bān jiā le."}]},{"id":"2-11-3","b":2,"l":11,"k":"tiempo momento orden secuencia time order sequence 時間 順序 tiempo momento orden secuencia time order sequence 时间 顺序","t":{"es":"Solo entonces con 才","en":"才 cái then and only then","ens":"才 cái then and only then","tc":"A才B（先後條件）","sc":"A才B（先后条件）"},"d":{"es":"A 才 B = solo después de A ocurre B (A es condición previa).","en":"A 才 B means B happens only after A. A is a prerequisite.","tc":"「A 才 B」表示要先有 A，才會有 B，A 是前提。","sc":"「A 才 B」表示要先有 A，才会有 B，A 是前提。"},"ex":[{"c":"吃了飯才可以玩。","s":"吃了饭才可以玩。","es":"Solo después de comer puedes jugar.","en":"You can play only after you eat.","p":"chī le fàn cái kě yǐ wán."}]},{"id":"2-11-4","b":2,"l":11,"k":"pasiva voz pasiva passive 被動 被字句 pasiva voz pasiva passive 被动 被字句","t":{"es":"Pasiva con 被","en":"Passive Sentences with 被 bèi","ens":"Passive Sentences with 被 bèi","tc":"被字句","sc":"被字句"},"d":{"es":"A 被 B + verbo + complemento = A es afectado por B (pasiva, suele tener sentido negativo).","en":"A 被 B + verb + complement means A is affected by B (passive). It often describes something unfortunate.","tc":"「A 被 B ＋動詞＋補語」表示 A 受到 B 的影響，常常是不好的事。","sc":"「A 被 B ＋动词＋补语」表示 A 受到 B 的影响，常常是不好的事。"},"ex":[{"c":"我的手機被偷了。","s":"我的手机被偷了。","es":"Me robaron el celular.","en":"My phone was stolen.","p":"wǒ de shǒu jī bèi tōu le."}]},{"id":"2-11-5","b":2,"l":11,"k":"reduplicación repetición reduplication repetition 重疊 reduplicación repetición reduplication repetition 重叠","t":{"es":"V了V","en":"Verb Reduplication in V 了 le V","ens":"Verb Reduplication in V 了 le V","tc":"V了V","sc":"V了V"},"d":{"es":"V 了 V = hacer algo un ratito o un poco (acción ya realizada).","en":"V了V means doing something for a little while (an action already carried out).","tc":"「V了V」表示做了一下子，是已經做過的動作。","sc":"「V了V」表示做了一下子，是已经做过的动作。"},"ex":[{"c":"我想了想，決定不去。","s":"我想了想，决定不去。","es":"Lo pensé un poco y decidí no ir.","en":"I thought about it for a moment and decided not to go.","p":"wǒ xiǎng le xiǎng, jué dìng bú qù."}]},{"id":"2-11-6","b":2,"l":11,"k":"","t":{"es":"Contacto con 上","en":"Verb Particle 上 shàng coming into contact","ens":"Verb Particle 上 shàng coming into contact","tc":"V＋上","sc":"V＋上"},"d":{"es":"V + 上 expresa contacto o cierre: 關上 (cerrar), 穿上 (ponerse), 考上 (ser admitido), 愛上 (enamorarse).","en":"V + 上 shows contact or closing: 關上 (close), 穿上 (put on), 考上 (get admitted), 愛上 (fall in love with).","tc":"「V＋上」表示接觸或閉合，例如關上、穿上、考上、愛上。","sc":"「V＋上」表示接触或闭合，例如关上、穿上、考上、爱上。"},"ex":[{"c":"請關上門。","s":"请关上门。","es":"Por favor cierra la puerta.","en":"Please close the door.","p":"qǐng guān shàng mén."},{"c":"他考上大學了。","s":"他考上大学了。","es":"Entró a la universidad.","en":"He got into university.","p":"tā kǎo shàng dà xué le."}]},{"id":"2-12-0","b":2,"l":12,"k":"","t":{"es":"Dejar con 讓","en":"讓 ràng to let someone do something","ens":"让 ràng to let someone do something","tc":"讓","sc":"让"},"d":{"es":"A 讓 B + verbo = A deja / hace que B haga algo (permiso o causa).","en":"A 讓 B + verb means A lets / makes B do something (permission or cause).","tc":"「A 讓 B ＋動詞」表示 A 允許或使 B 去做某件事。","sc":"「A 让 B ＋动词」表示 A 允许或使 B 去做某件事。"},"ex":[{"c":"媽媽讓我去玩。","s":"妈妈让我去玩。","es":"Mi mamá me deja ir a jugar.","en":"Mom lets me go play.","p":"mā ma ràng wǒ qù wán."}]},{"id":"2-12-1","b":2,"l":12,"k":"","t":{"es":"Apúrate con 快一點","en":"快一點 kuài yìdiǎn hurry up","ens":"快一点 kuài yìdiǎn hurry up","tc":"快一點","sc":"快一点"},"d":{"es":"快一點 = ¡date prisa! (petición o mandato suave).","en":"快一點 is a gentle urging: 'hurry up'.","tc":"「快一點」是催促的說法，語氣比較柔和，意思是動作快一點。","sc":"「快一点」是催促的说法，语气比较柔和，意思是动作快一点。"},"ex":[{"c":"快一點，我們要遲到了。","s":"快一点，我们要迟到了。","es":"Apúrate, vamos a llegar tarde.","en":"Hurry up, we're going to be late.","p":"kuài yì diǎn, wǒ men yào chí dào le."}]},{"id":"2-12-2","b":2,"l":12,"k":"","t":{"es":"Mencionar con 起","en":"Verb Particle 起 qǐ to touch upon","ens":"Verb Particle 起 qǐ to touch upon","tc":"V＋起（談起、提起）","sc":"V＋起（谈起、提起）"},"d":{"es":"V + 起 (談起, 提起, 說起, 想起) = empezar a mencionar un tema.","en":"V + 起 (談起, 提起, 說起) means to begin mentioning a topic.","tc":"「V＋起」，例如談起、提起、說起，表示開始提到某個話題。","sc":"「V＋起」，例如谈起、提起、说起，表示开始提到某个话题。"},"ex":[{"c":"他常常談起他的家人。","s":"他常常谈起他的家人。","es":"Habla a menudo de su familia.","en":"He often talks about his family.","p":"tā cháng cháng tán qǐ tā de jiā rén."}]},{"id":"2-12-3","b":2,"l":12,"k":"tiempo momento orden secuencia time order sequence 時間 順序 condicional condición si conditional condition if 條件 假設 如果 tiempo momento orden secuencia time order sequence 时间 顺序 condicional condición si conditional condition if 条件 假设 如果","t":{"es":"Con tal de que 只要…就","en":"只要 zhǐyào……就 jiù… …as long as…","ens":"只要 zhǐyào……就 jiù… …as long as…","tc":"只要…就…","sc":"只要…就…"},"d":{"es":"只要 A 就 B = con tal de que A, B (A es condición suficiente).","en":"只要 A 就 B means 'as long as A, then B' (A is a sufficient condition).","tc":"「只要 A 就 B」表示只需要 A 這個條件，就會有 B。","sc":"「只要 A 就 B」表示只需要 A 这个条件，就会有 B。"},"ex":[{"c":"只要你努力，就會成功。","s":"只要你努力，就会成功。","es":"Con tal de que te esfuerces, tendrás éxito.","en":"As long as you work hard, you will succeed.","p":"zhǐ yào nǐ nǔ lì, jiù huì chéng gōng."}]},{"id":"2-12-4","b":2,"l":12,"k":"","t":{"es":"Cuanto más… con 越…越","en":"越 yuè…越 yuè…the more…, the more…","ens":"越 yuè…越 yuè…the more…, the more…","tc":"越…越…","sc":"越…越…"},"d":{"es":"越 A 越 B = cuanto más A, más B.","en":"越 A 越 B means 'the more A, the more B'.","tc":"「越 A 越 B」表示 A 的程度增加，B 也跟著增加。","sc":"「越 A 越 B」表示 A 的程度增加，B 也跟着增加。"},"ex":[{"c":"他越說越快。","s":"他越说越快。","es":"Cuanto más habla, más rápido habla.","en":"The more he talks, the faster he gets.","p":"tā yuè shuō yuè kuài."}]},{"id":"2-12-5","b":2,"l":12,"k":"","t":{"es":"Tema de contraste","en":"Topic as Contrastive","ens":"Topic as Contrastive","tc":"對比的主題","sc":"对比的主题"},"d":{"es":"Un tema al inicio sirve para contrastar con otro: «en cuanto a A…, pero B…».","en":"Putting a topic at the start of the sentence sets up a contrast: 'as for A…, but B…'.","tc":"把一個主題放在句子開頭，用來和另一件事對比：就 A 來說……，可是 B……。","sc":"把一个主题放在句子开头，用来和另一件事对比：就 A 来说……，可是 B……。"},"ex":[{"c":"中文我會說，可是不會寫。","s":"中文我会说，可是不会写。","es":"El chino sí sé hablarlo, pero no sé escribirlo.","en":"I can speak Chinese, but I can't write it.","p":"zhōng wén wǒ huì shuō, kě shì bú huì xiě."}]},{"id":"2-13-0","b":2,"l":13,"k":"pasado completado terminado past completed finished perfective 完成 過去 experiencia alguna vez haber experience ever 經驗 經歷 pasado completado terminado past completed finished perfective 完成 过去 experiencia alguna vez haber experience ever 经验 经历","t":{"es":"Haber terminado con 過","en":"Completion of Action with V+過 guò","ens":"Completion of Action with V+过 guò","tc":"V＋過（完成）","sc":"V＋过（完成）"},"d":{"es":"V + 過 también indica que ya terminó de hacer algo (acción completada). Se usa sobre todo en preguntas: 吃過飯了嗎？","en":"V + 過 can also mean that an action has already been completed, mostly in questions: 吃過飯了嗎？","tc":"「V＋過」也可以表示已經做完某件事，多用在問句，例如「吃過飯了嗎？」","sc":"「V＋过」也可以表示已经做完某件事，多用在问句，例如「吃过饭了吗？」"},"ex":[{"c":"你吃過飯了嗎？","s":"你吃过饭了吗？","es":"¿Ya comiste?","en":"Have you eaten yet?","p":"nǐ chī guò fàn le ma?"}]},{"id":"2-13-1","b":2,"l":13,"k":"","t":{"es":"Alejarse con 走","en":"Verb Particle 走 zǒu away","ens":"Verb Particle 走 zǒu away","tc":"V＋走","sc":"V＋走"},"d":{"es":"V + 走 = llevarse, irse (alejarse): 拿走, 帶走, 開走.","en":"V + 走 means taking away or leaving: 拿走, 帶走, 開走.","tc":"「V＋走」表示離開或被帶走，例如拿走、帶走、開走。","sc":"「V＋走」表示离开或被带走，例如拿走、带走、开走。"},"ex":[{"c":"他把我的書拿走了。","s":"他把我的书拿走了。","es":"Se llevó mi libro.","en":"He took my book away.","p":"tā bǎ wǒ de shū ná zǒu le."}]},{"id":"2-13-2","b":2,"l":13,"k":"","t":{"es":"Mandar con 叫","en":"Imperative Sentences with 叫 jiào","ens":"Imperative Sentences with 叫 jiào","tc":"叫（命令、要求）","sc":"叫（命令、要求）"},"d":{"es":"A 叫 B + verbo = A manda o pide a B que haga algo.","en":"A 叫 B + verb means A tells / asks B to do something.","tc":"「A 叫 B ＋動詞」表示 A 要求或命令 B 去做某件事。","sc":"「A 叫 B ＋动词」表示 A 要求或命令 B 去做某件事。"},"ex":[{"c":"老師叫我們寫作業。","s":"老师叫我们写作业。","es":"El profesor nos pide hacer la tarea.","en":"The teacher asks us to do the homework.","p":"lǎo shī jiào wǒ men xiě zuò yè."}]},{"id":"2-13-3","b":2,"l":13,"k":"negación negar negativa negation negative 否定 tiempo momento orden secuencia time order sequence 時間 順序 negación negar negativa negation negative 否定 tiempo momento orden secuencia time order sequence 时间 顺序","t":{"es":"Dejar de con 別再…了","en":"別再 bié zài…了 le stop doing it","ens":"别再 bié zài…了 le stop doing it","tc":"別再…了","sc":"别再…了"},"d":{"es":"別再 + verbo + 了 = no lo vuelvas a hacer / deja de hacerlo.","en":"別再 + verb + 了 means 'don't do it again / stop doing it'.","tc":"「別再＋動詞＋了」表示不要再重複做，或叫對方停止。","sc":"「别再＋动词＋了」表示不要再重复做，或叫对方停止。"},"ex":[{"c":"你別再玩手機了。","s":"你别再玩手机了。","es":"Deja de jugar con el celular.","en":"Stop playing with your phone.","p":"nǐ bié zài wán shǒu jī le."}]},{"id":"2-13-4","b":2,"l":13,"k":"poder saber habilidad capacidad permiso posibilidad ability can permission possibility 能力 可能 許可 poder saber habilidad capacidad permiso posibilidad ability can permission possibility 能力 可能 许可","t":{"es":"Seguridad con 會…的","en":"To offer assurance with 會 huì…的 de…","ens":"To offer assurance with 会 huì…的 de…","tc":"會…的（保證）","sc":"会…的（保证）"},"d":{"es":"會…的 expresa seguridad o promesa sobre el futuro: «seguro que…».","en":"會…的 expresses confidence about the future, with a reassuring tone: 'surely…'.","tc":"「會……的」表示說話的人很確定未來會發生，有保證、安慰的語氣。","sc":"「会……的」表示说话的人很确定未来会发生，有保证、安慰的语气。"},"ex":[{"c":"你放心，他會來的。","s":"你放心，他会来的。","es":"Tranquilo, seguro que viene.","en":"Don't worry, he will come.","p":"nǐ fàng xīn, tā huì lái de."}]},{"id":"2-13-5","b":2,"l":13,"k":"","t":{"es":"Por medio de 透過","en":"透過 tòuguò… by means of…","ens":"透过 tòuguò… by means of…","tc":"透過","sc":"透过"},"d":{"es":"透過 + medio o persona = por medio de, a través de.","en":"透過 + means or person means 'through, by means of'.","tc":"「透過＋方法或人」表示經由某個管道或人。","sc":"「透过＋方法或人」表示经由某个管道或人。"},"ex":[{"c":"我是透過朋友認識他的。","s":"我是透过朋友认识他的。","es":"Lo conocí por medio de un amigo.","en":"I met him through a friend.","p":"wǒ shì tòu guò péng yǒu rèn shì tā de."}]},{"id":"2-13-6","b":2,"l":13,"k":"tiempo momento orden secuencia time order sequence 時間 順序 tiempo momento orden secuencia time order sequence 时间 顺序","t":{"es":"才…就…","en":"才 cái…就 jiù… only just…, and…already","ens":"才 cái…就 jiù… only just…, and…already","tc":"才…就…","sc":"才…就…"},"d":{"es":"A 才 B 就 C = apenas A y ya B: algo ocurrió muy pronto.","en":"A 才 B 就 C means 'barely A and already B': something happened very soon.","tc":"「A 才 B 就 C」表示剛剛 A，很快就 B，表示事情發生得很快。","sc":"「A 才 B 就 C」表示刚刚 A，很快就 B，表示事情发生得很快。"},"ex":[{"c":"他才來一個月就學會了。","s":"他才来一个月就学会了。","es":"Apenas llevaba un mes y ya aprendió.","en":"He had been here only a month and had already learned it.","p":"tā cái lái yí ge yuè jiù xué huì le."}]},{"id":"2-13-7","b":2,"l":13,"k":"tiempo momento orden secuencia time order sequence 時間 順序 siempre nunca frecuencia always never frequency 經常 從來 tiempo momento orden secuencia time order sequence 时间 顺序 siempre nunca frecuencia always never frequency 经常 从来","t":{"es":"Frecuencia con 每","en":"Frequency with 每 měi + Time Expression","ens":"Frequency with 每 měi + Time Expression","tc":"每＋時間＋次數","sc":"每＋时间＋次数"},"d":{"es":"每 + tiempo + frecuencia = tantas veces cada…","en":"每 + time + frequency means how many times something happens in each period.","tc":"「每＋時間＋次數」表示在固定的時間裡做幾次。","sc":"「每＋时间＋次数」表示在固定的时间里做几次。"},"ex":[{"c":"我每個星期游泳兩次。","s":"我每个星期游泳两次。","es":"Nado dos veces por semana.","en":"I swim twice a week.","p":"wǒ měi ge xīng qí yóu yǒng liǎng cì."}]},{"id":"2-13-8","b":2,"l":13,"k":"tiempo momento orden secuencia time order sequence 時間 順序 condicional condición si conditional condition if 條件 假設 如果 tiempo momento orden secuencia time order sequence 时间 顺序 condicional condición si conditional condition if 条件 假设 如果","t":{"es":"Solo si con 只有…才","en":"只有 zhǐyǒu…，才 cái… cannot …, unless…","ens":"只有 zhǐyǒu…，才 cái… cannot …, unless…","tc":"只有…才…","sc":"只有…才…"},"d":{"es":"只有 A 才 B = solo si A, B (A es condición necesaria).","en":"只有 A 才 B means 'only if A, then B' (A is a necessary condition).","tc":"「只有 A 才 B」表示 A 是唯一的條件，沒有 A 就不會有 B。","sc":"「只有 A 才 B」表示 A 是唯一的条件，没有 A 就不会有 B。"},"ex":[{"c":"只有多練習，才能說得好。","s":"只有多练习，才能说得好。","es":"Solo practicando mucho se puede hablar bien.","en":"Only with lots of practice can you speak well.","p":"zhǐ yǒu duō liàn xí, cái néng shuō de hǎo."}]},{"id":"2-14-0","b":2,"l":14,"k":"tiempo momento orden secuencia time order sequence 時間 順序 tiempo momento orden secuencia time order sequence 时间 顺序","t":{"es":"A punto de con 就要…了","en":"就要 jiù yào…了 le will soon…","ens":"就要 jiù yào…了 le will soon…","tc":"就要…了","sc":"就要…了"},"d":{"es":"就要 + verbo + 了 = estar a punto de. Es más cercano que 快…了.","en":"就要 + verb + 了 means 'about to happen', closer in time than 快…了.","tc":"「就要＋動詞＋了」表示馬上就要發生，比「快……了」更近。","sc":"「就要＋动词＋了」表示马上就要发生，比「快……了」更近。"},"ex":[{"c":"火車就要開了。","s":"火车就要开了。","es":"El tren está por salir.","en":"The train is about to leave.","p":"huǒ chē jiù yào kāi le."}]},{"id":"2-14-1","b":2,"l":14,"k":"","t":{"es":"Hablando de con 說到","en":"說到 shuōdào/談到 tándào… talking of…","ens":"说到 shuōdào/谈到 tándào… talking of…","tc":"說到／談到","sc":"说到／谈到"},"d":{"es":"說到 / 談到 + tema = hablando de…, cuando se trata de…","en":"說到 / 談到 + topic means 'speaking of…, when it comes to…'.","tc":"「說到／談到＋話題」表示說起某個話題的時候。","sc":"「说到／谈到＋话题」表示说起某个话题的时候。"},"ex":[{"c":"說到台灣小吃，我最喜歡滷肉飯。","s":"说到台湾小吃，我最喜欢卤肉饭。","es":"Hablando de comida callejera de Taiwán, lo que más me gusta es el lu rou fan.","en":"Speaking of Taiwanese street food, my favorite is braised pork rice.","p":"shuō dào tái wān xiǎo chī, wǒ zuì xǐ huān lǔ ròu fàn."}]},{"id":"2-14-2","b":2,"l":14,"k":"","t":{"es":"對A有B","en":"對 duìA 有 yǒu B to be B in A","ens":"对 duìA 有 yǒu B to be B in A","tc":"對…有…","sc":"对…有…"},"d":{"es":"對 A 有 B = hacia A hay B (efecto o sentimiento): 對…有幫助 / 有興趣 / 有信心.","en":"對 A 有 B means B (an effect or feeling) toward A: 對…有幫助 / 有興趣 / 有信心.","tc":"「對 A 有 B」表示對 A 有某種影響或感覺，例如對……有幫助、有興趣、有信心。","sc":"「对 A 有 B」表示对 A 有某种影响或感觉，例如对……有帮助、有兴趣、有信心。"},"ex":[{"c":"運動對身體有幫助。","s":"运动对身体有帮助。","es":"Hacer ejercicio ayuda al cuerpo.","en":"Exercise is good for your body.","p":"yùn dòng duì shēn tǐ yǒu bāng zhù."}]},{"id":"2-14-3","b":2,"l":14,"k":"énfasis enfático incluso emphasis emphatic even 強調 甚至 énfasis enfático incluso emphasis emphatic even 强调 甚至","t":{"es":"Incluso con 連…都","en":"連 lián…都 dōu… even","ens":"连 lián…都 dōu… even","tc":"連…都…","sc":"连…都…"},"d":{"es":"連 A 都 B = incluso A también B. A es el caso extremo.","en":"連 A 都 B means 'even A is B'. A is the extreme case.","tc":"「連 A 都 B」表示連 A 這麼極端的情況也是 B。","sc":"「连 A 都 B」表示连 A 这么极端的情况也是 B。"},"ex":[{"c":"他連飯都沒吃就走了。","s":"他连饭都没吃就走了。","es":"Se fue sin siquiera comer.","en":"He left without even eating.","p":"tā lián fàn dōu méi chī jiù zǒu le."}]},{"id":"2-14-4","b":2,"l":14,"k":"negación negar negativa negation negative 否定 además adición también addition also besides 另外 而且 contraste pero sin embargo contrast but however 對比 轉折 negación negar negativa negation negative 否定 además adición también addition also besides 另外 而且 contraste pero sin embargo contrast but however 对比 转折","t":{"es":"No solo con 不但…而且","en":"不但 búdàn…，而且 érqiě… not only…but also…","ens":"不但 búdàn…，而且 érqiě… not only…but also…","tc":"不但…，而且…","sc":"不但…，而且…"},"d":{"es":"不但 A，而且 B = no solo A sino también B.","en":"不但 A，而且 B means 'not only A but also B'.","tc":"「不但 A，而且 B」表示不只 A，還有 B。","sc":"「不但 A，而且 B」表示不只 A，还有 B。"},"ex":[{"c":"他不但會說中文，而且說得很好。","s":"他不但会说中文，而且说得很好。","es":"No solo habla chino, sino que lo habla muy bien.","en":"Not only can he speak Chinese, he speaks it very well.","p":"tā bú dàn huì shuō zhōng wén, ér qiě shuō de hěn hǎo."}]},{"id":"2-14-5","b":2,"l":14,"k":"disposición objeto complemento disposal object ba 處置 把字句 disposición objeto complemento disposal object ba 处置 把字句","t":{"es":"把 sin querer","en":"Unintentional 把 bǎ Construction","ens":"Unintentional 把 bǎ Construction","tc":"把（非故意）","sc":"把（非故意）"},"d":{"es":"把 + objeto + verbo + complemento puede expresar algo hecho sin querer (un accidente): 弄丟, 弄壞, 忘.","en":"把 + object + verb + complement can also describe something done unintentionally, such as 弄丟, 弄壞, 忘.","tc":"「把＋東西＋動詞＋補語」也可以表示不是故意做的事，例如弄丟、弄壞、忘了。","sc":"「把＋东西＋动词＋补语」也可以表示不是故意做的事，例如弄丢、弄坏、忘了。"},"ex":[{"c":"我把鑰匙弄丟了。","s":"我把钥匙弄丢了。","es":"Perdí las llaves.","en":"I lost my keys.","p":"wǒ bǎ yuè shi nòng diū le."}]},{"id":"2-15-0","b":2,"l":15,"k":"","t":{"es":"Hasta con 到","en":"Post-verbal Preposition 到 dào upto, till","ens":"Post-verbal Preposition 到 dào upto, till","tc":"V＋到（時間、地點）","sc":"V＋到（时间、地点）"},"d":{"es":"V + 到 + tiempo / lugar = hasta (el límite de una acción).","en":"V + 到 + time / place means 'until / up to' (the limit of the action).","tc":"「V＋到＋時間或地點」表示動作持續到某個時間或地點為止。","sc":"「V＋到＋时间或地点」表示动作持续到某个时间或地点为止。"},"ex":[{"c":"我昨天工作到十二點。","s":"我昨天工作到十二点。","es":"Ayer trabajé hasta las doce.","en":"I worked until twelve o'clock yesterday.","p":"wǒ zuó tiān gōng zuò dào shí èr diǎn."}]},{"id":"2-15-1","b":2,"l":15,"k":"","t":{"es":"De uno en uno con 一M一M","en":"Manner 一 M 一 M one at a time","ens":"Manner 一 M 一 M one at a time","tc":"一M一M","sc":"一M一M"},"d":{"es":"一 + clasificador + 一 + clasificador = de uno en uno, poco a poco (manera).","en":"一 + measure word + 一 + measure word means 'one by one' or 'bit by bit'.","tc":"「一＋量詞＋一＋量詞」表示一個接著一個，例如一個一個、一口一口。","sc":"「一＋量词＋一＋量词」表示一个接着一个，例如一个一个、一口一口。"},"ex":[{"c":"請大家一個一個說。","s":"请大家一个一个说。","es":"Por favor hablen uno por uno.","en":"Please speak one by one.","p":"qǐng dà jiā yí ge yí ge shuō."}]},{"id":"2-15-2","b":2,"l":15,"k":"","t":{"es":"Cada vez más con 一M比一M","en":"Intensifying a State with 一 M 一 M more and more X; more X than the last…","ens":"Intensifying a State with 一 M 一 M more and more X; more X than the last…","tc":"一M比一M＋形容詞","sc":"一M比一M＋形容词"},"d":{"es":"一 + clasificador + 比 + 一 + clasificador + adjetivo = cada vez más…","en":"一 + measure word + 比 + 一 + measure word + adjective means 'more and more…'.","tc":"「一＋量詞＋比＋一＋量詞＋形容詞」表示越來越……。","sc":"「一＋量词＋比＋一＋量词＋形容词」表示越来越……。"},"ex":[{"c":"天氣一天比一天冷。","s":"天气一天比一天冷。","es":"Cada día hace más frío.","en":"It gets colder day by day.","p":"tiān qì yì tiān bǐ yì tiān lěng."}]},{"id":"2-15-3","b":2,"l":15,"k":"dirección movimiento direction movement 方向 趨向 dirección movimiento direction movement 方向 趋向","t":{"es":"Empezar con 起來","en":"Inchoative Meaning with 起來 qǐlái","ens":"Inchoative Meaning with 起来 qǐlái","tc":"V／形容詞＋起來（開始）","sc":"V／形容词＋起来（开始）"},"d":{"es":"V / adjetivo + 起來 = empezar a (inicio de una acción o estado).","en":"Verb / adjective + 起來 means starting an action or a state.","tc":"「動詞或形容詞＋起來」表示開始出現某個動作或狀態。","sc":"「动词或形容词＋起来」表示开始出现某个动作或状态。"},"ex":[{"c":"她突然哭起來。","s":"她突然哭起来。","es":"De pronto se puso a llorar.","en":"She suddenly started to cry.","p":"tā tú rán kū qǐ lái."},{"c":"天氣冷起來了。","s":"天气冷起来了。","es":"Empezó a hacer frío.","en":"It is getting cold.","p":"tiān qì lěng qǐ lái le."}]},{"id":"2-15-4","b":2,"l":15,"k":"","t":{"es":"Frases de cuatro caracteres","en":"Four-character Phrases 四字格 sìzìgé","ens":"Four-character Phrases 四字格 sìzìgé","tc":"四字格","sc":"四字格"},"d":{"es":"Las expresiones de cuatro caracteres (四字格) condensan una idea y se usan como una unidad fija.","en":"Four-character phrases (四字格) are fixed expressions that express an idea concisely. Learn them as a unit.","tc":"四字格是由四個字組成的固定說法，用來簡短表達一個意思，要當成一個整體來記。","sc":"四字格是由四个字组成的固定说法，用来简短表达一个意思，要当成一个整体来记。"},"ex":[{"c":"這次考試我考得馬馬虎虎。","s":"这次考试我考得马马虎虎。","es":"En este examen me fue así así.","en":"I did so-so on this exam.","p":"zhè cì kǎo shì wǒ kǎo dé mǎ mǎ hǔ hǔ."}]},{"id":"3-1-0","b":3,"l":1,"k":"condicional condición si conditional condition if 條件 假設 如果 condicional condición si conditional condition if 条件 假设 如果","t":{"es":"Si…: …的話","en":"…的話 if, supposing","ens":"…的话 if, supposing","tc":"…的話","sc":"…的话"},"d":{"es":"A 的話，B = si A, entonces B (condicional coloquial). Se combina con 如果 / 要是.","en":"A 的話，B = if A, then B (colloquial conditional). Often used with 如果 or 要是.","tc":"A 的話，B：如果 A 發生，就 B。口語常和「如果」「要是」一起用。","sc":"A 的话，B：如果 A 发生，就 B。口语常和「如果」「要是」一起用。"},"ex":[{"c":"如果你有空的話，我們一起去吧。","s":"如果你有空的话，我们一起去吧。","es":"Si tienes tiempo, vamos juntos.","en":"If you have time, let's go together.","p":"rú guǒ nǐ yǒu kòng de huà, wǒ men yì qǐ qù ba."}]},{"id":"3-1-1","b":3,"l":1,"k":"negación negar negativa negation negative 否定 negación negar negativa negation negative 否定","t":{"es":"Menos de: 不到","en":"不到 less than","ens":"不到 less than","tc":"不到","sc":"不到"},"d":{"es":"不到 + cantidad = menos de.","en":"不到 + quantity = less than that amount.","tc":"不到＋數量：比那個數量還少。","sc":"不到＋数量：比那个数量还少。"},"ex":[{"c":"我等了不到十分鐘。","s":"我等了不到十分钟。","es":"Esperé menos de diez minutos.","en":"I waited less than ten minutes.","p":"wǒ děng le bú dào shí fēn zhōng."}]},{"id":"3-1-2","b":3,"l":1,"k":"tiempo momento orden secuencia time order sequence 時間 順序 tiempo momento orden secuencia time order sequence 时间 顺序","t":{"es":"Por poco: 差一點","en":"差一點（就）… almost","ens":"差一点（就）… almost","tc":"差一點","sc":"差一点"},"d":{"es":"差一點(就) + verbo = por poco ocurre (pero no ocurrió).","en":"差一點(就) + verb = almost happened, but in the end did not.","tc":"差一點(就)＋動詞：幾乎發生，但最後沒發生。","sc":"差一点(就)＋动词：几乎发生，但最后没发生。"},"ex":[{"c":"我差一點就遲到了。","s":"我差一点就迟到了。","es":"Por poco llego tarde.","en":"I almost was late.","p":"wǒ chā yì diǎn jiù chí dào le."}]},{"id":"3-1-3","b":3,"l":1,"k":"","t":{"es":"Me temo que: 恐怕","en":"恐怕… probably","ens":"恐怕… probably","tc":"恐怕","sc":"恐怕"},"d":{"es":"恐怕 = me temo que, probablemente (sobre algo desfavorable).","en":"恐怕 = I'm afraid that…, probably (about something undesirable).","tc":"恐怕：擔心或推測不太好的事情可能會發生，意思是「我怕…」。","sc":"恐怕：担心或推测不太好的事情可能会发生，意思是「我怕…」。"},"ex":[{"c":"恐怕要下雨了。","s":"恐怕要下雨了。","es":"Me temo que va a llover.","en":"I'm afraid it's going to rain.","p":"kǒng pà yào xià yǔ le."}]},{"id":"3-1-4","b":3,"l":1,"k":"negación negar negativa negation negative 否定 negación negar negativa negation negative 否定","t":{"es":"Por fin: 好不容易","en":"好不容易 finally managed to","ens":"好不容易 finally managed to","tc":"好不容易","sc":"好不容易"},"d":{"es":"好不容易 = con mucha dificultad, por fin logró.","en":"好不容易(才) = after great difficulty, finally managed to.","tc":"好不容易（才）：經過很多困難，終於做到。","sc":"好不容易（才）：经过很多困难，终于做到。"},"ex":[{"c":"我好不容易才買到票。","s":"我好不容易才买到票。","es":"Con mucho trabajo por fin conseguí el boleto.","en":"After a lot of trouble I finally managed to get the ticket.","p":"wǒ hǎo bù róng yì cái mǎi dào piào."}]},{"id":"3-1-5","b":3,"l":1,"k":"tiempo momento orden secuencia time order sequence 時間 順序 tiempo momento orden secuencia time order sequence 时间 顺序","t":{"es":"Decir y hacer: 說…就…","en":"Instantly without Prior Warning with 說…就…","ens":"Instantly without Prior Warning with 说…就…","tc":"說…就…","sc":"说…就…"},"d":{"es":"說 A 就 A = hacer algo en cuanto se dice, sin previo aviso.","en":"說 A 就 A = does it right away as soon as it's said, with no warning.","tc":"說 A 就 A：一說就馬上做，沒有任何預告。","sc":"说 A 就 A：一说就马上做，没有任何预告。"},"ex":[{"c":"他說走就走。","s":"他说走就走。","es":"Dijo que se iba y se fue de inmediato.","en":"He said he was leaving and left right away.","p":"tā shuō zǒu jiù zǒu."}]},{"id":"3-1-6","b":3,"l":1,"k":"negación negar negativa negation negative 否定 negación negar negativa negation negative 否定","t":{"es":"No importa: 不管…都","en":"不管…都 … regardless of whether or not","ens":"不管…都 … regardless of whether or not","tc":"不管…都…","sc":"不管…都…"},"d":{"es":"不管 + pregunta u opciones，都… = no importa…, siempre…","en":"不管 + question or alternatives, 都 + result = no matter what, the result is the same.","tc":"不管＋疑問或選項，都＋結果：不論情況怎麼樣，結果都一樣。","sc":"不管＋疑问或选项，都＋结果：不论情况怎么样，结果都一样。"},"ex":[{"c":"不管天氣好不好，他都去爬山。","s":"不管天气好不好，他都去爬山。","es":"Haga o no haga buen tiempo, él va a la montaña.","en":"Whether the weather is good or not, he goes hiking.","p":"bù guǎn tiān qì hǎo bù hǎo, tā dōu qù pá shān."}]},{"id":"3-2-0","b":3,"l":2,"k":"dirección movimiento direction movement 方向 趨向 dirección movimiento direction movement 方向 趋向","t":{"es":"En general: 一般來說","en":"一般來說 generally speaking","ens":"一般来说 generally speaking","tc":"一般來說","sc":"一般来说"},"d":{"es":"一般來說 = en general, por lo común.","en":"一般來說 = generally, usually (not necessarily every time).","tc":"一般來說：通常的情況是…，不一定每次都這樣。","sc":"一般来说：通常的情况是…，不一定每次都这样。"},"ex":[{"c":"一般來說，學生都很忙。","s":"一般来说，学生都很忙。","es":"En general, los estudiantes están ocupados.","en":"Generally speaking, students are all busy.","p":"yì bān lái shuō, xué shēng dōu hěn máng."}]},{"id":"3-2-1","b":3,"l":2,"k":"","t":{"es":"Verbo comodín: 弄","en":"General Verb 弄","ens":"General Verb 弄","tc":"弄","sc":"弄"},"d":{"es":"弄 es un verbo comodín: «hacer, arreglar, estropear» según el complemento: 弄壞, 弄髒, 弄好.","en":"弄 is an all-purpose verb; its meaning depends on the complement: 弄壞 (break), 弄髒 (dirty), 弄好 (fix).","tc":"「弄」是萬用動詞，意思會跟著後面的補語變，例如弄壞、弄髒、弄好。","sc":"「弄」是万用动词，意思会跟着后面的补语变，例如弄坏、弄脏、弄好。"},"ex":[{"c":"我把手機弄壞了。","s":"我把手机弄坏了。","es":"Descompuse mi celular.","en":"I broke my phone.","p":"wǒ bǎ shǒu jī nòng huài le."}]},{"id":"3-2-2","b":3,"l":2,"k":"tiempo momento orden secuencia time order sequence 時間 順序 además adición también addition also besides 另外 而且 tiempo momento orden secuencia time order sequence 时间 顺序 además adición también addition also besides 另外 而且","t":{"es":"Además: 再說","en":"再說 besides, moreover","ens":"再说 besides, moreover","tc":"再說","sc":"再说"},"d":{"es":"再說 = además, y por si fuera poco (añade otra razón).","en":"再說 = besides, what's more (adds another reason).","tc":"再說：再補充一個理由，意思是「而且」「何況」。","sc":"再说：再补充一个理由，意思是「而且」「何况」。"},"ex":[{"c":"太晚了，再說我也累了，明天再去吧。","s":"太晚了，再说我也累了，明天再去吧。","es":"Es muy tarde, además estoy cansado; vamos mañana.","en":"It's too late, and besides I'm tired too; let's go tomorrow.","p":"tài wǎn le, zài shuō wǒ yě lèi le, míng tiān zài qù ba."}]},{"id":"3-2-3","b":3,"l":2,"k":"","t":{"es":"Convertir en: V成","en":"V+成 to become, to turn into","ens":"V+成 to become, to turn into","tc":"V成","sc":"V成"},"d":{"es":"V + 成 = convertir, resultar en: 變成, 寫成, 翻成.","en":"Verb + 成 = turn into, convert to: 變成, 寫成, 翻成.","tc":"動詞＋成：表示變成、轉換成另一種東西，例如變成、寫成、翻成。","sc":"动词＋成：表示变成、转换成另一种东西，例如变成、写成、翻成。"},"ex":[{"c":"請把這句話翻成中文。","s":"请把这句话翻成中文。","es":"Por favor traduce esta frase al chino.","en":"Please translate this sentence into Chinese.","p":"qǐng bǎ zhè jù huà fān chéng zhōng wén."}]},{"id":"3-2-4","b":3,"l":2,"k":"","t":{"es":"En realidad no: 並","en":"Contrary to Expectation with 並","ens":"Contrary to Expectation with 并","tc":"並不／並沒有","sc":"并不／并没有"},"d":{"es":"並 + 不 / 沒 = en realidad no. Refuerza una negación contraria a lo que se esperaba.","en":"並 + 不/沒 = actually not; strengthens a negation that goes against expectations.","tc":"並＋不／沒：加強否定，表示事實跟想像或預期不一樣。","sc":"并＋不／没：加强否定，表示事实跟想像或预期不一样。"},"ex":[{"c":"這件事並不難。","s":"这件事并不难。","es":"Este asunto en realidad no es difícil.","en":"This matter is actually not difficult.","p":"zhè jiàn shì bìng bù nán."}]},{"id":"3-2-5","b":3,"l":2,"k":"","t":{"es":"Sobre todo: 尤其是","en":"尤其是 especially","ens":"尤其是 especially","tc":"尤其是","sc":"尤其是"},"d":{"es":"尤其是 = especialmente. Destaca un caso dentro de un grupo.","en":"尤其是 = especially; singles out one case within a group.","tc":"尤其是：在一群裡特別強調其中一個。","sc":"尤其是：在一群里特别强调其中一个。"},"ex":[{"c":"我喜歡水果，尤其是芒果。","s":"我喜欢水果，尤其是芒果。","es":"Me gustan las frutas, sobre todo el mango.","en":"I like fruit, especially mango.","p":"wǒ xǐ huān shuǐ guǒ, yóu qí shì máng guǒ."}]},{"id":"3-2-6","b":3,"l":2,"k":"contraste pero sin embargo contrast but however 對比 轉折 contraste pero sin embargo contrast but however 对比 转折","t":{"es":"No hay remedio: 只好","en":"Concession with 只好 could only, have no choice but to","ens":"Concession with 只好 could only, have no choice but to","tc":"只好","sc":"只好"},"d":{"es":"只好 + verbo = no queda más remedio que…","en":"只好 + verb = have no choice but to.","tc":"只好＋動詞：沒有別的辦法，只能這樣做。","sc":"只好＋动词：没有别的办法，只能这样做。"},"ex":[{"c":"沒有車，我們只好走路去。","s":"没有车，我们只好走路去。","es":"No hay coche, así que no nos queda más que ir caminando.","en":"There's no car, so we have no choice but to walk.","p":"méi yǒu chē, wǒ men zhǐ hǎo zǒu lù qù."}]},{"id":"3-3-0","b":3,"l":3,"k":"pasiva voz pasiva passive 被動 被字句 pasiva voz pasiva passive 被动 被字句","t":{"es":"Influido por: 受到…影響","en":"受到…的影響 to be influenced by, affected by","ens":"受到…的影响 to be influenced by, affected by","tc":"受到…的影響","sc":"受到…的影响"},"d":{"es":"受到 + X + 的影響 = ser influenciado por X.","en":"受到 + X + 的影響 = to be influenced by X.","tc":"受到＋人事物＋的影響：被某人或某事影響。","sc":"受到＋人事物＋的影响：被某人或某事影响。"},"ex":[{"c":"他受到爸爸的影響，也喜歡音樂。","s":"他受到爸爸的影响，也喜欢音乐。","es":"Influido por su papá, a él también le gusta la música.","en":"Influenced by his dad, he likes music too.","p":"tā shòu dào bà ba de yǐng xiǎng, yě xǐ huān yīn yuè."}]},{"id":"3-3-1","b":3,"l":3,"k":"","t":{"es":"Menos mal: 幸虧","en":"幸虧… fortunately…","ens":"幸亏… fortunately…","tc":"幸虧","sc":"幸亏"},"d":{"es":"幸虧 A，B = por suerte A, (de lo contrario habría pasado algo malo).","en":"幸虧 A, B = fortunately A (otherwise something bad would have happened).","tc":"幸虧 A，B：因為有 A 這個好運，才沒有發生不好的事。","sc":"幸亏 A，B：因为有 A 这个好运，才没有发生不好的事。"},"ex":[{"c":"幸虧你提醒我，不然我忘了。","s":"幸亏你提醒我，不然我忘了。","es":"Menos mal que me lo recordaste, si no, lo habría olvidado.","en":"Luckily you reminded me, otherwise I would have forgotten.","p":"xìng kuī nǐ tí xǐng wǒ, bù rán wǒ wàng le."}]},{"id":"3-3-2","b":3,"l":3,"k":"","t":{"es":"Se puede considerar: 算是","en":"算是… can be considered…","ens":"算是… can be considered…","tc":"算是","sc":"算是"},"d":{"es":"算是 = se puede considerar (aunque no del todo).","en":"算是 = can be considered (though not entirely).","tc":"算是：雖然不是百分之百，但可以這樣看。","sc":"算是：虽然不是百分之百，但可以这样看。"},"ex":[{"c":"這家店算是很有名的。","s":"这家店算是很有名的。","es":"Esta tienda se puede considerar muy famosa.","en":"This shop can be considered quite famous.","p":"zhè jiā diàn suàn shì hěn yǒu míng de."}]},{"id":"3-3-3","b":3,"l":3,"k":"","t":{"es":"Sí que: 是…","en":"是… It is indeed true that…","ens":"是… It is indeed true that…","tc":"是（強調）","sc":"是（强调）"},"d":{"es":"是 acentuado antes de un adjetivo o verbo confirma algo: «sí que», «en efecto».","en":"A stressed 是 before an adjective or verb confirms something: 'indeed', 'it's true that'.","tc":"「是」放在形容詞或動詞前面，要重讀，表示確認、承認「的確如此」。","sc":"「是」放在形容词或动词前面，要重读，表示确认、承认「的确如此」。"},"ex":[{"c":"他是很聰明。","s":"他是很聪明。","es":"Es cierto que es muy inteligente.","en":"He is indeed very smart.","p":"tā shì hěn cōng míng."}]},{"id":"3-3-4","b":3,"l":3,"k":"","t":{"es":"Con razón: 難怪","en":"難怪 no wonder","ens":"难怪 no wonder","tc":"難怪","sc":"难怪"},"d":{"es":"難怪 = con razón, no es de extrañar (ahora se entiende la causa).","en":"難怪 = no wonder; now the cause is understood, the result makes sense.","tc":"難怪：知道原因後，覺得結果不奇怪了。","sc":"难怪：知道原因后，觉得结果不奇怪了。"},"ex":[{"c":"他是台灣人，難怪中文說得這麼好。","s":"他是台湾人，难怪中文说得这么好。","es":"Es taiwanés, con razón habla tan bien chino.","en":"He's Taiwanese, no wonder he speaks Chinese so well.","p":"tā shì tái wān rén, nán guài zhōng wén shuō de zhè me hǎo."}]},{"id":"3-3-5","b":3,"l":3,"k":"","t":{"es":"Muchísimo: …死了","en":"A Post-verbal Intensifier 死了 terribly","ens":"A Post-verbal Intensifier 死了 terribly","tc":"…死了","sc":"…死了"},"d":{"es":"Adjetivo / verbo + 死了 = muchísimo (coloquial, para sensaciones intensas).","en":"Adj/verb + 死了 = extremely (colloquial, for strong feelings).","tc":"形容詞或動詞＋死了：非常、極了，口語，多用在強烈的感覺。","sc":"形容词或动词＋死了：非常、极了，口语，多用在强烈的感觉。"},"ex":[{"c":"我累死了。","s":"我累死了。","es":"Estoy muertísimo de cansancio.","en":"I'm dead tired.","p":"wǒ lèi sǐ le."}]},{"id":"3-3-6","b":3,"l":3,"k":"","t":{"es":"Casi: 幾乎","en":"幾乎 almost","ens":"几乎 almost","tc":"幾乎","sc":"几乎"},"d":{"es":"幾乎 = casi (casi todo, casi siempre, casi ocurre).","en":"幾乎 = almost (almost all, almost every day).","tc":"幾乎：差不多、將近，例如幾乎全部、幾乎每天。","sc":"几乎：差不多、将近，例如几乎全部、几乎每天。"},"ex":[{"c":"他幾乎每天都來。","s":"他几乎每天都来。","es":"Viene casi todos los días.","en":"He comes almost every day.","p":"tā jī hū měi tiān dōu lái."}]},{"id":"3-3-7","b":3,"l":3,"k":"","t":{"es":"Algo, un poco: 多少","en":"多少 somewhat","ens":"多少 somewhat","tc":"多少","sc":"多少"},"d":{"es":"多少 + verbo / adjetivo = en alguna medida, algo, aunque sea un poco.","en":"多少 + verb/adjective = to some extent, at least a little.","tc":"多少＋動詞或形容詞：多多少少、至少有一點。","sc":"多少＋动词或形容词：多多少少、至少有一点。"},"ex":[{"c":"他多少知道一點。","s":"他多少知道一点。","es":"Algo sabe, aunque sea un poco.","en":"He knows a little, at least.","p":"tā duō shǎo zhī dào yì diǎn."}]},{"id":"3-3-8","b":3,"l":3,"k":"tiempo momento orden secuencia time order sequence 時間 順序 tiempo momento orden secuencia time order sequence 时间 顺序","t":{"es":"Por más que: 再…也","en":"再…也… no matter how…, still…","ens":"再…也… no matter how…, still…","tc":"再…也…","sc":"再…也…"},"d":{"es":"再 + adjetivo / verbo + 也 = por más… que sea, aun así…","en":"再 + adjective/verb + 也 = no matter how…, still…","tc":"再＋形容詞或動詞＋也：就算程度很高，結果還是一樣。","sc":"再＋形容词或动词＋也：就算程度很高，结果还是一样。"},"ex":[{"c":"再忙我也要吃早餐。","s":"再忙我也要吃早餐。","es":"Por muy ocupado que esté, desayuno.","en":"No matter how busy I am, I eat breakfast.","p":"zài máng wǒ yě yào chī zǎo cān."}]},{"id":"3-4-0","b":3,"l":4,"k":"negación negar negativa negation negative 否定 además adición también addition also besides 另外 而且 contraste pero sin embargo contrast but however 對比 轉折 negación negar negativa negation negative 否定 además adición también addition also besides 另外 而且 contraste pero sin embargo contrast but however 对比 转折","t":{"es":"No solo…también: 不但…還","en":"不但…，還… not only…, but also","ens":"不但…，还… not only…, but also","tc":"不但…，還…","sc":"不但…，还…"},"d":{"es":"不但 A，還 B = no solo A, también B.","en":"不但 A，還 B = not only A, but also B.","tc":"不但 A，還 B：除了 A 以外，還有 B。","sc":"不但 A，还 B：除了 A 以外，还有 B。"},"ex":[{"c":"他不但會唱歌，還會跳舞。","s":"他不但会唱歌，还会跳舞。","es":"No solo canta, también baila.","en":"He can not only sing but also dance.","p":"tā bú dàn huì chàng gē, hái huì tiào wǔ."}]},{"id":"3-4-1","b":3,"l":4,"k":"","t":{"es":"Hablar: 說 vs 談","en":"Speak 說 vs Talk 談","ens":"Speak 说 vs Talk 谈","tc":"說 vs 談","sc":"说 vs 谈"},"d":{"es":"說 = decir o hablar (producir palabras). 談 = conversar o discutir un tema con intercambio.","en":"說 = to say or speak (produce words); 談 = to talk over or discuss a topic back and forth.","tc":"「說」是把話說出口；「談」是就某個主題互相交談、討論。","sc":"「说」是把话说出口；「谈」是就某个主题互相交谈、讨论。"},"ex":[{"c":"他說中文。","s":"他说中文。","es":"Habla chino.","en":"He speaks Chinese.","p":"tā shuō zhōng wén."},{"c":"我們談一談這個問題。","s":"我们谈一谈这个问题。","es":"Hablemos de este problema.","en":"Let's talk about this problem.","p":"wǒ men tán yì tán zhè ge wèn tí."}]},{"id":"3-4-2","b":3,"l":4,"k":"negación negar negativa negation negative 否定 contraste pero sin embargo contrast but however 對比 轉折 negación negar negativa negation negative 否定 contraste pero sin embargo contrast but however 对比 转折","t":{"es":"No es…sino: 不是…而是","en":"…不是…，而是… not…; rather…","ens":"…不是…，而是… not…; rather…","tc":"不是…，而是…","sc":"不是…，而是…"},"d":{"es":"不是 A，而是 B = no es A, sino B.","en":"不是 A，而是 B = it's not A, but B.","tc":"不是 A，而是 B：不是 A，真正的是 B。","sc":"不是 A，而是 B：不是 A，真正的是 B。"},"ex":[{"c":"他不是不想去，而是沒時間。","s":"他不是不想去，而是没时间。","es":"No es que no quiera ir, es que no tiene tiempo.","en":"It's not that he doesn't want to go; he has no time.","p":"tā bú shì bù xiǎng qù, ér shì méi shí jiān."}]},{"id":"3-4-3","b":3,"l":4,"k":"negación negar negativa negation negative 否定 lugar ubicación dónde existencia hay location place existence where 地點 位置 存在 dirección movimiento direction movement 方向 趨向 siempre nunca frecuencia always never frequency 經常 從來 negación negar negativa negation negative 否定 lugar ubicación dónde existencia hay location place existence where 地点 位置 存在 dirección movimiento direction movement 方向 趋向 siempre nunca frecuencia always never frequency 经常 从来","t":{"es":"Nunca: 從來","en":"從來+Negation never","ens":"从来+Negation never","tc":"從來","sc":"从来"},"d":{"es":"從來 + 不 / 沒 (有) = nunca, jamás (hasta ahora).","en":"從來 + 不/沒 = never, not once up to now.","tc":"從來＋不／沒：到現在都沒有過。","sc":"从来＋不／没：到现在都没有过。"},"ex":[{"c":"我從來沒吃過榴槤。","s":"我从来没吃过榴梿。","es":"Nunca he comido durián.","en":"I've never eaten durian.","p":"wǒ cóng lái méi chī guò liú lián."}]},{"id":"3-4-4","b":3,"l":4,"k":"","t":{"es":"Verbo 上: 上課, 上班","en":"Various Meanings of the Verb 上","ens":"Various Meanings of the Verb 上","tc":"動詞「上」","sc":"动词「上」"},"d":{"es":"上 tiene varios sentidos como verbo: 上課, 上班, 上網, 上車 (empezar o ir a una actividad, subir).","en":"上 has several senses as a verb: 上課, 上班, 上網, 上車 (start or go to an activity, get on a vehicle).","tc":"「上」有很多用法，像上課、上班、上網、上車，常表示開始或進入某個活動，或是搭上交通工具。","sc":"「上」有很多用法，像上课、上班、上网、上车，常表示开始或进入某个活动，或是搭上交通工具。"},"ex":[{"c":"他每天坐捷運上班。","s":"他每天坐捷运上班。","es":"Va al trabajo en metro todos los días.","en":"He takes the MRT to work every day.","p":"tā měi tiān zuò jié yùn shàng bān."}]},{"id":"3-4-5","b":3,"l":4,"k":"negación negar negativa negation negative 否定 negación negar negativa negation negative 否定","t":{"es":"Sí o sí: 非…不可","en":"非…不可 it is imperative that…","ens":"非…不可 it is imperative that…","tc":"非…不可","sc":"非…不可"},"d":{"es":"非 A 不可 = es imprescindible A, tiene que ser A.","en":"非 A 不可 = must do A; there's no alternative.","tc":"非 A 不可：一定要 A，不能不。","sc":"非 A 不可：一定要 A，不能不。"},"ex":[{"c":"明天的會，你非來不可。","s":"明天的会，你非来不可。","es":"A la reunión de mañana tienes que venir sí o sí.","en":"You must come to tomorrow's meeting.","p":"míng tiān de huì, nǐ fēi lái bù kě."}]},{"id":"3-4-6","b":3,"l":4,"k":"dirección movimiento direction movement 方向 趨向 dirección movimiento direction movement 方向 趋向","t":{"es":"Para…: 對…來說","en":"對…來說 as far as...is concerned, for","ens":"对…来说 as far as...is concerned, for","tc":"對…來說","sc":"对…来说"},"d":{"es":"對 X 來說 = para X, desde la perspectiva de X.","en":"對 X 來說 = for X, from X's point of view.","tc":"對＋人＋來說：從某人的角度來看。","sc":"对＋人＋来说：从某人的角度来看。"},"ex":[{"c":"對學生來說，睡眠很重要。","s":"对学生来说，睡眠很重要。","es":"Para los estudiantes, dormir es muy importante.","en":"For students, sleep is very important.","p":"duì xué shēng lái shuō, shuì mián hěn zhòng yào."}]},{"id":"3-4-7","b":3,"l":4,"k":"","t":{"es":"Ser exigente: 講究","en":"對…講究 to be discerning, discriminating, particular about","ens":"对…讲究 to be discerning, discriminating, particular about","tc":"對…講究","sc":"对…讲究"},"d":{"es":"對 X 很講究 = ser exigente o cuidadoso con X.","en":"對 X 很講究 = to be particular or demanding about X.","tc":"對＋事情＋很講究：對這件事要求很高、很在意。","sc":"对＋事情＋很讲究：对这件事要求很高、很在意。"},"ex":[{"c":"他對吃很講究。","s":"他对吃很讲究。","es":"Es muy exigente con la comida.","en":"He's very particular about food.","p":"tā duì chī hěn jiǎng jiù."}]},{"id":"3-5-0","b":3,"l":5,"k":"complemento resultado potencial complement result potential 補語 結果補語 可能補語 complemento resultado potencial complement result potential 补语 结果补语 可能补语","t":{"es":"Lleno de: V滿","en":"Verb Plus Complement V+滿 crowded with","ens":"Verb Plus Complement V+满 crowded with","tc":"V滿","sc":"V满"},"d":{"es":"V + 滿 = llenar: el espacio queda lleno.","en":"Verb + 滿 = the space gets filled up.","tc":"動詞＋滿：空間被填滿了。","sc":"动词＋满：空间被填满了。"},"ex":[{"c":"教室裡坐滿了人。","s":"教室里坐满了人。","es":"El salón está lleno de gente sentada.","en":"The classroom is full of people sitting.","p":"jiào shì lǐ zuò mǎn le rén."}]},{"id":"3-5-1","b":3,"l":5,"k":"","t":{"es":"Salir/descubrir: V出","en":"Verb Particle 出 to have emerged","ens":"Verb Particle 出 to have emerged","tc":"V出（來）","sc":"V出（来）"},"d":{"es":"V + 出 (來) = salir o aparecer; también descubrir o distinguir: 想出, 做出, 看出.","en":"Verb + 出(來) = come out or make out, discover: 想出, 做出, 看出.","tc":"動詞＋出（來）：出現、發現或分辨出來，例如想出、做出、看出。","sc":"动词＋出（来）：出现、发现或分辨出来，例如想出、做出、看出。"},"ex":[{"c":"我看不出他是外國人。","s":"我看不出他是外国人。","es":"No me doy cuenta de que sea extranjero.","en":"I can't tell that he is a foreigner.","p":"wǒ kàn bù chū tā shì wài guó rén."}]},{"id":"3-5-2","b":3,"l":5,"k":"comparar comparación comparativo más menos igual semejante comparison compare comparative 比較 比較級 negación negar negativa negation negative 否定 comparar comparación comparativo más menos igual semejante comparison compare comparative 比较 比较级 negación negar negativa negation negative 否定","t":{"es":"No tan bueno: 不如","en":"不如 not as good as","ens":"不如 not as good as","tc":"不如","sc":"不如"},"d":{"es":"A 不如 B = A no es tan bueno como B (B es mejor).","en":"A 不如 B = A is not as good as B.","tc":"A 不如 B：A 沒有 B 好。","sc":"A 不如 B：A 没有 B 好。"},"ex":[{"c":"坐車不如坐捷運方便。","s":"坐车不如坐捷运方便。","es":"Ir en coche no es tan cómodo como ir en metro.","en":"Going by car is not as convenient as taking the MRT.","p":"zuò chē bù rú zuò jié yùn fāng biàn."}]},{"id":"3-5-3","b":3,"l":5,"k":"negación negar negativa negation negative 否定 tiempo momento orden secuencia time order sequence 時間 順序 condicional condición si conditional condition if 條件 假設 如果 negación negar negativa negation negative 否定 tiempo momento orden secuencia time order sequence 时间 顺序 condicional condición si conditional condition if 条件 假设 如果","t":{"es":"Si no…ya: 再不…就…了","en":"Urgent Conditional with 再不…就…了","ens":"Urgent Conditional with 再不…就…了","tc":"再不…就…了","sc":"再不…就…了"},"d":{"es":"再不 A 就 B 了 = si no hacemos A ya, ocurrirá B (urgencia).","en":"再不 A 就 B 了 = if we don't do A now, B will happen (urgency).","tc":"再不 A 就 B 了：如果現在還不做 A，馬上就會出問題，有急迫的感覺。","sc":"再不 A 就 B 了：如果现在还不做 A，马上就会出问题，有急迫的感觉。"},"ex":[{"c":"再不走，就來不及了。","s":"再不走，就来不及了。","es":"Si no nos vamos ya, no llegamos.","en":"If we don't leave now, we'll be too late.","p":"zài bù zǒu, jiù lái bù jí le."}]},{"id":"3-5-4","b":3,"l":5,"k":"","t":{"es":"Quitar: V掉","en":"Verb Particle 掉 separated from","ens":"Verb Particle 掉 separated from","tc":"V掉","sc":"V掉"},"d":{"es":"V + 掉 = quitar, eliminar o perder: 丟掉, 吃掉, 忘掉.","en":"Verb + 掉 = get rid of, away, lose: 丟掉, 吃掉, 忘掉.","tc":"動詞＋掉：去掉、消失、失去，例如丟掉、吃掉、忘掉。","sc":"动词＋掉：去掉、消失、失去，例如丢掉、吃掉、忘掉。"},"ex":[{"c":"請把垃圾丟掉。","s":"请把垃圾丢掉。","es":"Por favor tira la basura.","en":"Please throw away the trash.","p":"qǐng bǎ lè sè diū diào."}]},{"id":"3-5-5","b":3,"l":5,"k":"énfasis enfático incluso emphasis emphatic even 強調 甚至 énfasis enfático incluso emphasis emphatic even 强调 甚至","t":{"es":"¡Increíble!: 居然","en":"居然 to one’s surprise","ens":"居然 to one’s surprise","tc":"居然","sc":"居然"},"d":{"es":"居然 = increíblemente, ¡quién lo diría! (sorpresa).","en":"居然 = unexpectedly, surprisingly (expresses surprise).","tc":"居然：沒想到，帶有驚訝的語氣。","sc":"居然：没想到，带有惊讶的语气。"},"ex":[{"c":"他居然忘了今天考試。","s":"他居然忘了今天考试。","es":"¡Increíble, se olvidó del examen de hoy!","en":"He actually forgot there's an exam today!","p":"tā jū rán wàng le jīn tiān kǎo shì."}]},{"id":"3-5-6","b":3,"l":5,"k":"tiempo momento orden secuencia time order sequence 時間 順序 condicional condición si conditional condition if 條件 假設 如果 tiempo momento orden secuencia time order sequence 时间 顺序 condicional condición si conditional condition if 条件 假设 如果","t":{"es":"Ya que: 既然…就","en":"Concession with 既然…（就）… since…(then)…","ens":"Concession with 既然…（就）… since…(then)…","tc":"既然…（就）…","sc":"既然…（就）…"},"d":{"es":"既然 A (就) B = ya que A, entonces B (A es un hecho aceptado).","en":"既然 A，(就) B = since A is already the case, then B.","tc":"既然 A，（就）B：A 已經是事實，所以接著 B。","sc":"既然 A，（就）B：A 已经是事实，所以接着 B。"},"ex":[{"c":"既然你累了，就早點休息吧。","s":"既然你累了，就早点休息吧。","es":"Ya que estás cansado, descansa temprano.","en":"Since you're tired, get some rest early.","p":"jì rán nǐ lèi le, jiù zǎo diǎn xiū xí ba."}]},{"id":"3-5-7","b":3,"l":5,"k":"negación negar negativa negation negative 否定 negación negar negativa negation negative 否定","t":{"es":"No parar: V個不停","en":"V+個不停 keep on…","ens":"V+个不停 keep on…","tc":"V個不停","sc":"V个不停"},"d":{"es":"V + 個不停 = no parar de hacer algo.","en":"Verb + 個不停 = keep doing, can't stop.","tc":"動詞＋個不停：一直做，停不下來。","sc":"动词＋个不停：一直做，停不下来。"},"ex":[{"c":"孩子哭個不停。","s":"孩子哭个不停。","es":"El niño no deja de llorar.","en":"The child keeps crying.","p":"hái zi kū gè bù tíng."}]},{"id":"3-6-0","b":3,"l":6,"k":"tiempo momento orden secuencia time order sequence 時間 順序 causa razón porque consecuencia resultado cause reason because consequence result 原因 結果 因果 tiempo momento orden secuencia time order sequence 时间 顺序 causa razón porque consecuencia resultado cause reason because consequence result 原因 结果 因果","t":{"es":"Justo por: 因為…才","en":"因為…才… only because…","ens":"因为…才… only because…","tc":"因為…才…","sc":"因为…才…"},"d":{"es":"因為 A 才 B = justamente por A es que B.","en":"因為 A 才 B = it's precisely because of A that B happens.","tc":"因為 A 才 B：正是因為 A，所以 B 才會發生。","sc":"因为 A 才 B：正是因为 A，所以 B 才会发生。"},"ex":[{"c":"就是因為你幫我，我才成功。","s":"就是因为你帮我，我才成功。","es":"Fue justo porque tú me ayudaste que tuve éxito.","en":"It was precisely because you helped me that I succeeded.","p":"jiù shì yīn wèi nǐ bāng wǒ, wǒ cái chéng gōng."}]},{"id":"3-6-1","b":3,"l":6,"k":"negación negar negativa negation negative 否定 contraste pero sin embargo contrast but however 對比 轉折 negación negar negativa negation negative 否定 contraste pero sin embargo contrast but however 对比 转折","t":{"es":"Y encima: …不說，…也…","en":"Complaining with …S1…不說，S2 也… not merely, but also","ens":"Complaining with …S1…不说，S2 也… not merely, but also","tc":"…不說，…也…","sc":"…不说，…也…"},"d":{"es":"S1 … 不說，S2 也… = no solo S1, además S2 (para quejarse de algo que se suma).","en":"S1 …不說，S2 也… = not to mention S1, S2 too (used to complain).","tc":"S1 不說，S2 也…：除了前面那件事，後面還有另一件，常用來抱怨。","sc":"S1 不说，S2 也…：除了前面那件事，后面还有另一件，常用来抱怨。"},"ex":[{"c":"他遲到不說，也不道歉。","s":"他迟到不说，也不道歉。","es":"Llegó tarde y encima no pidió disculpas.","en":"He was late, and on top of that he didn't apologize.","p":"tā chí dào bù shuō, yě bú dào qiàn."}]},{"id":"3-6-2","b":3,"l":6,"k":"tiempo momento orden secuencia time order sequence 時間 順序 además adición también addition also besides 另外 而且 tiempo momento orden secuencia time order sequence 时间 顺序 además adición también addition also besides 另外 而且","t":{"es":"Sumado a: 再加上","en":"再加上 furthermore","ens":"再加上 furthermore","tc":"再加上","sc":"再加上"},"d":{"es":"再加上 = sumado a, además. Añade otra razón.","en":"再加上 = on top of that, adds another reason.","tc":"再加上：再多加一個原因。","sc":"再加上：再多加一个原因。"},"ex":[{"c":"天氣冷，再加上下雨，我不想出門。","s":"天气冷，再加上下雨，我不想出门。","es":"Hace frío y además llueve, no quiero salir.","en":"It's cold, and it's raining too; I don't want to go out.","p":"tiān qì lěng, zài jiā shàng xià yǔ, wǒ bù xiǎng chū mén."}]},{"id":"3-6-3","b":3,"l":6,"k":"tiempo momento orden secuencia time order sequence 時間 順序 contraste pero sin embargo contrast but however 對比 轉折 tiempo momento orden secuencia time order sequence 时间 顺序 contraste pero sin embargo contrast but however 对比 转折","t":{"es":"De todo, pero: 什麼都…就是","en":"什麼都…，就是… everything but …","ens":"什么都…，就是… everything but …","tc":"什麼都…，就是…","sc":"什么都…，就是…"},"d":{"es":"什麼都 A，就是 B = de todo A, pero no B.","en":"什麼都 A，就是 B = anything is fine, except B.","tc":"什麼都 A，就是 B：什麼都可以，只有 B 例外。","sc":"什么都 A，就是 B：什么都可以，只有 B 例外。"},"ex":[{"c":"我什麼都吃，就是不吃香菜。","s":"我什么都吃，就是不吃香菜。","es":"Como de todo, menos cilantro.","en":"I eat everything, except cilantro.","p":"wǒ shén me dōu chī, jiù shì bù chī xiāng cài."}]},{"id":"3-6-4","b":3,"l":6,"k":"","t":{"es":"Preferir…: 寧可…也要","en":"寧可…也要… would rather…, in order to…","ens":"宁可…也要… would rather…, in order to…","tc":"寧可…也要…","sc":"宁可…也要…"},"d":{"es":"寧可 A 也要 B = preferir A antes que renunciar a B (sacrificio).","en":"寧可 A 也要 B = would rather give up A than not get B.","tc":"寧可 A 也要 B：願意犧牲 A，也一定要做到 B。","sc":"宁可 A 也要 B：愿意牺牲 A，也一定要做到 B。"},"ex":[{"c":"他寧可不睡覺也要把書看完。","s":"他宁可不睡觉也要把书看完。","es":"Prefiere no dormir con tal de terminar el libro.","en":"He'd rather not sleep than not finish the book.","p":"tā nìng kě bú shuì jiào yě yào bǎ shū kàn wán."}]},{"id":"3-6-5","b":3,"l":6,"k":"comparar comparación comparativo más menos igual semejante comparison compare comparative 比較 比較級 comparar comparación comparativo más menos igual semejante comparison compare comparative 比较 比较级","t":{"es":"Como…: 像…的+N","en":"像…的+noun such (nouns) as","ens":"像…的+noun such (nouns) as","tc":"像…的＋名詞","sc":"像…的＋名词"},"d":{"es":"像 X 的 N = N como X (da ejemplos de una categoría).","en":"像 X 的 N = N such as X (X gives examples of the category).","tc":"像 X 的 N：用 X 當例子說明這一類東西。","sc":"像 X 的 N：用 X 当例子说明这一类东西。"},"ex":[{"c":"像芒果、西瓜的水果，我都喜歡。","s":"像芒果、西瓜的水果，我都喜欢。","es":"Frutas como el mango y la sandía, me gustan todas.","en":"I like fruits such as mango and watermelon.","p":"xiàng máng guǒ, xī guā de shuǐ guǒ, wǒ dōu xǐ huān."}]},{"id":"3-6-6","b":3,"l":6,"k":"","t":{"es":"Por un lado: 一方面…","en":"一方面…，一方面… on the one hand, …, on the other","ens":"一方面…，一方面… on the one hand, …, on the other","tc":"一方面…，一方面…","sc":"一方面…，一方面…"},"d":{"es":"一方面 A，一方面 B = por un lado A, por otro lado B.","en":"一方面 A，一方面 B = on the one hand A, on the other hand B.","tc":"一方面 A，一方面 B：同時有兩件事或兩個角度。","sc":"一方面 A，一方面 B：同时有两件事或两个角度。"},"ex":[{"c":"一方面要工作，一方面要念書，很累。","s":"一方面要工作，一方面要念书，很累。","es":"Por un lado trabajar y por otro estudiar, es agotador.","en":"On the one hand I have to work, on the other I have to study; it's tiring.","p":"yì fāng miàn yào gōng zuò, yì fāng miàn yào niàn shū, hěn lèi."}]},{"id":"3-6-7","b":3,"l":6,"k":"progresivo continuo estar haciendo presente progressive continuous ongoing 進行 持續 progresivo continuo estar haciendo presente progressive continuous ongoing 进行 持续","t":{"es":"A medida que: 隨著","en":"隨著 S1…，S2 也… as a consequence of…","ens":"随着 S1…，S2 也… as a consequence of…","tc":"隨著…，…也…","sc":"随着…，…也…"},"d":{"es":"隨著 X，Y 也… = a medida que X, Y también…","en":"隨著 X，Y 也… = as X changes, Y changes too.","tc":"隨著 X，Y 也…：X 改變時，Y 跟著改變。","sc":"随着 X，Y 也…：X 改变时，Y 跟着改变。"},"ex":[{"c":"隨著年紀增加，他的想法也不一樣了。","s":"随着年纪增加，他的想法也不一样了。","es":"A medida que crece, sus ideas también cambian.","en":"As he gets older, his way of thinking also changes.","p":"suí zhe nián jì zēng jiā, tā de xiǎng fǎ yě bù yí yàng le."}]},{"id":"3-7-0","b":3,"l":7,"k":"","t":{"es":"Sin cuidado: 亂+V","en":"亂＋V to do something in an irresponsible manner,","ens":"乱＋V to do something in an irresponsible manner,","tc":"亂＋動詞","sc":"乱＋动词"},"d":{"es":"亂 + verbo = hacer algo sin orden ni cuidado.","en":"亂 + verb = do something carelessly or without order.","tc":"亂＋動詞：沒有規矩、沒有秩序地做某件事。","sc":"乱＋动词：没有规矩、没有秩序地做某件事。"},"ex":[{"c":"不要亂丟垃圾。","s":"不要乱丢垃圾。","es":"No tires basura por cualquier lado.","en":"Don't litter.","p":"bú yào luàn diū lè sè."}]},{"id":"3-7-1","b":3,"l":7,"k":"","t":{"es":"Cada uno: 各V各的","en":"各 V 各的 each doing her/his own…","ens":"各 V 各的 each doing her/his own…","tc":"各V各的","sc":"各V各的"},"d":{"es":"各 V 各的 = cada uno hace lo suyo.","en":"各 V 各的 = everyone does their own thing.","tc":"各 V 各的：大家各做各的事，互不相干。","sc":"各 V 各的：大家各做各的事，互不相干。"},"ex":[{"c":"吃飯的時候，大家各玩各的手機。","s":"吃饭的时候，大家各玩各的手机。","es":"Mientras comen, cada uno juega con su celular.","en":"During meals, everyone plays with their own phone.","p":"chī fàn de shí hòu, dà jiā gè wán gè de shǒu jī."}]},{"id":"3-7-2","b":3,"l":7,"k":"tiempo momento orden secuencia time order sequence 時間 順序 condicional condición si conditional condition if 條件 假設 如果 tiempo momento orden secuencia time order sequence 时间 顺序 condicional condición si conditional condition if 条件 假设 如果","t":{"es":"Aunque: 就算…也","en":"就算…，也… even if…(S1) …, would…(S2)…","ens":"就算…，也… even if…(S1) …, would…(S2)…","tc":"就算…，也…","sc":"就算…，也…"},"d":{"es":"就算 A，也 B = aunque A (hipótesis), igual B.","en":"就算 A，也 B = even if A happens, B still holds.","tc":"就算 A，也 B：假設 A 發生，結果還是 B。","sc":"就算 A，也 B：假设 A 发生，结果还是 B。"},"ex":[{"c":"就算下雨，我也要去。","s":"就算下雨，我也要去。","es":"Aunque llueva, voy a ir.","en":"Even if it rains, I'm going.","p":"jiù suàn xià yǔ, wǒ yě yào qù."}]},{"id":"3-7-3","b":3,"l":7,"k":"causa razón porque consecuencia resultado cause reason because consequence result 原因 結果 因果 causa razón porque consecuencia resultado cause reason because consequence result 原因 结果 因果","t":{"es":"Debido a: 因為+N","en":"因為 NP，S… because of NP, S…","ens":"因为 NP，S… because of NP, S…","tc":"因為＋名詞","sc":"因为＋名词"},"d":{"es":"因為 + sustantivo，S… = debido a + sustantivo.","en":"因為 + noun, clause = because of a noun (not a full clause).","tc":"因為＋名詞，句子：說明原因是某個事物，不是一個句子。","sc":"因为＋名词，句子：说明原因是某个事物，不是一个句子。"},"ex":[{"c":"因為天氣，比賽取消了。","s":"因为天气，比赛取消了。","es":"Por el clima, se canceló el partido.","en":"Because of the weather, the game was canceled.","p":"yīn wèi tiān qì, bǐ sài qǔ xiāo le."}]},{"id":"3-7-4","b":3,"l":7,"k":"dirección movimiento direction movement 方向 趨向 dirección movimiento direction movement 方向 趋向","t":{"es":"Primero…segundo: 一來…二來","en":"一來…，二來… on the one hand…, and on the other…; first…, second…","ens":"一来…，二来… on the one hand…, and on the other…; first…, second…","tc":"一來…，二來…","sc":"一来…，二来…"},"d":{"es":"一來 A，二來 B = primero A, segundo B (enumera razones).","en":"一來 A，二來 B = first A, second B (lists two reasons).","tc":"一來 A，二來 B：列出兩個理由。","sc":"一来 A，二来 B：列出两个理由。"},"ex":[{"c":"我不去，一來太遠，二來沒時間。","s":"我不去，一来太远，二来没时间。","es":"No voy: primero, está muy lejos; segundo, no tengo tiempo.","en":"I'm not going: first, it's too far; second, I have no time.","p":"wǒ bú qù, yì lái tài yuǎn, èr lái méi shí jiān."}]},{"id":"3-7-5","b":3,"l":7,"k":"dirección movimiento direction movement 方向 趨向 dirección movimiento direction movement 方向 趋向","t":{"es":"De un lado a otro: V來V去","en":"Repetitively, Back and Forth with V 來 V 去","ens":"Repetitively, Back and Forth with V 来 V 去","tc":"V來V去","sc":"V来V去"},"d":{"es":"V 來 V 去 = hacer algo de aquí para allá o una y otra vez.","en":"V 來 V 去 = do the same action back and forth, or over and over.","tc":"V 來 V 去：同一個動作來回做，或一直重複。","sc":"V 来 V 去：同一个动作来回做，或一直重复。"},"ex":[{"c":"他走來走去。","s":"他走来走去。","es":"Camina de un lado a otro.","en":"He walks back and forth.","p":"tā zǒu lái zǒu qù."},{"c":"我想來想去，還是不去。","s":"我想来想去，还是不去。","es":"Lo pensé y lo pensé, y al final decidí no ir.","en":"I thought it over and over, and still decided not to go.","p":"wǒ xiǎng lái xiǎng qù, hái shì bú qù."}]},{"id":"3-7-6","b":3,"l":7,"k":"negación negar negativa negation negative 否定 tiempo momento orden secuencia time order sequence 時間 順序 negación negar negativa negation negative 否定 tiempo momento orden secuencia time order sequence 时间 顺序","t":{"es":"Ya no: 不再…了","en":"不再…了 not…any more","ens":"不再…了 not…any more","tc":"不再…了","sc":"不再…了"},"d":{"es":"不再 + verbo + 了 = ya no (algo que antes sí se hacía).","en":"不再 + verb + 了 = no longer (used to, but not anymore).","tc":"不再＋動詞＋了：以前會做，現在不做了。","sc":"不再＋动词＋了：以前会做，现在不做了。"},"ex":[{"c":"他不再喝咖啡了。","s":"他不再喝咖啡了。","es":"Ya no toma café.","en":"He doesn't drink coffee anymore.","p":"tā bú zài hē kā fēi le."}]},{"id":"3-8-0","b":3,"l":8,"k":"negación negar negativa negation negative 否定 tiempo momento orden secuencia time order sequence 時間 順序 negación negar negativa negation negative 否定 tiempo momento orden secuencia time order sequence 时间 顺序","t":{"es":"O…o: 不是…就是","en":"不是…就是… if it's not…, then it’s…","ens":"不是…就是… if it's not…, then it’s…","tc":"不是…就是…","sc":"不是…就是…"},"d":{"es":"不是 A 就是 B = o bien A o bien B.","en":"不是 A 就是 B = it's either A or B.","tc":"不是 A 就是 B：只有這兩種可能。","sc":"不是 A 就是 B：只有这两种可能。"},"ex":[{"c":"他週末不是看書就是睡覺。","s":"他周末不是看书就是睡觉。","es":"Los fines de semana o lee o duerme.","en":"On weekends he's either reading or sleeping.","p":"tā zhōu mò bú shì kàn shū jiù shì shuì jiào."}]},{"id":"3-8-1","b":3,"l":8,"k":"","t":{"es":"Olvídalo: 算了","en":"算了 forget it, drop it","ens":"算了 forget it, drop it","tc":"算了","sc":"算了"},"d":{"es":"算了 = déjalo, olvídalo (dejar pasar o renunciar).","en":"算了 = forget it, drop it, let it go.","tc":"算了：不再想了、放棄、不計較。","sc":"算了：不再想了、放弃、不计较。"},"ex":[{"c":"太貴了，算了。","s":"太贵了，算了。","es":"Es muy caro, mejor olvídalo.","en":"It's too expensive, forget it.","p":"tài guì le, suàn le."}]},{"id":"3-8-2","b":3,"l":8,"k":"dirección movimiento direction movement 方向 趨向 dirección movimiento direction movement 方向 趋向","t":{"es":"Así que: 這樣一來","en":"這樣一來 that being the case, that way","ens":"这样一来 that being the case, that way","tc":"這樣一來","sc":"这样一来"},"d":{"es":"這樣一來 = de esta manera, en ese caso (introduce la consecuencia).","en":"這樣一來 = in that case, this way (introduces a consequence).","tc":"這樣一來：這樣的話，接著會出現某個結果。","sc":"这样一来：这样的话，接着会出现某个结果。"},"ex":[{"c":"這樣一來，我們就不用等了。","s":"这样一来，我们就不用等了。","es":"Así ya no tenemos que esperar.","en":"This way, we don't have to wait.","p":"zhè yàng yì lái, wǒ men jiù bú yòng děng le."}]},{"id":"3-8-3","b":3,"l":8,"k":"tiempo momento orden secuencia time order sequence 時間 順序 tiempo momento orden secuencia time order sequence 时间 顺序","t":{"es":"Ya hace tiempo: 早就…了","en":"早就…了 long since…","ens":"早就…了 long since…","tc":"早就…了","sc":"早就…了"},"d":{"es":"早就 + verbo + 了 = hace mucho que ya…","en":"早就 + verb + 了 = already a long time ago.","tc":"早就＋動詞＋了：很久以前就已經…。","sc":"早就＋动词＋了：很久以前就已经…。"},"ex":[{"c":"我早就知道了。","s":"我早就知道了。","es":"Hace tiempo que lo sé.","en":"I knew a long time ago.","p":"wǒ zǎo jiù zhī dào le."}]},{"id":"3-8-4","b":3,"l":8,"k":"lugar ubicación dónde existencia hay location place existence where 地點 位置 存在 lugar ubicación dónde existencia hay location place existence where 地点 位置 存在","t":{"es":"A partir de: 從…起","en":"從…起 starting from…","ens":"从…起 starting from…","tc":"從…起","sc":"从…起"},"d":{"es":"從 + tiempo / lugar + 起 = a partir de.","en":"從 + time/place + 起 = starting from.","tc":"從＋時間或地點＋起：從那裡開始算。","sc":"从＋时间或地点＋起：从那里开始算。"},"ex":[{"c":"從明天起，我要早起。","s":"从明天起，我要早起。","es":"A partir de mañana voy a madrugar.","en":"Starting tomorrow, I'm going to get up early.","p":"cóng míng tiān qǐ, wǒ yào zǎo qǐ."}]},{"id":"3-8-5","b":3,"l":8,"k":"contraste pero sin embargo contrast but however 對比 轉折 contraste pero sin embargo contrast but however 对比 转折","t":{"es":"Sin embargo: 卻","en":"卻 however","ens":"却 however","tc":"卻","sc":"却"},"d":{"es":"卻 = sin embargo, en cambio (contraste inesperado). Va antes del verbo.","en":"卻 = but, however (contrary to expectation), placed before the verb.","tc":"卻：前後意思相反，有「沒想到」的感覺，放在動詞前面。","sc":"却：前后意思相反，有「没想到」的感觉，放在动词前面。"},"ex":[{"c":"他很聰明，卻不愛念書。","s":"他很聪明，却不爱念书。","es":"Es muy inteligente, pero no le gusta estudiar.","en":"He's very smart but doesn't like studying.","p":"tā hěn cōng míng, què bú ài niàn shū."}]},{"id":"3-8-6","b":3,"l":8,"k":"causa razón porque consecuencia resultado cause reason because consequence result 原因 結果 因果 causa razón porque consecuencia resultado cause reason because consequence result 原因 结果 因果","t":{"es":"Por…: 因為…而…","en":"因為…而… therefore, consequently","ens":"因为…而… therefore, consequently","tc":"因為…而…","sc":"因为…而…"},"d":{"es":"因為 X 而 V = por X, (resulta) V. Es una forma más escrita.","en":"因為 X 而 V = because of X, V happens (more literary).","tc":"因為 X 而 V：因為 X，所以 V，比較書面。","sc":"因为 X 而 V：因为 X，所以 V，比较书面。"},"ex":[{"c":"他因為生病而沒來上課。","s":"他因为生病而没来上课。","es":"No vino a clase porque se enfermó.","en":"He didn't come to class because he got sick.","p":"tā yīn wèi shēng bìng ér méi lái shàng kè."}]},{"id":"3-8-7","b":3,"l":8,"k":"","t":{"es":"Tras: 經過","en":"經過 after","ens":"经过 after","tc":"經過","sc":"经过"},"d":{"es":"經過 = pasar por (un lugar) o tras (un proceso o tiempo).","en":"經過 = pass through a place, or after going through a process or period of time.","tc":"經過：走過某個地方，或是經歷一段過程、一段時間之後。","sc":"经过：走过某个地方，或是经历一段过程、一段时间之后。"},"ex":[{"c":"經過一年的努力，他通過了考試。","s":"经过一年的努力，他通过了考试。","es":"Tras un año de esfuerzo, aprobó el examen.","en":"After a year of hard work, he passed the exam.","p":"jīng guò yì nián de nǔ lì, tā tōng guò le kǎo shì."}]},{"id":"3-9-0","b":3,"l":9,"k":"","t":{"es":"Depender de: 靠","en":"靠 to rely on, by means of","ens":"靠 to rely on, by means of","tc":"靠","sc":"靠"},"d":{"es":"靠 = depender de, apoyarse en.","en":"靠 = rely on, depend on.","tc":"靠：依賴、憑著某個人或某件事。","sc":"靠：依赖、凭着某个人或某件事。"},"ex":[{"c":"他靠自己的努力考上大學。","s":"他靠自己的努力考上大学。","es":"Entró a la universidad gracias a su propio esfuerzo.","en":"He got into university through his own effort.","p":"tā kào zì jǐ de nǔ lì kǎo shàng dà xué."}]},{"id":"3-9-1","b":3,"l":9,"k":"contraste pero sin embargo contrast but however 對比 轉折 contraste pero sin embargo contrast but however 对比 转折","t":{"es":"Tanto…como: 既…又","en":"既…又… not merely…, but…as well","ens":"既…又… not merely…, but…as well","tc":"既…又…","sc":"既…又…"},"d":{"es":"既 A 又 B = tanto A como B (dos cualidades; más formal que 又…又…).","en":"既 A 又 B = both A and B (two qualities; more formal than 又…又…).","tc":"既 A 又 B：同時有兩個特點，比「又…又…」更書面。","sc":"既 A 又 B：同时有两个特点，比「又…又…」更书面。"},"ex":[{"c":"這裡既安靜又乾淨。","s":"这里既安静又干净。","es":"Este lugar es tranquilo y limpio.","en":"This place is both quiet and clean.","p":"zhè lǐ jì ān jìng yòu gān jìng."}]},{"id":"3-9-2","b":3,"l":9,"k":"","t":{"es":"Dentro de: 以內","en":"…以內 within …","ens":"…以内 within …","tc":"以內","sc":"以内"},"d":{"es":"以內 = dentro de (un límite de cantidad, tiempo o espacio).","en":"以內 = within (a limit of quantity, time or space).","tc":"以內：不超過某個範圍（數量、時間、空間）。","sc":"以内：不超过某个范围（数量、时间、空间）。"},"ex":[{"c":"請在三天以內回覆。","s":"请在三天以内回复。","es":"Por favor responde en un plazo de tres días.","en":"Please reply within three days.","p":"qǐng zài sān tiān yǐ nèi huí fù."}]},{"id":"3-9-3","b":3,"l":9,"k":"","t":{"es":"Representar: 占","en":"占 to constitute","ens":"占 to constitute","tc":"占","sc":"占"},"d":{"es":"占 = ocupar o representar (una parte o porcentaje).","en":"占 = to take up or make up (a proportion or space).","tc":"占：佔有某個比例或空間。","sc":"占：占有某个比例或空间。"},"ex":[{"c":"女生占全班的一半。","s":"女生占全班的一半。","es":"Las mujeres son la mitad de la clase.","en":"Girls make up half of the class.","p":"nǚ shēng zhàn quán bān de yí bàn."}]},{"id":"3-9-4","b":3,"l":9,"k":"","t":{"es":"En cuanto a: (在)…上","en":"（在） NP 上 regarding NP","ens":"（在） NP 上 regarding NP","tc":"（在）…上","sc":"（在）…上"},"d":{"es":"(在) N 上 = en el aspecto de N, en cuanto a N.","en":"(在) N 上 = in the area of N, regarding N.","tc":"（在）＋名詞＋上：在某方面、就某件事來說。","sc":"（在）＋名词＋上：在某方面、就某件事来说。"},"ex":[{"c":"在學習上，他很認真。","s":"在学习上，他很认真。","es":"En los estudios, él es muy aplicado.","en":"In his studies, he is very diligent.","p":"zài xué xí shàng, tā hěn rèn zhēn."}]},{"id":"3-9-5","b":3,"l":9,"k":"dirección movimiento direction movement 方向 趨向 dirección movimiento direction movement 方向 趋向","t":{"es":"Traer a: 給…帶來","en":"給…帶來 to bring… to…","ens":"给…带来 to bring… to…","tc":"給…帶來…","sc":"给…带来…"},"d":{"es":"給 A 帶來 B = traerle B a A (efecto o consecuencia).","en":"給 A 帶來 B = bring B to A (an effect or consequence).","tc":"給 A 帶來 B：對 A 產生 B 這個影響。","sc":"给 A 带来 B：对 A 产生 B 这个影响。"},"ex":[{"c":"網路給我們帶來很多方便。","s":"网路给我们带来很多方便。","es":"Internet nos trae muchas comodidades.","en":"The internet has brought us a lot of convenience.","p":"wǎng lù gěi wǒ men dài lái hěn duō fāng biàn."}]},{"id":"3-9-6","b":3,"l":9,"k":"causa razón porque consecuencia resultado cause reason because consequence result 原因 結果 因果 causa razón porque consecuencia resultado cause reason because consequence result 原因 结果 因果","t":{"es":"Al final: 結果","en":"結果 consequently, in the end","ens":"结果 consequently, in the end","tc":"結果","sc":"结果"},"d":{"es":"結果 = el resultado fue…, al final (el desenlace de algo).","en":"結果 = in the end, the outcome (often unexpected).","tc":"結果：最後的結局，常和預期不同。","sc":"结果：最后的结局，常和预期不同。"},"ex":[{"c":"我等了很久，結果他沒來。","s":"我等了很久，结果他没来。","es":"Esperé mucho y al final no vino.","en":"I waited a long time, and in the end he didn't come.","p":"wǒ děng le hěn jiǔ, jié guǒ tā méi lái."}]},{"id":"3-10-0","b":3,"l":10,"k":"","t":{"es":"En cuanto a: 至於","en":"Introducing a New Topic with 至於…, as to, as far","ens":"Introducing a New Topic with 至于…, as to, as far","tc":"至於","sc":"至于"},"d":{"es":"至於 = en cuanto a… (cambia a otro tema).","en":"至於 = as for (switches to another topic).","tc":"至於：換一個話題，意思是「說到…的話」。","sc":"至于：换一个话题，意思是「说到…的话」。"},"ex":[{"c":"我去，至於他去不去，我不知道。","s":"我去，至于他去不去，我不知道。","es":"Yo voy; en cuanto a si él va o no, no lo sé.","en":"I'm going; as for whether he's going, I don't know.","p":"wǒ qù, zhì yú tā qù bú qù, wǒ bù zhī dào."}]},{"id":"3-10-1","b":3,"l":10,"k":"","t":{"es":"Depende de: A看B","en":"看 depends on","ens":"看 depends on","tc":"A 看 B","sc":"A 看 B"},"d":{"es":"A 看 B = A depende de B.","en":"A 看 B = A depends on B.","tc":"A 看 B：A 要看 B 的情況才能決定。","sc":"A 看 B：A 要看 B 的情况才能决定。"},"ex":[{"c":"去不去看天氣。","s":"去不去看天气。","es":"Ir o no depende del clima.","en":"Whether we go depends on the weather.","p":"qù bú qù kàn tiān qì."}]},{"id":"3-10-2","b":3,"l":10,"k":"siempre nunca frecuencia always never frequency 經常 從來 siempre nunca frecuencia always never frequency 经常 从来","t":{"es":"Siempre: 一向","en":"一向 all along, has always…","ens":"一向 all along, has always…","tc":"一向","sc":"一向"},"d":{"es":"一向 = siempre (desde antes hasta ahora, como hábito).","en":"一向 = always, all along (from before until now, as a habit).","tc":"一向：從以前到現在都是這樣，已成習慣。","sc":"一向：从以前到现在都是这样，已成习惯。"},"ex":[{"c":"他一向早起。","s":"他一向早起。","es":"Siempre se ha levantado temprano.","en":"He has always gotten up early.","p":"tā yí xiàng zǎo qǐ."}]},{"id":"3-10-3","b":3,"l":10,"k":"dirección movimiento direction movement 方向 趨向 dirección movimiento direction movement 方向 趋向","t":{"es":"Por ejemplo: 拿…來說","en":"拿…來說 take…as an example","ens":"拿…来说 take…as an example","tc":"拿…來說","sc":"拿…来说"},"d":{"es":"拿 X 來說 = tomando X como ejemplo.","en":"拿 X 來說 = take X as an example.","tc":"拿 X 來說：用 X 當例子來說明。","sc":"拿 X 来说：用 X 当例子来说明。"},"ex":[{"c":"拿我自己來說，我就不喜歡吃辣。","s":"拿我自己来说，我就不喜欢吃辣。","es":"Por ejemplo, yo no como picante.","en":"Take myself, for example: I don't like spicy food.","p":"ná wǒ zì jǐ lái shuō, wǒ jiù bù xǐ huān chī là."}]},{"id":"3-10-4","b":3,"l":10,"k":"pasiva voz pasiva passive 被動 被字句 pasiva voz pasiva passive 被动 被字句","t":{"es":"Pasiva formal: 受","en":"Passive Sentences with 受","ens":"Passive Sentences with 受","tc":"被動句「受」","sc":"被动句「受」"},"d":{"es":"受 + sustantivo: 受到歡迎 (ser bien recibido), 受傷 (herirse), 受影響 (ser afectado). Pasiva de estilo más formal.","en":"受 + noun: 受到歡迎 (be welcomed), 受傷 (get hurt), 受影響 (be affected); a more formal passive.","tc":"受＋名詞：受到歡迎、受傷、受影響，比「被」更書面。","sc":"受＋名词：受到欢迎、受伤、受影响，比「被」更书面。"},"ex":[{"c":"這部電影很受歡迎。","s":"这部电影很受欢迎。","es":"Esta película es muy popular.","en":"This movie is very popular.","p":"zhè bù diàn yǐng hěn shòu huān yíng."}]},{"id":"3-10-5","b":3,"l":10,"k":"negación negar negativa negation negative 否定 tiempo momento orden secuencia time order sequence 時間 順序 negación negar negativa negation negative 否定 tiempo momento orden secuencia time order sequence 时间 顺序","t":{"es":"Por cualquier cosa: 動不動就","en":"動不動就… to do something impetuously","ens":"动不动就… to do something impetuously","tc":"動不動就","sc":"动不动就"},"d":{"es":"動不動就 + verbo = a la menor ocasión, por cualquier cosa (negativo).","en":"動不動就 + verb = at the slightest thing; usually negative behavior.","tc":"動不動就＋動詞：一點小事就會…，多用在不好的行為。","sc":"动不动就＋动词：一点小事就会…，多用在不好的行为。"},"ex":[{"c":"他動不動就生氣。","s":"他动不动就生气。","es":"Se enoja por cualquier cosa.","en":"He gets angry at the slightest thing.","p":"tā dòng bu dòng jiù shēng qì."}]},{"id":"3-11-0","b":3,"l":11,"k":"pregunta preguntar interrogativa question ask 疑問 問句 提問 pregunta preguntar interrogativa question ask 疑问 问句 提问","t":{"es":"En realidad: 到底","en":"到底 after all? how on earth…?","ens":"到底 after all? how on earth…?","tc":"到底","sc":"到底"},"d":{"es":"到底 = en realidad, ¿qué demonios…? Insiste en una pregunta.","en":"到底 = on earth, exactly (presses a question); also 'after all'.","tc":"到底：用在問句，想問出真正的答案；也有「畢竟」的意思。","sc":"到底：用在问句，想问出真正的答案；也有「毕竟」的意思。"},"ex":[{"c":"你到底想吃什麼？","s":"你到底想吃什么？","es":"¿Pero qué quieres comer en realidad?","en":"What on earth do you want to eat?","p":"nǐ dào dǐ xiǎng chī shén me?"}]},{"id":"3-11-1","b":3,"l":11,"k":"énfasis enfático incluso emphasis emphatic even 強調 甚至 énfasis enfático incluso emphasis emphatic even 强调 甚至","t":{"es":"Incluso: 甚至","en":"甚至 even","ens":"甚至 even","tc":"甚至","sc":"甚至"},"d":{"es":"甚至 = incluso, hasta (el caso extremo).","en":"甚至 = even (points to an extreme case).","tc":"甚至：連…也，說到更極端的情況。","sc":"甚至：连…也，说到更极端的情况。"},"ex":[{"c":"他很忙，甚至沒有時間吃飯。","s":"他很忙，甚至没有时间吃饭。","es":"Está muy ocupado, incluso no tiene tiempo para comer.","en":"He is so busy that he doesn't even have time to eat.","p":"tā hěn máng, shèn zhì méi yǒu shí jiān chī fàn."}]},{"id":"3-11-2","b":3,"l":11,"k":"","t":{"es":"Entonces: 這麼說","en":"這麼說 that being the case, in that case","ens":"这么说 that being the case, in that case","tc":"這麼說","sc":"这么说"},"d":{"es":"這麼說 = entonces, siendo así… (se concluye a partir de lo que dijo el otro).","en":"這麼說 = in that case, so (drawing a conclusion from what was just said).","tc":"這麼說：根據對方說的話，得出一個結論。","sc":"这么说：根据对方说的话，得出一个结论。"},"ex":[{"c":"這麼說，你已經知道了？","s":"这么说，你已经知道了？","es":"Entonces, ¿ya lo sabías?","en":"So, you already knew?","p":"zhè me shuō, nǐ yǐ jīng zhī dào le?"}]},{"id":"3-11-3","b":3,"l":11,"k":"","t":{"es":"Relacionado con: 跟B有關的A","en":"跟 B 有關的 A A is related to B","ens":"跟 B 有关的 A A is related to B","tc":"跟…有關的…","sc":"跟…有关的…"},"d":{"es":"跟 B 有關的 A = A relacionado con B.","en":"跟 B 有關的 A = A that is related to B.","tc":"跟 B 有關的 A：和 B 有關係的 A。","sc":"跟 B 有关的 A：和 B 有关系的 A。"},"ex":[{"c":"我想看跟台灣歷史有關的書。","s":"我想看跟台湾历史有关的书。","es":"Quiero leer libros sobre la historia de Taiwán.","en":"I want to read books about Taiwan's history.","p":"wǒ xiǎng kàn gēn tái wān lì shǐ yǒu guān de shū."}]},{"id":"3-11-4","b":3,"l":11,"k":"negación negar negativa negation negative 否定 complemento resultado potencial complement result potential 補語 結果補語 可能補語 contraste pero sin embargo contrast but however 對比 轉折 negación negar negativa negation negative 否定 complemento resultado potencial complement result potential 补语 结果补语 可能补语 contraste pero sin embargo contrast but however 对比 转折","t":{"es":"No hay remedio: 不得不","en":"不得不 have no choice but to","ens":"不得不 have no choice but to","tc":"不得不","sc":"不得不"},"d":{"es":"不得不 + verbo = no tener más remedio que, verse obligado a.","en":"不得不 + verb = have no choice but to, forced by circumstances.","tc":"不得不＋動詞：因為情況，沒有別的選擇。","sc":"不得不＋动词：因为情况，没有别的选择。"},"ex":[{"c":"太晚了，我不得不回家。","s":"太晚了，我不得不回家。","es":"Es muy tarde, no tengo más remedio que irme a casa.","en":"It's too late; I have no choice but to go home.","p":"tài wǎn le, wǒ bù dé bù huí jiā."}]},{"id":"3-11-5","b":3,"l":11,"k":"","t":{"es":"Así como: 以及","en":"以及 as well as","ens":"以及 as well as","tc":"以及","sc":"以及"},"d":{"es":"以及 = así como. Une sustantivos (más formal).","en":"以及 = as well as (a more formal 'and', linking nouns).","tc":"以及：「和」的書面說法，連接名詞。","sc":"以及：「和」的书面说法，连接名词。"},"ex":[{"c":"我買了蘋果、香蕉以及芒果。","s":"我买了苹果、香蕉以及芒果。","es":"Compré manzanas, plátanos y mangos.","en":"I bought apples, bananas and mangoes.","p":"wǒ mǎi le píng guǒ, xiāng jiāo yǐ jí máng guǒ."}]},{"id":"3-12-0","b":3,"l":12,"k":"negación negar negativa negation negative 否定 negación negar negativa negation negative 否定","t":{"es":"Solo…: 只不過","en":"只不過… (而已) merely…; nothing more than…","ens":"只不过… (而已) merely…; nothing more than…","tc":"只不過…（而已）","sc":"只不过…（而已）"},"d":{"es":"只不過…(而已) = simplemente, no es más que…","en":"只不過…(而已) = merely, nothing more than.","tc":"只不過…（而已）：只是…，沒有那麼嚴重或特別。","sc":"只不过…（而已）：只是…，没有那么严重或特别。"},"ex":[{"c":"這只不過是一個小問題而已。","s":"这只不过是一个小问题而已。","es":"Esto no es más que un pequeño problema.","en":"This is just a small problem.","p":"zhè zhǐ bú guò shì yí ge xiǎo wèn tí ér yǐ."}]},{"id":"3-12-1","b":3,"l":12,"k":"","t":{"es":"A cargo de: 由","en":"Introducing an Agent with 由","ens":"Introducing an Agent with 由","tc":"由","sc":"由"},"d":{"es":"由 + agente + verbo = a cargo de, por parte de (quien hace algo).","en":"由 + person/unit + verb = to be done by, in charge of.","tc":"由＋人或單位＋動詞：說明由誰負責做。","sc":"由＋人或单位＋动词：说明由谁负责做。"},"ex":[{"c":"這件事由我來做。","s":"这件事由我来做。","es":"De esto me encargo yo.","en":"I'll take care of this.","p":"zhè jiàn shì yóu wǒ lái zuò."}]},{"id":"3-12-2","b":3,"l":12,"k":"pregunta preguntar interrogativa question ask 疑問 問句 提問 pregunta preguntar interrogativa question ask 疑问 问句 提问","t":{"es":"¿Acaso…?: 難道","en":"難道… how could it possibly be true","ens":"难道… how could it possibly be true","tc":"難道…嗎？","sc":"难道…吗？"},"d":{"es":"難道…嗎？ = ¿acaso…? Pregunta retórica.","en":"難道…嗎？ = a rhetorical question: 'surely not?'.","tc":"難道…嗎？：反問句，意思是「不可能吧」。","sc":"难道…吗？：反问句，意思是「不可能吧」。"},"ex":[{"c":"難道你不知道嗎？","s":"难道你不知道吗？","es":"¿Acaso no lo sabías?","en":"Don't tell me you didn't know?","p":"nán dào nǐ bù zhī dào ma?"}]},{"id":"3-12-3","b":3,"l":12,"k":"","t":{"es":"Lleno: 滿","en":"To Reach a Ceiling with 滿","ens":"To Reach a Ceiling with 满","tc":"滿","sc":"满"},"d":{"es":"滿 = llegar al máximo, estar lleno: 客滿, 額滿, 坐滿.","en":"滿 = full to the maximum: 客滿, 額滿, 坐滿.","tc":"滿：到最多了，不能再多，例如客滿、額滿、坐滿。","sc":"满：到最多了，不能再多，例如客满、额满、坐满。"},"ex":[{"c":"今天餐廳客滿了。","s":"今天餐厅客满了。","es":"Hoy el restaurante está lleno.","en":"The restaurant is full today.","p":"jīn tiān cān tīng kè mǎn le."}]},{"id":"3-12-4","b":3,"l":12,"k":"","t":{"es":"Por/para: 為","en":"Beneficiary marker 為","ens":"Beneficiary marker 为","tc":"為＋對象","sc":"为＋对象"},"d":{"es":"為 + beneficiario + verbo = por / para (a favor de).","en":"為 + beneficiary + verb = do something for someone.","tc":"為＋對象＋動詞：替誰、為了誰做某件事。","sc":"为＋对象＋动词：替谁、为了谁做某件事。"},"ex":[{"c":"他為家人工作。","s":"他为家人工作。","es":"Trabaja por su familia.","en":"He works for his family.","p":"tā wéi jiā rén gōng zuò."}]},{"id":"3-12-5","b":3,"l":12,"k":"","t":{"es":"En el aspecto: (在)…方面","en":"（在）…方面 with respect to; regarding","ens":"（在）…方面 with respect to; regarding","tc":"（在）…方面","sc":"（在）…方面"},"d":{"es":"(在) X 方面 = en el aspecto de X, con respecto a X.","en":"(在) X 方面 = in terms of X, with respect to X.","tc":"（在）＋名詞＋方面：就某個方面來說。","sc":"（在）＋名词＋方面：就某个方面来说。"},"ex":[{"c":"在工作方面，他很努力。","s":"在工作方面，他很努力。","es":"En lo laboral, se esfuerza mucho.","en":"In terms of work, he works very hard.","p":"zài gōng zuò fāng miàn, tā hěn nǔ lì."}]},{"id":"4-1-0","b":4,"l":1,"k":"comparar comparación comparativo más menos igual semejante comparison compare comparative 比較 比較級 negación negar negativa negation negative 否定 comparar comparación comparativo más menos igual semejante comparison compare comparative 比较 比较级 negación negar negativa negation negative 否定","t":{"es":"Mejor B que A: 與其…不如","en":"與其 A…不如 B… B rather than A","ens":"与其 A…不如 B… B rather than A","tc":"與其 A，不如 B","sc":"与其 A，不如 B"},"d":{"es":"與其 A，不如 B = en vez de A, es mejor B. Se compara dos opciones y se recomienda la segunda.","en":"Compares two options and says the second is better. 與其 A，不如 B means 'rather than A, it would be better to B'.","tc":"比較兩個選擇，說明第二個比較好。「與其 A，不如 B」是「與其做 A，還不如做 B」的意思。","sc":"比较两个选择，说明第二个比较好。「与其 A，不如 B」是「与其做 A，还不如做 B」的意思。"},"ex":[{"c":"與其在家看電視，不如出去走走。","s":"与其在家看电视，不如出去走走。","es":"En vez de ver televisión en casa, mejor salir a caminar.","en":"Rather than watching TV at home, it's better to go out for a walk.","p":"yǔ qí zài jiā kàn diàn shì, bù rú chū qù zǒu zǒu."}]},{"id":"4-1-1","b":4,"l":1,"k":"tiempo momento orden secuencia time order sequence 時間 順序 contraste pero sin embargo contrast but however 對比 轉折 tiempo momento orden secuencia time order sequence 时间 顺序 contraste pero sin embargo contrast but however 对比 转折","t":{"es":"Contraste con 就","en":"就 on the contrary","ens":"就 on the contrary","tc":"表示對比的「就」","sc":"表示对比的「就」"},"d":{"es":"就 puede marcar un contraste inesperado: «en cambio, sin embargo». Los demás piensan una cosa y esta persona piensa lo contrario.","en":"When others think or do one thing but this person differs, 就 marks the contrast, much like 'whereas' or 'on the contrary'.","tc":"別人的想法或情況是一樣的，但說話的人（或這個人）卻不同，這時可以用「就」表示對比，意思像「卻」「反倒」。","sc":"别人的想法或情况是一样的，但说话的人（或这个人）却不同，这时可以用「就」表示对比，意思像「却」「反倒」。"},"ex":[{"c":"大家都說這部電影很無聊，他就覺得很有意思。","s":"大家都说这部电影很无聊，他就觉得很有意思。","es":"Todos dicen que esta película es aburrida; él, en cambio, la encuentra interesante.","en":"Everyone says this movie is boring, but he finds it interesting.","p":"dà jiā dōu shuō zhè bù diàn yǐng hěn wú liáo, tā jiù jué dé hěn yǒu yì sī."}]},{"id":"4-1-2","b":4,"l":1,"k":"tiempo momento orden secuencia time order sequence 時間 順序 tiempo momento orden secuencia time order sequence 时间 顺序","t":{"es":"Usos de 就 (resumen)","en":"A Summary of the Various Usages of 就","ens":"A Summary of the Various Usages of 就","tc":"「就」的用法總整理","sc":"「就」的用法总整理"},"d":{"es":"Resumen de 就: (1) enseguida, pronto; (2) enfático, «precisamente»; (3) «solo», limita una cantidad; (4) condición y resultado (要是…就…).","en":"Main uses of 就: (1) soon, right away; (2) emphatic 'precisely'; (3) 'only'; (4) linking condition and result (要是…就…).","tc":"「就」常見的用法有：一、很快、馬上（我馬上就到）；二、強調「正是」（這就是……）；三、只有（就我一個人）；四、前後連接（要是……就……）。","sc":"「就」常见的用法有：一、很快、马上（我马上就到）；二、强调「正是」（这就是……）；三、只有（就我一个人）；四、前后连接（要是……就……）。"},"ex":[{"c":"我馬上就到。","s":"我马上就到。","es":"Llego enseguida.","en":"I'll be there right away.","p":"wǒ mǎ shàng jiù dào."},{"c":"這就是我要找的書。","s":"这就是我要找的书。","es":"Este es justamente el libro que busco.","en":"This is exactly the book I'm looking for.","p":"zhè jiù shì wǒ yào zhǎo de shū."}]},{"id":"4-1-3","b":4,"l":1,"k":"negación negar negativa negation negative 否定 tiempo momento orden secuencia time order sequence 時間 順序 siempre nunca frecuencia always never frequency 經常 從來 negación negar negativa negation negative 否定 tiempo momento orden secuencia time order sequence 时间 顺序 siempre nunca frecuencia always never frequency 经常 从来","t":{"es":"Ni A, ni B: 別說…就是","en":"別說 A，就是 B 也… never mind A, even B is the case…","ens":"别说 A，就是 B 也… never mind A, even B is the case…","tc":"別說 A，就是 B 也…","sc":"别说 A，就是 B 也…"},"d":{"es":"別說 A，就是 B 也… = ni hablar de A; incluso B (el caso más fácil) también…. A es el caso más difícil y B el más fácil.","en":"First name the harder thing (A), then say even the easier thing (B) isn't possible either: 'forget A, even B…'.","tc":"先說一件比較難的事（A）都不行，連比較容易的事（B）也不行。意思是「連 B 都……，更不用說 A」。","sc":"先说一件比较难的事（A）都不行，连比较容易的事（B）也不行。意思是「连 B 都……，更不用说 A」。"},"ex":[{"c":"別說跑步，就是走路他也覺得累。","s":"别说跑步，就是走路他也觉得累。","es":"Ni hablar de correr; hasta caminar lo cansa.","en":"Forget running, even walking tires him out.","p":"bié shuō pǎo bù, jiù shì zǒu lù tā yě jué dé lèi."}]},{"id":"4-1-4","b":4,"l":1,"k":"","t":{"es":"Prácticamente: 簡直","en":"簡直 to put it simply and plainly, it seems as if","ens":"简直 to put it simply and plainly, it seems as if","tc":"簡直","sc":"简直"},"d":{"es":"簡直 = es simplemente…, casi como si… Exagera para dar énfasis (admiración o queja).","en":"簡直 exaggerates for emphasis: 'it's practically…', 'it's simply like…'. It can express admiration or complaint.","tc":"「簡直」用來誇張地描述，意思是「幾乎就是」「根本就像」，可以表示讚美，也可以表示抱怨。","sc":"「简直」用来夸张地描述，意思是「几乎就是」「根本就像」，可以表示赞美，也可以表示抱怨。"},"ex":[{"c":"他的中文說得簡直跟台灣人一樣好。","s":"他的中文说得简直跟台湾人一样好。","es":"Habla chino tan bien que parece taiwanés.","en":"He speaks Chinese so well that he sounds just like a Taiwanese person.","p":"tā de zhōng wén shuō de jiǎn zhí gēn tái wān rén yí yàng hǎo."}]},{"id":"4-1-5","b":4,"l":1,"k":"negación negar negativa negation negative 否定 contraste pero sin embargo contrast but however 對比 轉折 negación negar negativa negation negative 否定 contraste pero sin embargo contrast but however 对比 转折","t":{"es":"No llega a tanto: 不至於","en":"不至於 but the situation would not be so bad as to …","ens":"不至于 but the situation would not be so bad as to …","tc":"不至於","sc":"不至于"},"d":{"es":"不至於 = no llega al punto de…, no sería tan grave. Sirve para descartar una posibilidad exagerada.","en":"不至於 says things won't go as far as that; it's used to rule out an exaggerated possibility.","tc":"「不至於」表示事情不會嚴重到那個地步，用來否定一個太誇張的想法。","sc":"「不至于」表示事情不会严重到那个地步，用来否定一个太夸张的想法。"},"ex":[{"c":"只是小感冒，不至於住院吧。","s":"只是小感冒，不至于住院吧。","es":"Es solo un resfriado leve, no creo que haya que hospitalizarlo.","en":"It's just a mild cold; he surely doesn't need to be hospitalized.","p":"zhǐ shì xiǎo gǎn mào, bú zhì yú zhù yuàn ba."}]},{"id":"4-1-6","b":4,"l":1,"k":"","t":{"es":"Por lo general: 往往","en":"往往 usually, tend to","ens":"往往 usually, tend to","tc":"往往","sc":"往往"},"d":{"es":"往往 = por lo general, suele (patrón habitual basado en la experiencia). No se usa para el futuro ni para hechos únicos.","en":"往往 describes what usually happens based on experience. It isn't used for the future or for one-time events.","tc":"「往往」表示照過去的經驗，常常是這樣，有規律性。不能用在未來，也不能用在只發生一次的事。","sc":"「往往」表示照过去的经验，常常是这样，有规律性。不能用在未来，也不能用在只发生一次的事。"},"ex":[{"c":"週末的捷運往往很擠。","s":"周末的捷运往往很挤。","es":"Los fines de semana el metro suele estar lleno.","en":"On weekends the metro is usually crowded.","p":"zhōu mò de jié yùn wǎng wǎng hěn jǐ."}]},{"id":"4-1-7","b":4,"l":1,"k":"progresivo continuo estar haciendo presente progressive continuous ongoing 進行 持續 progresivo continuo estar haciendo presente progressive continuous ongoing 进行 持续","t":{"es":"Por diversión: V 著玩","en":"Do Something Just for Fun V 著玩","ens":"Do Something Just for Fun V 着玩","tc":"V 著玩","sc":"V 着玩"},"d":{"es":"V 著玩 = hacer algo solo por diversión, sin tomarlo en serio.","en":"V 著玩 means doing something just for fun, not seriously.","tc":"「V 著玩」表示只是為了好玩去做，不是認真的。","sc":"「V 着玩」表示只是为了好玩去做，不是认真的。"},"ex":[{"c":"我只是畫著玩，畫得不好。","s":"我只是画着玩，画得不好。","es":"Solo dibujo por diversión, no dibujo bien.","en":"I'm only drawing for fun; I'm not good at it.","p":"wǒ zhǐ shì huà zhe wán, huà de bù hǎo."},{"c":"別當真，他是說著玩的。","s":"别当真，他是说着玩的。","es":"No lo tomes en serio, lo dijo en broma.","en":"Don't take it seriously, he was just joking.","p":"bié dāng zhēn, tā shì shuō zhe wán de."}]},{"id":"4-2-0","b":4,"l":2,"k":"complemento resultado potencial complement result potential 補語 結果補語 可能補語 complemento resultado potencial complement result potential 补语 结果补语 可能补语","t":{"es":"Lograr algo: V 成","en":"Verb Complement 成 successful(ly)","ens":"Verb Complement 成 successful(ly)","tc":"動詞＋成（成功）","sc":"动词＋成（成功）"},"d":{"es":"V + 成 = lograr hacer algo (resultado exitoso). Negación: V 不成 = no se logró.","en":"V + 成 shows that something was achieved successfully. Its negative, V 不成, means it couldn't be done.","tc":"「V＋成」表示事情做成了、成功了。否定用「V 不成」，表示沒辦法完成。","sc":"「V＋成」表示事情做成了、成功了。否定用「V 不成」，表示没办法完成。"},"ex":[{"c":"這筆生意終於談成了。","s":"这笔生意终于谈成了。","es":"Por fin se cerró este negocio.","en":"This deal was finally closed.","p":"zhè bǐ shēng yì zhōng yú tán chéng le."},{"c":"下雨了，我們去不成了。","s":"下雨了，我们去不成了。","es":"Está lloviendo, ya no podemos ir.","en":"It's raining, so we can't go anymore.","p":"xià yǔ le, wǒ men qù bù chéng le."}]},{"id":"4-2-1","b":4,"l":2,"k":"","t":{"es":"Por si acaso: 萬一","en":"萬一 supposing, in the event of something negative","ens":"万一 supposing, in the event of something negative","tc":"萬一","sc":"万一"},"d":{"es":"萬一 = en caso de que (algo malo y poco probable), por si acaso.","en":"萬一 introduces something unlikely but bad if it happened: 'in case…', 'what if…'.","tc":"「萬一」用在可能性很小、但如果發生會很糟的事情，意思是「如果真的……」。","sc":"「万一」用在可能性很小、但如果发生会很糟的事情，意思是「如果真的……」。"},"ex":[{"c":"帶把傘吧，萬一下雨怎麼辦？","s":"带把伞吧，万一下雨怎么办？","es":"Lleva un paraguas, ¿y si llueve?","en":"Bring an umbrella. What if it rains?","p":"dài bǎ sǎn ba, wàn yī xià yǔ zěn me bàn?"}]},{"id":"4-2-2","b":4,"l":2,"k":"","t":{"es":"Creer erróneamente: 以為","en":"以為 to have wrongly thought that…","ens":"以为 to have wrongly thought that…","tc":"以為","sc":"以为"},"d":{"es":"以為 = creer (equivocadamente) que…; la realidad resultó ser distinta.","en":"以為 means you thought something that turned out to be wrong.","tc":"「以為」是自己想的跟事實不一樣，後來才發現弄錯了。","sc":"「以为」是自己想的跟事实不一样，后来才发现弄错了。"},"ex":[{"c":"我以為今天放假，原來要上班。","s":"我以为今天放假，原来要上班。","es":"Creí que hoy era feriado, pero resulta que hay que trabajar.","en":"I thought today was a day off, but it turns out I have to work.","p":"wǒ yǐ wéi jīn tiān fàng jià, yuán lái yào shàng bān."}]},{"id":"4-2-3","b":4,"l":2,"k":"","t":{"es":"El adverbio 可","en":"Adverb 可","ens":"Adverb 可","tc":"副詞「可」","sc":"副词「可」"},"d":{"es":"可 como adverbio da énfasis: «sí que», «de verdad». Se usa en advertencias, exclamaciones y lenguaje coloquial.","en":"The adverb 可 adds emphasis before a verb or adjective, often in reminders, warnings or exclamations. It's colloquial.","tc":"「可」放在動詞或形容詞前面加強語氣，常用在提醒、警告或感嘆，是口語的說法。","sc":"「可」放在动词或形容词前面加强语气，常用在提醒、警告或感叹，是口语的说法。"},"ex":[{"c":"你可別忘了明天的會議！","s":"你可别忘了明天的会议！","es":"¡No te vayas a olvidar de la reunión de mañana!","en":"Don't you forget about tomorrow's meeting!","p":"nǐ kě bié wàng le míng tiān de huì yì!"},{"c":"這家的牛肉麵可好吃了！","s":"这家的牛肉面可好吃了！","es":"¡Los fideos con carne de este lugar sí que están ricos!","en":"The beef noodles here are really delicious!","p":"zhè jiā de niú ròu miàn kě hǎo chī le!"}]},{"id":"4-2-4","b":4,"l":2,"k":"complemento resultado potencial complement result potential 補語 結果補語 可能補語 complemento resultado potencial complement result potential 补语 结果补语 可能补语","t":{"es":"Para evitar que: 免得","en":"免得 lest, so as to avoid","ens":"免得 lest, so as to avoid","tc":"免得","sc":"免得"},"d":{"es":"免得 = para evitar que, no sea que. Introduce la consecuencia no deseada y va en la segunda cláusula.","en":"免得 goes in the second clause: you do something first so as to avoid an unwanted result.","tc":"「免得」放在後面的句子，表示為了避免不好的結果，所以前面先做某件事。","sc":"「免得」放在后面的句子，表示为了避免不好的结果，所以前面先做某件事。"},"ex":[{"c":"你先打電話問一下，免得白跑一趟。","s":"你先打电话问一下，免得白跑一趟。","es":"Llama antes a preguntar, para no ir en balde.","en":"Call and ask first, so you don't make a trip for nothing.","p":"nǐ xiān dǎ diàn huà wèn yí xià, miǎn dé bái pǎo yí tàng."}]},{"id":"4-2-5","b":4,"l":2,"k":"","t":{"es":"Alguna vez: 曾經","en":"曾經 experience in the past, V’ed before","ens":"曾经 experience in the past, V’ed before","tc":"曾經","sc":"曾经"},"d":{"es":"曾經 + V = alguna vez, en el pasado (una experiencia que ya no continúa). Suele ir con 過.","en":"曾經 shows that something happened in the past and no longer holds now. It often appears with 過.","tc":"「曾經」表示過去有過某種經驗，現在已經不是這樣了，常常跟「過」一起用。","sc":"「曾经」表示过去有过某种经验，现在已经不是这样了，常常跟「过」一起用。"},"ex":[{"c":"我曾經在台南住過一年。","s":"我曾经在台南住过一年。","es":"Una vez viví un año en Tainan.","en":"I once lived in Tainan for a year.","p":"wǒ céng jīng zài tái nán zhù guò yì nián."}]},{"id":"4-2-6","b":4,"l":2,"k":"","t":{"es":"Etcétera: 等","en":"Enumeration Particle 等 etc…","ens":"Enumeration Particle 等 etc…","tc":"列舉的「等」","sc":"列举的「等」"},"d":{"es":"等 al final de una lista = etcétera; indica que hay más ejemplos. También se dice 等等.","en":"Add 等 after a list of examples to show there are more; 等等 also works.","tc":"列舉幾個例子後加上「等」，表示還有其他沒說完的，也可以說「等等」。","sc":"列举几个例子后加上「等」，表示还有其他没说完的，也可以说「等等」。"},"ex":[{"c":"夜市有臭豆腐、蚵仔煎、珍珠奶茶等小吃。","s":"夜市有臭豆腐、蚵仔煎、珍珠奶茶等小吃。","es":"En el mercado nocturno hay tofu apestoso, tortilla de ostras, té con perlas, etc.","en":"The night market has stinky tofu, oyster omelet, bubble tea and other snacks.","p":"yè shì yǒu chòu dòu fǔ, kē zǐ jiān, zhēn zhū nǎi chá děng xiǎo chī."}]},{"id":"4-2-7","b":4,"l":2,"k":"","t":{"es":"Lo que…: 所 + verbo","en":"Making a Verb with the Particle 所","ens":"Making a Verb with the Particle 所","tc":"「所」＋動詞","sc":"「所」＋动词"},"d":{"es":"所 + verbo forma una expresión nominal de estilo formal: «lo que…». Ejemplos: 我所知道的, 他所說的.","en":"所 before a verb turns it into a noun-like phrase meaning 'what…' or 'that which…'. It's fairly formal.","tc":"「所」加在動詞前面，可以把一個動作變成名詞性的說法，意思是「……的（事／東西）」，比較書面。","sc":"「所」加在动词前面，可以把一个动作变成名词性的说法，意思是「……的（事／东西）」，比较书面。"},"ex":[{"c":"這就是我所知道的一切。","s":"这就是我所知道的一切。","es":"Esto es todo lo que sé.","en":"This is everything I know.","p":"zhè jiù shì wǒ suǒ zhī dào de yí qiè."},{"c":"他所說的我都同意。","s":"他所说的我都同意。","es":"Estoy de acuerdo con todo lo que dijo.","en":"I agree with everything he said.","p":"tā suǒ shuō de wǒ dōu tóng yì."}]},{"id":"4-3-0","b":4,"l":3,"k":"","t":{"es":"¿Para qué? 何必","en":"何必 why must","ens":"何必 why must","tc":"何必","sc":"何必"},"d":{"es":"何必 = ¿para qué…?, ¿por qué habrías de…? Es una pregunta retórica: no hace falta.","en":"何必 is a rhetorical question meaning 'there's no need to…', often used to persuade someone not to do something.","tc":"「何必」是反問，意思是「不需要」「沒有必要」，常用來勸人不要這樣做。","sc":"「何必」是反问，意思是「不需要」「没有必要」，常用来劝人不要这样做。"},"ex":[{"c":"只是小事，你何必這麼生氣？","s":"只是小事，你何必这么生气？","es":"Es solo una tontería, ¿para qué enojarte tanto?","en":"It's only a small matter. Why get so angry?","p":"zhǐ shì xiǎo shì, nǐ hé bì zhè me shēng qì?"}]},{"id":"4-3-1","b":4,"l":3,"k":"negación negar negativa negation negative 否定 complemento resultado potencial complement result potential 補語 結果補語 可能補語 negación negar negativa negation negative 否定 complemento resultado potencial complement result potential 补语 结果补语 可能补语","t":{"es":"No necesariamente: 不見得","en":"不見得 not necessarily","ens":"不见得 not necessarily","tc":"不見得","sc":"不见得"},"d":{"es":"不見得 = no necesariamente. Niega de forma suave que algo sea siempre así.","en":"不見得 means 'not necessarily'. It's a mild way to say it isn't always as you think.","tc":"「不見得」表示不一定，不一定是你想的那樣，語氣比較委婉。","sc":"「不见得」表示不一定，不一定是你想的那样，语气比较委婉。"},"ex":[{"c":"貴的東西不見得比較好。","s":"贵的东西不见得比较好。","es":"Lo caro no necesariamente es mejor.","en":"Expensive things are not necessarily better.","p":"guì de dōng xi bú jiàn dé bǐ jiào hǎo."}]},{"id":"4-3-2","b":4,"l":3,"k":"","t":{"es":"La partícula 嘛","en":"嘛 isn’t it obvious that","ens":"嘛 isn’t it obvious that","tc":"語氣詞「嘛」","sc":"语气词「嘛」"},"d":{"es":"嘛 al final de la oración es una partícula coloquial: indica que algo es obvio o insiste con un tono de reproche suave.","en":"嘛 at the end of a sentence shows that something is obvious, or adds a gently persuasive or impatient tone. It's colloquial.","tc":"「嘛」放在句尾，表示這件事很明顯、很簡單，或帶一點勸說、不耐煩的語氣，是口語的說法。","sc":"「嘛」放在句尾，表示这件事很明显、很简单，或带一点劝说、不耐烦的语气，是口语的说法。"},"ex":[{"c":"這很簡單嘛，你一定會的。","s":"这很简单嘛，你一定会的。","es":"Esto es fácil, ¿no ves?; seguro que puedes.","en":"It's easy, you know. I'm sure you can do it.","p":"zhè hěn jiǎn dān má, nǐ yí dìng huì de."},{"c":"有問題就問嘛。","s":"有问题就问嘛。","es":"Si tienes dudas, pregunta, ¿no?","en":"If you have a question, just ask!","p":"yǒu wèn tí jiù wèn má."}]},{"id":"4-3-3","b":4,"l":3,"k":"","t":{"es":"Acostumbrarse: V 慣","en":"Verb Particle 慣","ens":"Verb Particle 惯","tc":"動詞＋慣","sc":"动词＋惯"},"d":{"es":"V + 慣 = estar acostumbrado a: 吃慣, 住慣, 用慣. En negativo, 看不慣 = no soportar ver algo.","en":"V + 慣 means being used to something (吃慣, 住慣, 用慣). 看不慣 means you can't stand seeing it.","tc":"「V＋慣」表示習慣了，例如「吃慣」「住慣」「用慣」。否定的「看不慣」是「看了不舒服、無法接受」。","sc":"「V＋惯」表示习惯了，例如「吃惯」「住惯」「用惯」。否定的「看不惯」是「看了不舒服、无法接受」。"},"ex":[{"c":"我已經吃慣台灣菜了。","s":"我已经吃惯台湾菜了。","es":"Ya me acostumbré a la comida taiwanesa.","en":"I'm already used to Taiwanese food.","p":"wǒ yǐ jīng chī guàn tái wān cài le."},{"c":"他看不慣別人亂丟垃圾。","s":"他看不惯别人乱丢垃圾。","es":"No soporta ver que otros tiren basura por cualquier lado.","en":"He can't stand seeing people litter.","p":"tā kàn bú guàn bié rén luàn diū lè sè."}]},{"id":"4-3-4","b":4,"l":3,"k":"complemento resultado potencial complement result potential 補語 結果補語 可能補語 complemento resultado potencial complement result potential 补语 结果补语 可能补语","t":{"es":"No tener fuerzas: V 得動／不動","en":"Verb Complement 動 capable of causing movement","ens":"Verb Complement 动 capable of causing movement","tc":"動詞＋得動／不動","sc":"动词＋得动／不动"},"d":{"es":"V + 得動 / 不動 = tener / no tener fuerza para mover o hacer algo: 搬不動, 走不動, 吃不動.","en":"V + 得動 / 不動 shows whether you have the strength to do something, like 搬不動, 走不動, 吃不動.","tc":"「V＋得動／不動」表示有沒有力氣把一個動作做完，例如「搬不動」「走不動」「吃不動」。","sc":"「V＋得动／不动」表示有没有力气把一个动作做完，例如「搬不动」「走不动」「吃不动」。"},"ex":[{"c":"這個箱子太重了，我搬不動。","s":"这个箱子太重了，我搬不动。","es":"Esta caja pesa demasiado, no puedo moverla.","en":"This box is too heavy; I can't move it.","p":"zhè ge xiāng zi tài zhòng le, wǒ bān bú dòng."},{"c":"我今天累得走不動了。","s":"我今天累得走不动了。","es":"Hoy estoy tan cansado que ya no puedo caminar.","en":"I'm so tired today that I can't walk anymore.","p":"wǒ jīn tiān lèi de zǒu bú dòng le."}]},{"id":"4-3-5","b":4,"l":3,"k":"","t":{"es":"Sin darse cuenta: 無形中","en":"無形中 without knowing it, and before you know it","ens":"无形中 without knowing it, and before you know it","tc":"無形中","sc":"无形中"},"d":{"es":"無形中 = sin darse cuenta, de forma imperceptible y poco a poco.","en":"無形中 means something happens imperceptibly and gradually, without you noticing.","tc":"「無形中」表示不知不覺、慢慢地發生，自己沒有特別注意到。","sc":"「无形中」表示不知不觉、慢慢地发生，自己没有特别注意到。"},"ex":[{"c":"常常看台劇，無形中他的中文進步了。","s":"常常看台剧，无形中他的中文进步了。","es":"Como veía series taiwanesas a menudo, su chino mejoró sin que se diera cuenta.","en":"He watched Taiwanese dramas often, and his Chinese improved without him realizing it.","p":"cháng cháng kàn tái jù, wú xíng zhōng tā de zhōng wén jìn bù le."}]},{"id":"4-3-6","b":4,"l":3,"k":"además adición también addition also besides 另外 而且 además adición también addition also besides 另外 而且","t":{"es":"Además: 此外","en":"此外 in addition, furthermore","ens":"此外 in addition, furthermore","tc":"此外","sc":"此外"},"d":{"es":"此外 = además, aparte de esto. Es un conector de estilo formal que añade otro punto.","en":"此外 is a formal connector meaning 'besides this, there is also…'; it adds another point.","tc":"「此外」是書面的連接詞，意思是「除了這個以外，還有……」，用來再加一點。","sc":"「此外」是书面的连接词，意思是「除了这个以外，还有……」，用来再加一点。"},"ex":[{"c":"這家店的東西很新鮮，此外服務也很好。","s":"这家店的东西很新鲜，此外服务也很好。","es":"Los productos de esta tienda son muy frescos y, además, el servicio es muy bueno.","en":"The food at this shop is very fresh, and the service is great too.","p":"zhè jiā diàn de dōng xi hěn xīn xiān, cǐ wài fú wù yě hěn hǎo."}]},{"id":"4-3-7","b":4,"l":3,"k":"","t":{"es":"En resumen: 總而言之","en":"總而言之 in short","ens":"总而言之 in short","tc":"總而言之","sc":"总而言之"},"d":{"es":"總而言之 = en resumen, en una palabra. Introduce la conclusión.","en":"總而言之 introduces a brief conclusion after several points have been made.","tc":"「總而言之」用在說完幾個看法之後，引出簡短的結論。","sc":"「总而言之」用在说完几个看法之后，引出简短的结论。"},"ex":[{"c":"總而言之，這個方法比較省時間。","s":"总而言之，这个方法比较省时间。","es":"En resumen, este método ahorra más tiempo.","en":"In short, this method saves more time.","p":"zǒng ér yán zhī, zhè ge fāng fǎ bǐ jiào shěng shí jiān."}]},{"id":"4-4-0","b":4,"l":4,"k":"","t":{"es":"Por fin: 總算","en":"總算 finally, speaking roughly (in the ball park)","ens":"总算 finally, speaking roughly (in the ball park)","tc":"總算","sc":"总算"},"d":{"es":"總算 = por fin, finalmente. Expresa alivio después de esperar o esforzarse mucho.","en":"總算 shows that after a long wait or effort, a result finally came, with a sense of relief.","tc":"「總算」表示等了很久或努力很久之後，終於有了結果，帶著鬆了一口氣的感覺。","sc":"「总算」表示等了很久或努力很久之后，终于有了结果，带着松了一口气的感觉。"},"ex":[{"c":"等了三個月，簽證總算下來了。","s":"等了三个月，签证总算下来了。","es":"Después de esperar tres meses, por fin salió la visa.","en":"After waiting three months, the visa has finally come through.","p":"děng le sān ge yuè, qiān zhèng zǒng suàn xià lái le."}]},{"id":"4-4-1","b":4,"l":4,"k":"negación negar negativa negation negative 否定 tiempo momento orden secuencia time order sequence 時間 順序 además adición también addition also besides 另外 而且 negación negar negativa negation negative 否定 tiempo momento orden secuencia time order sequence 时间 顺序 además adición también addition also besides 另外 而且","t":{"es":"No es más que…: 還不就是","en":"還不就是 nothing more than","ens":"还不就是 nothing more than","tc":"還不就是","sc":"还不就是"},"d":{"es":"還不就是 = no es más que…, al fin y al cabo es solo… Resta importancia; tono coloquial.","en":"還不就是 is a colloquial rhetorical phrase meaning 'it's nothing more than…', playing down how important something is.","tc":"「還不就是」用來說「也不過是……」，把事情說得不重要，是口語的反問。","sc":"「还不就是」用来说「也不过是……」，把事情说得不重要，是口语的反问。"},"ex":[{"c":"他們說的新方法，還不就是以前那一套？","s":"他们说的新方法，还不就是以前那一套？","es":"Ese «método nuevo» que dicen, ¿no es lo mismo de antes?","en":"That 'new method' they talk about is just the same old routine, isn't it?","p":"tā men shuō de xīn fāng fǎ, hái bú jiù shì yǐ qián nà yí tào?"}]},{"id":"4-4-2","b":4,"l":4,"k":"tiempo momento orden secuencia time order sequence 時間 順序 tiempo momento orden secuencia time order sequence 时间 顺序","t":{"es":"Negación fuerte con 才","en":"Outright Denial with 才","ens":"Outright Denial with 才","tc":"表示強烈否定的「才」","sc":"表示强烈否定的「才」"},"d":{"es":"才 enfático con negación: «eso sí que no», «claro que no». Contradice con fuerza lo que se dijo: 才不, 才沒有.","en":"才不 / 才沒有 strongly denies or pushes back: 'no way', 'certainly not'.","tc":"「才不」「才沒有」用來強烈反駁，意思是「才不是這樣」「我才不要」。","sc":"「才不」「才没有」用来强烈反驳，意思是「才不是这样」「我才不要」。"},"ex":[{"c":"我才不要去！","s":"我才不要去！","es":"¡Yo no pienso ir!","en":"I'm not going, no way!","p":"wǒ cái bú yào qù!"},{"c":"誰說我生氣了？我才沒有。","s":"谁说我生气了？我才没有。","es":"¿Quién dijo que estoy enojado? Para nada.","en":"Who said I was angry? I'm not.","p":"shéi shuō wǒ shēng qì le? wǒ cái méi yǒu."}]},{"id":"4-4-3","b":4,"l":4,"k":"tiempo momento orden secuencia time order sequence 時間 順序 tiempo momento orden secuencia time order sequence 时间 顺序","t":{"es":"Usos de 才 (resumen)","en":"A Summary of the Various Usages of 才","ens":"A Summary of the Various Usages of 才","tc":"「才」的用法總整理","sc":"「才」的用法总整理"},"d":{"es":"Resumen de 才: (1) «solo entonces» (condición previa); (2) «apenas» (cantidad pequeña); (3) más tarde de lo esperado; (4) negación enfática (我才不去).","en":"Main uses of 才: (1) only after something is done; (2) 'only/just' for small amounts; (3) later than expected; (4) emphatic denial.","tc":"「才」常見的用法有：一、做完某件事之後才能……；二、數量很少（才八點）；三、比預期晚（十點才來）；四、強烈否定（我才不去）。","sc":"「才」常见的用法有：一、做完某件事之后才能……；二、数量很少（才八点）；三、比预期晚（十点才来）；四、强烈否定（我才不去）。"},"ex":[{"c":"你先寫完功課才可以玩。","s":"你先写完功课才可以玩。","es":"Solo después de terminar la tarea puedes jugar.","en":"You can only play after you finish your homework.","p":"nǐ xiān xiě wán gōng kè cái kě yǐ wán."},{"c":"他昨天十二點才睡。","s":"他昨天十二点才睡。","es":"Ayer no se durmió hasta las doce.","en":"He didn't go to sleep until twelve yesterday.","p":"tā zuó tiān shí èr diǎn cái shuì."}]},{"id":"4-4-4","b":4,"l":4,"k":"","t":{"es":"Definir: 所謂…是指","en":"所謂（的） A 是指 B so called A refers to B","ens":"所谓（的） A 是指 B so called A refers to B","tc":"所謂（的）A，是指 B","sc":"所谓（的）A，是指 B"},"d":{"es":"所謂（的）A，是指 B = lo que se llama A se refiere a B. Sirve para definir un término.","en":"Used to define a term: 所謂 A means 'what is called A', followed by 是指 B to say what it refers to.","tc":"用來解釋一個詞的意思：「所謂 A」就是「大家說的 A」，後面接「是指 B」說明它是什麼。","sc":"用来解释一个词的意思：「所谓 A」就是「大家说的 A」，后面接「是指 B」说明它是什么。"},"ex":[{"c":"所謂「宵夜」，是指晚餐以後吃的東西。","s":"所谓「宵夜」，是指晚餐以后吃的东西。","es":"Lo que se llama «xiaoye» se refiere a lo que se come después de la cena.","en":"'Xiaoye' refers to what you eat after dinner.","p":"suǒ wèi 「xiāo yè」, shì zhǐ wǎn cān yǐ hòu chī de dōng xi."}]},{"id":"4-4-5","b":4,"l":4,"k":"","t":{"es":"De un tirón: 一口氣","en":"一口氣 lit. in one breath","ens":"一口气 lit. in one breath","tc":"一口氣","sc":"一口气"},"d":{"es":"一口氣 = de un tirón, sin parar (en una sola respiración).","en":"一口氣 means doing something in one go, without stopping or resting.","tc":"「一口氣」表示一次就做完，中間不停，不休息。","sc":"「一口气」表示一次就做完，中间不停，不休息。"},"ex":[{"c":"他一口氣喝完了一大杯水。","s":"他一口气喝完了一大杯水。","es":"Se tomó de un trago un vaso grande de agua.","en":"He drank a large glass of water in one gulp.","p":"tā yì kǒu qì hē wán le yí dà bēi shuǐ."},{"c":"我一口氣把書看完了。","s":"我一口气把书看完了。","es":"Me leí el libro de un tirón.","en":"I read the whole book in one go.","p":"wǒ yì kǒu qì bǎ shū kàn wán le."}]},{"id":"4-4-6","b":4,"l":4,"k":"tiempo momento orden secuencia time order sequence 時間 順序 tiempo momento orden secuencia time order sequence 时间 顺序","t":{"es":"Solo A ya…: 光 A 就","en":"光 A 就… just A alone…","ens":"光 A 就… just A alone…","tc":"光 A 就…","sc":"光 A 就…"},"d":{"es":"光 A 就… = solo A ya… Solo eso ya es mucho, sin contar lo demás.","en":"光 A 就… means that A alone is already a lot, without counting anything else.","tc":"「光 A 就……」表示只算 A 這一項，就已經很多了，更不用算別的。","sc":"「光 A 就……」表示只算 A 这一项，就已经很多了，更不用算别的。"},"ex":[{"c":"光機票就要三萬塊。","s":"光机票就要三万块。","es":"Solo el pasaje de avión ya cuesta treinta mil dólares.","en":"The plane ticket alone costs thirty thousand dollars.","p":"guāng jī piào jiù yào sān wàn kuài."}]},{"id":"4-4-7","b":4,"l":4,"k":"","t":{"es":"Queja con 都","en":"Expressing Displeasure or Annoyance with 都","ens":"Expressing Displeasure or Annoyance with 都","tc":"表示抱怨的「都」","sc":"表示抱怨的「都」"},"d":{"es":"都 + causa o tiempo expresa queja o fastidio: 都是你… = es todo culpa tuya; 都 + hora + 了 = ya es tan tarde y todavía….","en":"都是你… blames someone ('it's all your fault'); 都 + time + 了 means 'it's already this late, and yet…'.","tc":"「都是你……」表示責怪，說因為你才會這樣；「都＋時間＋了」表示已經這麼晚了，還沒做某件事。","sc":"「都是你……」表示责怪，说因为你才会这样；「都＋时间＋了」表示已经这么晚了，还没做某件事。"},"ex":[{"c":"都是你，我們才會遲到！","s":"都是你，我们才会迟到！","es":"¡Por tu culpa llegamos tarde!","en":"It's all your fault that we're late!","p":"dōu shì nǐ, wǒ men cái huì chí dào!"},{"c":"都十二點了，你還不睡？","s":"都十二点了，你还不睡？","es":"Ya son las doce, ¿todavía no te duermes?","en":"It's already twelve o'clock; aren't you going to sleep yet?","p":"dōu shí èr diǎn le, nǐ hái bú shuì?"}]},{"id":"4-5-0","b":4,"l":5,"k":"pregunta preguntar interrogativa question ask 疑問 問句 提問 pregunta preguntar interrogativa question ask 疑问 问句 提问","t":{"es":"Pregunta retórica: 哪裡","en":"Rhetorical Question with 哪裡","ens":"Rhetorical Question with 哪里","tc":"反問的「哪裡」","sc":"反问的「哪里」"},"d":{"es":"哪裡 + verbo / adjetivo = negación retórica: «qué va», «cómo voy a…». También se usa como respuesta modesta a un halago.","en":"哪裡 before a verb or adjective makes a rhetorical negation: 'how could…', 'not at all'. Replying 哪裡 to a compliment is a modest answer.","tc":"「哪裡」放在動詞或形容詞前面，用反問的方式表示否定，意思是「怎麼會」「才不是」。回答別人稱讚時說「哪裡哪裡」，是謙虛的說法。","sc":"「哪里」放在动词或形容词前面，用反问的方式表示否定，意思是「怎么会」「才不是」。回答别人称赞时说「哪里哪里」，是谦虚的说法。"},"ex":[{"c":"我哪裡知道他今天不來？","s":"我哪里知道他今天不来？","es":"¿Cómo iba a saber yo que hoy no venía?","en":"How would I know he isn't coming today?","p":"wǒ nǎ lǐ zhī dào tā jīn tiān bù lái?"},{"c":"哪裡，我的中文還不夠好。","s":"哪里，我的中文还不够好。","es":"Qué va, mi chino todavía no es suficientemente bueno.","en":"Not at all, my Chinese still isn't good enough.","p":"nǎ lǐ, wǒ de zhōng wén hái bú gòu hǎo."}]},{"id":"4-5-1","b":4,"l":5,"k":"","t":{"es":"Al fin y al cabo: 畢竟","en":"畢竟 after all","ens":"毕竟 after all","tc":"畢竟","sc":"毕竟"},"d":{"es":"畢竟 = al fin y al cabo, después de todo. Recuerda la razón de fondo.","en":"畢竟 points to the underlying reason: 'after all', 'when all is said and done'.","tc":"「畢竟」提醒對方最根本的原因，意思是「說到底」「終究」。","sc":"「毕竟」提醒对方最根本的原因，意思是「说到底」「终究」。"},"ex":[{"c":"他畢竟還是個孩子，別太嚴格。","s":"他毕竟还是个孩子，别太严格。","es":"Al fin y al cabo es un niño, no seas tan estricto.","en":"After all, he's still a child, so don't be too strict.","p":"tā bì jìng hái shì ge hái zi, bié tài yán gé."}]},{"id":"4-5-2","b":4,"l":5,"k":"","t":{"es":"Efectivamente: 的確","en":"的確 indeed","ens":"的确 indeed","tc":"的確","sc":"的确"},"d":{"es":"的確 = efectivamente, realmente. Confirma que algo es cierto.","en":"的確 confirms that something is true: 'indeed', 'certainly'.","tc":"「的確」用來確認一件事是真的，意思是「確實」。","sc":"「的确」用来确认一件事是真的，意思是「确实」。"},"ex":[{"c":"這家店的牛肉麵的確很好吃。","s":"这家店的牛肉面的确很好吃。","es":"Los fideos con carne de este lugar de verdad están muy ricos.","en":"The beef noodles at this shop really are delicious.","p":"zhè jiā diàn de niú ròu miàn dí què hěn hǎo chī."}]},{"id":"4-5-3","b":4,"l":5,"k":"dirección movimiento direction movement 方向 趨向 contraste pero sin embargo contrast but however 對比 轉折 dirección movimiento direction movement 方向 趋向 contraste pero sin embargo contrast but however 对比 转折","t":{"es":"Por otro lado: 話說回來","en":"話說回來 however, on the other hand","ens":"话说回来 however, on the other hand","tc":"話說回來","sc":"话说回来"},"d":{"es":"話說回來 = pero, por otro lado; dicho esto. Introduce otro punto de vista o vuelve al tema.","en":"話說回來 shifts to another angle or brings the topic back: 'that said', 'on the other hand'.","tc":"「話說回來」用來轉到另一個角度，或把話題拉回來，意思是「不過」「說回來」。","sc":"「话说回来」用来转到另一个角度，或把话题拉回来，意思是「不过」「说回来」。"},"ex":[{"c":"台北交通很方便，話說回來，房租也真的很貴。","s":"台北交通很方便，话说回来，房租也真的很贵。","es":"En Taipéi el transporte es muy cómodo, pero, por otro lado, la renta sí que es cara.","en":"Transportation in Taipei is very convenient, but then again, the rent is really expensive.","p":"tái běi jiāo tōng hěn fāng biàn, huà shuō huí lái, fáng zū yě zhēn de hěn guì."}]},{"id":"4-5-4","b":4,"l":5,"k":"causa razón porque consecuencia resultado cause reason because consequence result 原因 結果 因果 causa razón porque consecuencia resultado cause reason because consequence result 原因 结果 因果","t":{"es":"La razón es…: 之所以…是因為","en":"NP 之所以 S2 是因為 S1 S2 is due to S1","ens":"NP 之所以 S2 是因为 S1 S2 is due to S1","tc":"NP 之所以 S2，是因為 S1","sc":"NP 之所以 S2，是因为 S1"},"d":{"es":"NP 之所以 S2，是因為 S1 = la razón por la que S2 es que S1. Primero se dice el resultado y luego la causa.","en":"State the result first, then the cause: 之所以…，是因為…. It puts more weight on the reason than 因為…所以….","tc":"先說結果，再說原因：「之所以……，是因為……」。比「因為……所以……」更強調原因。","sc":"先说结果，再说原因：「之所以……，是因为……」。比「因为……所以……」更强调原因。"},"ex":[{"c":"他之所以能考上，是因為他每天都很努力。","s":"他之所以能考上，是因为他每天都很努力。","es":"La razón por la que pudo entrar es que se esforzaba todos los días.","en":"The reason he got in is that he worked hard every day.","p":"tā zhī suǒ yǐ néng kǎo shàng, shì yīn wèi tā měi tiān dōu hěn nǔ lì."}]},{"id":"4-5-5","b":4,"l":5,"k":"","t":{"es":"En absoluto: 根本","en":"根本 not…at all","ens":"根本 not…at all","tc":"根本","sc":"根本"},"d":{"es":"根本 + negación = en absoluto, de ninguna manera. Enfatiza que no es así desde el fondo.","en":"根本 in a negative sentence means 'not at all', 'not even in the slightest'.","tc":"「根本」放在否定的句子裡，表示完全不是這樣，意思是「從來就不」「完全不」。","sc":"「根本」放在否定的句子里，表示完全不是这样，意思是「从来就不」「完全不」。"},"ex":[{"c":"我根本不知道這件事。","s":"我根本不知道这件事。","es":"No tenía ni idea de este asunto.","en":"I had no idea about this matter at all.","p":"wǒ gēn běn bù zhī dào zhè jiàn shì."}]},{"id":"4-5-6","b":4,"l":5,"k":"comparar comparación comparativo más menos igual semejante comparison compare comparative 比較 比較級 negación negar negativa negation negative 否定 siempre nunca frecuencia always never frequency 經常 從來 comparar comparación comparativo más menos igual semejante comparison compare comparative 比较 比较级 negación negar negativa negation negative 否定 siempre nunca frecuencia always never frequency 经常 从来","t":{"es":"Y mucho menos: 更別說…了","en":"更別說…了 let alone, never mind","ens":"更别说…了 let alone, never mind","tc":"更別說…了","sc":"更别说…了"},"d":{"es":"更別說 A 了 = y mucho menos A, ni hablar de A. Se niega un caso más difícil después de uno más fácil.","en":"After saying someone can't even do the easier thing, 更別說 A 了 adds that the harder thing is out of the question.","tc":"先說一件比較容易的事都做不到，再說「更別說 A 了」，表示更難的事當然做不到。","sc":"先说一件比较容易的事都做不到，再说「更别说 A 了」，表示更难的事当然做不到。"},"ex":[{"c":"他連中文都不會說，更別說寫了。","s":"他连中文都不会说，更别说写了。","es":"Ni siquiera sabe hablar chino, y mucho menos escribirlo.","en":"He can't even speak Chinese, let alone write it.","p":"tā lián zhōng wén dōu bú huì shuō, gèng bié shuō xiě le."}]},{"id":"4-5-7","b":4,"l":5,"k":"negación negar negativa negation negative 否定 complemento resultado potencial complement result potential 補語 結果補語 可能補語 negación negar negativa negation negative 否定 complemento resultado potencial complement result potential 补语 结果补语 可能补语","t":{"es":"Desear con fuerza: 恨不得","en":"恨不得 one really wishes one could…","ens":"恨不得 one really wishes one could…","tc":"恨不得","sc":"恨不得"},"d":{"es":"恨不得 + verbo = desear con todas las fuerzas poder hacer algo (a menudo imposible).","en":"恨不得 means desperately wanting to do something, usually something you can't actually do.","tc":"「恨不得」表示非常想做某件事，但通常做不到。","sc":"「恨不得」表示非常想做某件事，但通常做不到。"},"ex":[{"c":"太累了，我恨不得馬上就能睡覺。","s":"太累了，我恨不得马上就能睡觉。","es":"Estoy tan cansado que quisiera poder dormirme ya mismo.","en":"I'm so tired I wish I could fall asleep right now.","p":"tài lèi le, wǒ hèn bù dé mǎ shàng jiù néng shuì jiào."},{"c":"聽到好消息，他恨不得馬上告訴大家。","s":"听到好消息，他恨不得马上告诉大家。","es":"Al oír la buena noticia, se moría por contárselo a todos.","en":"Hearing the good news, he couldn't wait to tell everyone.","p":"tīng dào hǎo xiāo xí, tā hèn bù dé mǎ shàng gào sù dà jiā."}]},{"id":"4-6-0","b":4,"l":6,"k":"pregunta preguntar interrogativa question ask 疑問 問句 提問 pregunta preguntar interrogativa question ask 疑问 问句 提问","t":{"es":"¿Por qué tan…? 怎麼這麼","en":"怎麼這麼 Why so…?","ens":"怎么这么 Why so…?","tc":"怎麼這麼","sc":"怎么这么"},"d":{"es":"怎麼這麼 + adjetivo / verbo = ¿por qué tan…? Expresa sorpresa o queja.","en":"怎麼這麼 + adjective / verb expresses surprise or complaint: 'why so…?'.","tc":"「怎麼這麼＋形容詞／動詞」表示驚訝或抱怨，意思是「為什麼這麼……」。","sc":"「怎么这么＋形容词／动词」表示惊讶或抱怨，意思是「为什么这么……」。"},"ex":[{"c":"今天怎麼這麼冷？","s":"今天怎么这么冷？","es":"¿Por qué hace tanto frío hoy?","en":"Why is it so cold today?","p":"jīn tiān zěn me zhè me lěng?"}]},{"id":"4-6-1","b":4,"l":6,"k":"","t":{"es":"Exclamación con 多","en":"Intensifying Adverb 多 how","ens":"Intensifying Adverb 多 how","tc":"感嘆的「多」","sc":"感叹的「多」"},"d":{"es":"多 + adjetivo en una exclamación = ¡qué…! Suele cerrar con 啊 / 呀 y expresa admiración.","en":"多 + adjective in an exclamation means 'how…!', and often ends with 啊 or 呀.","tc":"「多＋形容詞」用在感嘆句，意思是「多麼……」，句尾常加「啊」「呀」。","sc":"「多＋形容词」用在感叹句，意思是「多么……」，句尾常加「啊」「呀」。"},"ex":[{"c":"這裡的風景多美啊！","s":"这里的风景多美啊！","es":"¡Qué hermoso es el paisaje de aquí!","en":"How beautiful the scenery is here!","p":"zhè lǐ de fēng jǐng duō měi a!"}]},{"id":"4-6-2","b":4,"l":6,"k":"","t":{"es":"Usos de 多 (resumen)","en":"The Various Functions of 多","ens":"The Various Functions of 多","tc":"「多」的各種用法","sc":"「多」的各种用法"},"d":{"es":"Funciones de 多: (1) «más de» después de un número; (2) pregunta de grado (多高, 多久); (3) exclamación «qué…»; (4) «por más… que» en 不管多….","en":"Common uses of 多: (1) 'more than' after a number; (2) asking degree (多高); (3) exclamation 'how…'; (4) 不管多… for 'no matter how…'.","tc":"「多」常見的用法有：一、數字後面表示「超過」（三十多歲）；二、問程度（多高）；三、感嘆（多好看）；四、「不管多……」表示「再……也」。","sc":"「多」常见的用法有：一、数字后面表示「超过」（三十多岁）；二、问程度（多高）；三、感叹（多好看）；四、「不管多……」表示「再……也」。"},"ex":[{"c":"他今年三十多歲。","s":"他今年三十多岁。","es":"Este año tiene treinta y tantos.","en":"He's in his thirties this year.","p":"tā jīn nián sān shí duō suì."},{"c":"不管多忙，我都會陪家人吃晚飯。","s":"不管多忙，我都会陪家人吃晚饭。","es":"Por muy ocupado que esté, ceno con mi familia.","en":"No matter how busy I am, I eat dinner with my family.","p":"bù guǎn duō máng, wǒ dōu huì péi jiā rén chī wǎn fàn."}]},{"id":"4-6-3","b":4,"l":6,"k":"","t":{"es":"En vano: 白","en":"白 in vain, for nothing","ens":"白 in vain, for nothing","tc":"白","sc":"白"},"d":{"es":"白 + verbo = en vano, para nada, sin resultado: 白跑一趟 = ir en balde. También puede significar «gratis» (白吃).","en":"白 + verb means doing something with no result, such as 白跑一趟 (a wasted trip). It can also mean 'for free' (白吃).","tc":"「白＋動詞」表示做了卻沒有結果、沒有用，例如「白跑一趟」。也可以表示「不用付錢」（白吃）。","sc":"「白＋动词」表示做了却没有结果、没有用，例如「白跑一趟」。也可以表示「不用付钱」（白吃）。"},"ex":[{"c":"我白等了一個小時。","s":"我白等了一个小时。","es":"Esperé una hora en vano.","en":"I waited an hour for nothing.","p":"wǒ bái děng le yí ge xiǎo shí."},{"c":"他白跑了一趟。","s":"他白跑了一趟。","es":"Fue en balde.","en":"He made a trip for nothing.","p":"tā bái pǎo le yí tàng."}]},{"id":"4-6-4","b":4,"l":6,"k":"siempre nunca frecuencia always never frequency 經常 從來 siempre nunca frecuencia always never frequency 经常 从来","t":{"es":"Siempre: 總是","en":"總是 always","ens":"总是 always","tc":"總是","sc":"总是"},"d":{"es":"總是 = siempre, constantemente. Es un hábito constante, a veces con un tono de queja.","en":"總是 means 'always', a constant habit, sometimes with a slight tone of complaint.","tc":"「總是」表示一直都是這樣，是固定的習慣，有時帶一點抱怨。","sc":"「总是」表示一直都是这样，是固定的习惯，有时带一点抱怨。"},"ex":[{"c":"他總是遲到。","s":"他总是迟到。","es":"Siempre llega tarde.","en":"He's always late.","p":"tā zǒng shì chí dào."}]},{"id":"4-6-5","b":4,"l":6,"k":"dirección movimiento direction movement 方向 趨向 complemento resultado potencial complement result potential 補語 結果補語 可能補語 dirección movimiento direction movement 方向 趋向 complemento resultado potencial complement result potential 补语 结果补语 可能补语","t":{"es":"V 下來 (resumen)","en":"The Various Meanings of the Verb Complement 下來","ens":"The Various Meanings of the Verb Complement 下来","tc":"動詞＋下來","sc":"动词＋下来"},"d":{"es":"V + 下來: (1) de arriba hacia abajo; (2) algo queda registrado o se queda (記下來, 留下來); (3) continuar hasta ahora; (4) calmarse (安靜下來).","en":"Common meanings of V + 下來: (1) downward; (2) recording or keeping something (記下來, 留下來); (3) lasting up to now; (4) calming down.","tc":"「V＋下來」常見的意思有：一、從上往下；二、把東西記錄或留住（記下來、留下來）；三、從過去持續到現在；四、變安靜、變穩定（安靜下來）。","sc":"「V＋下来」常见的意思有：一、从上往下；二、把东西记录或留住（记下来、留下来）；三、从过去持续到现在；四、变安静、变稳定（安静下来）。"},"ex":[{"c":"請把這個電話號碼記下來。","s":"请把这个电话号码记下来。","es":"Por favor anota este número de teléfono.","en":"Please write down this phone number.","p":"qǐng bǎ zhè ge diàn huà hào mǎ jì xià lái."},{"c":"聽到音樂，他慢慢安靜下來了。","s":"听到音乐，他慢慢安静下来了。","es":"Al oír la música, poco a poco se fue calmando.","en":"Hearing the music, he gradually calmed down.","p":"tīng dào yīn yuè, tā màn màn ān jìng xià lái le."}]},{"id":"4-6-6","b":4,"l":6,"k":"tiempo momento orden secuencia time order sequence 時間 順序 tiempo momento orden secuencia time order sequence 时间 顺序","t":{"es":"Cuando: 當…的時候","en":"當…的時候 when, while, at the time of","ens":"当…的时候 when, while, at the time of","tc":"當…的時候","sc":"当…的时候"},"d":{"es":"當 + frase + 的時候 = cuando, mientras, en el momento en que…. 當 hace la expresión un poco más formal.","en":"當 + clause + 的時候 means 'at the time when…'; it's slightly more formal than just …的時候.","tc":"「當＋一段話＋的時候」表示「在……的時間」，比只說「……的時候」稍微正式一點。","sc":"「当＋一段话＋的时候」表示「在……的时间」，比只说「……的时候」稍微正式一点。"},"ex":[{"c":"當我到家的時候，天已經黑了。","s":"当我到家的时候，天已经黑了。","es":"Cuando llegué a casa, ya había oscurecido.","en":"When I got home, it was already dark.","p":"dāng wǒ dào jiā de shí hòu, tiān yǐ jīng hēi le."}]},{"id":"4-6-7","b":4,"l":6,"k":"contraste pero sin embargo contrast but however 對比 轉折 contraste pero sin embargo contrast but however 对比 转折","t":{"es":"Al contrario: 反而","en":"反而 on the contrary","ens":"反而 on the contrary","tc":"反而","sc":"反而"},"d":{"es":"反而 = al contrario, en cambio. El resultado va en contra de lo esperado.","en":"反而 shows that the result is the opposite of what you'd expect: 'on the contrary', 'instead'.","tc":"「反而」表示結果和預期相反，意思是「結果卻是」。","sc":"「反而」表示结果和预期相反，意思是「结果却是」。"},"ex":[{"c":"吃了藥，他不但沒好，反而更不舒服了。","s":"吃了药，他不但没好，反而更不舒服了。","es":"Tomó la medicina y no solo no mejoró, sino que se sintió peor.","en":"He took the medicine, and not only didn't he get better, he felt even worse.","p":"chī le yào, tā bú dàn méi hǎo, fǎn ér gèng bù shū fú le."},{"c":"我已經提醒他了，他反而生氣了。","s":"我已经提醒他了，他反而生气了。","es":"Ya se lo recordé y, al contrario, se enojó.","en":"I already reminded him, and he got angry instead.","p":"wǒ yǐ jīng tí xǐng tā le, tā fǎn ér shēng qì le."}]},{"id":"4-7-0","b":4,"l":7,"k":"además adición también addition also besides 另外 而且 además adición también addition also besides 另外 而且","t":{"es":"Sorpresa con 還","en":"還 to my surprise","ens":"还 to my surprise","tc":"表示意外的「還」","sc":"表示意外的「还」"},"d":{"es":"還 expresa sorpresa: algo resulta mejor o más de lo esperado. Suele aparecer en frases como 還會…, 還有….","en":"還 expresses surprise that something is better or more than expected. Common patterns are 還會… and 還有….","tc":"「還」可以表示事情比想像的更好、更多，帶有一點意外。常見的說法有「還會……」「還有……」。","sc":"「还」可以表示事情比想像的更好、更多，带有一点意外。常见的说法有「还会……」「还有……」。"},"ex":[{"c":"這麼難的歌，他還會唱！","s":"这么难的歌，他还会唱！","es":"¡Hasta sabe cantar una canción tan difícil!","en":"He can even sing such a hard song!","p":"zhè me nán de gē, tā hái huì chàng!"},{"c":"沒想到這家店還有賣中文書。","s":"没想到这家店还有卖中文书。","es":"No esperaba que esta tienda hasta vendiera libros en chino.","en":"I didn't expect this shop to sell Chinese books, too.","p":"méi xiǎng dào zhè jiā diàn hái yǒu mài zhōng wén shū."}]},{"id":"4-7-1","b":4,"l":7,"k":"","t":{"es":"Alternar: 一下…一下…","en":"Alternating Events with 一下…一下…","ens":"Alternating Events with 一下…一下…","tc":"一下……一下……","sc":"一下……一下……"},"d":{"es":"一下 A，一下 B = ahora A, ahora B. Describe dos situaciones que se alternan rápidamente.","en":"一下 A, 一下 B means 'one moment A, the next moment B'. Two situations alternate quickly.","tc":"「一下 A，一下 B」表示兩種情況很快輪流出現，一下子這樣、一下子那樣。","sc":"「一下 A，一下 B」表示两种情况很快轮流出现，一下子这样、一下子那样。"},"ex":[{"c":"他一下高興、一下難過，真讓人搞不懂。","s":"他一下高兴、一下难过，真让人搞不懂。","es":"Un rato está contento y otro triste; es difícil entenderlo.","en":"He's happy one moment and sad the next; it's hard to figure him out.","p":"tā yí xià gāo xìng, yí xià nán guò, zhēn ràng rén gǎo bù dǒng."},{"c":"天氣一下熱、一下冷，很容易感冒。","s":"天气一下热、一下冷，很容易感冒。","es":"El clima cambia de calor a frío todo el tiempo; es fácil resfriarse.","en":"The weather swings between hot and cold; it's easy to catch a cold.","p":"tiān qì yí xià rè, yí xià lěng, hěn róng yì gǎn mào."}]},{"id":"4-7-2","b":4,"l":7,"k":"","t":{"es":"Fracciones: A 分之 B","en":"Various Fractions with A 分之 B","ens":"Various Fractions with A 分之 B","tc":"分數：A 分之 B","sc":"分数：A 分之 B"},"d":{"es":"A 分之 B expresa fracciones: se dice primero el denominador (A) y luego el numerador (B). Los porcentajes usan 百分之.","en":"For fractions, say the denominator (A) first, then 分之, then the numerator (B). Percentages use 百分之.","tc":"說分數時，先說分母（A），再說分子（B），中間加「分之」。百分比用「百分之」。","sc":"说分数时，先说分母（A），再说分子（B），中间加「分之」。百分比用「百分之」。"},"ex":[{"c":"全班有三分之一的人去過日本。","s":"全班有三分之一的人去过日本。","es":"Un tercio de la clase ha ido a Japón.","en":"A third of the class has been to Japan.","p":"quán bān yǒu sān fēn zhī yī de rén qù guò rì běn."},{"c":"這家公司百分之八十的員工是女生。","s":"这家公司百分之八十的员工是女生。","es":"El ochenta por ciento de los empleados de esta empresa son mujeres.","en":"Eighty percent of the employees at this company are women.","p":"zhè jiā gōng sī bǎi fēn zhī bā shí de yuán gōng shì nǚ shēng."}]},{"id":"4-7-3","b":4,"l":7,"k":"énfasis enfático incluso emphasis emphatic even 強調 甚至 énfasis enfático incluso emphasis emphatic even 强调 甚至","t":{"es":"Seguidos: 一連","en":"一連 without interruption, in rapid succession","ens":"一连 without interruption, in rapid succession","tc":"一連","sc":"一连"},"d":{"es":"一連 + cantidad + verbo = varias veces o durante varios días seguidos, sin interrupción.","en":"一連 + quantity + verb means an action happens several times or for several days in a row, without a break.","tc":"「一連＋數量＋動詞」表示動作連續發生好幾次，或持續好幾天，中間沒有停。","sc":"「一连＋数量＋动词」表示动作连续发生好几次，或持续好几天，中间没有停。"},"ex":[{"c":"他一連請了三天假。","s":"他一连请了三天假。","es":"Pidió permiso tres días seguidos.","en":"He took leave for three days in a row.","p":"tā yì lián qǐng le sān tiān jiǎ."},{"c":"這個星期一連下了五天雨。","s":"这个星期一连下了五天雨。","es":"Esta semana llovió cinco días seguidos.","en":"It rained for five days straight this week.","p":"zhè ge xīng qí yī lián xià le wǔ tiān yǔ."}]},{"id":"4-7-4","b":4,"l":7,"k":"","t":{"es":"Hasta saciarse: V 個夠","en":"To Have a Full Dosage of an Activity V 個夠","ens":"To Have a Full Dosage of an Activity V 个够","tc":"動詞＋個夠","sc":"动词＋个够"},"d":{"es":"Verbo + 個夠 = hacer algo hasta quedar satisfecho, a más no poder (玩個夠, 吃個夠, 睡個夠).","en":"Verb + 個夠 means doing something to your heart's content, as in 玩個夠, 吃個夠, 睡個夠.","tc":"「動詞＋個夠」表示盡情做某件事，做到滿意為止，例如「玩個夠」「吃個夠」「睡個夠」。","sc":"「动词＋个够」表示尽情做某件事，做到满意为止，例如「玩个够」「吃个够」「睡个够」。"},"ex":[{"c":"放假的時候，我想睡個夠。","s":"放假的时候，我想睡个够。","es":"En las vacaciones quiero dormir todo lo que quiera.","en":"On vacation I want to sleep as much as I like.","p":"fàng jià de shí hòu, wǒ xiǎng shuì gè gòu."},{"c":"今天我們一定要吃個夠！","s":"今天我们一定要吃个够！","es":"¡Hoy vamos a comer hasta hartarnos!","en":"Today we're definitely going to eat our fill!","p":"jīn tiān wǒ men yí dìng yào chī gè gòu!"}]},{"id":"4-7-5","b":4,"l":7,"k":"","t":{"es":"Ayudar a: 有助於","en":"有助於 be conducive to","ens":"有助于 be conducive to","tc":"有助於","sc":"有助于"},"d":{"es":"有助於 + verbo / sustantivo = ayudar a, ser útil para. Es una forma más formal de 對…有幫助.","en":"有助於 + verb/noun means 'helps with / is conducive to'. It is a more formal way of saying 對…有幫助.","tc":"「有助於」是「對……有幫助」的比較正式說法，後面接動詞或名詞。","sc":"「有助于」是「对……有帮助」的比较正式说法，后面接动词或名词。"},"ex":[{"c":"多聽多說有助於提高中文程度。","s":"多听多说有助于提高中文程度。","es":"Escuchar y hablar mucho ayuda a mejorar el nivel de chino.","en":"Listening and speaking a lot helps improve your Chinese.","p":"duō tīng duō shuō yǒu zhù yú tí gāo zhōng wén chéng dù."},{"c":"運動有助於睡眠。","s":"运动有助于睡眠。","es":"El ejercicio ayuda a dormir.","en":"Exercise helps you sleep.","p":"yùn dòng yǒu zhù yú shuì mián."}]},{"id":"4-7-6","b":4,"l":7,"k":"","t":{"es":"Así que: 於是","en":"於是… thus, consequently","ens":"于是… thus, consequently","tc":"於是","sc":"于是"},"d":{"es":"於是 = así que, por eso (en consecuencia). Une dos hechos en orden: el segundo ocurre a causa del primero.","en":"於是 means 'so / as a result'. The second event follows from the first, in order.","tc":"「於是」表示因為前面的事，接著發生了後面的事，意思是「所以就」。前後兩件事有先後順序。","sc":"「于是」表示因为前面的事，接着发生了后面的事，意思是「所以就」。前后两件事有先后顺序。"},"ex":[{"c":"他覺得中文很有趣，於是決定去台灣學。","s":"他觉得中文很有趣，于是决定去台湾学。","es":"Le pareció que el chino era interesante, así que decidió ir a estudiarlo a Taiwán.","en":"He found Chinese interesting, so he decided to study it in Taiwan.","p":"tā jué dé zhōng wén hěn yǒu qù, yú shì jué dìng qù tái wān xué."},{"c":"外面下大雨，於是我們留在家裡看電影。","s":"外面下大雨，于是我们留在家里看电影。","es":"Llovía a cántaros afuera, así que nos quedamos en casa viendo una película.","en":"It was pouring outside, so we stayed home and watched a movie.","p":"wài miàn xià dà yǔ, yú shì wǒ men liú zài jiā lǐ kàn diàn yǐng."}]},{"id":"4-7-7","b":4,"l":7,"k":"","t":{"es":"Hacia, a: 向","en":"向 to, toward","ens":"向 to, toward","tc":"介詞「向」","sc":"介词「向」"},"d":{"es":"向 + persona o dirección = hacia, a, de. Marca el destinatario de una acción: 向…借, 向…道謝, 向前走.","en":"向 + person or direction marks the target or direction of an action, as in 向…借, 向…道謝, 向前走.","tc":"「向」後面接人或方向，表示動作的對象或方向，例如「向……借」「向……道謝」「向前走」。","sc":"「向」后面接人或方向，表示动作的对象或方向，例如「向……借」「向……道谢」「向前走」。"},"ex":[{"c":"我想向你借一本書。","s":"我想向你借一本书。","es":"Quiero pedirte prestado un libro.","en":"I'd like to borrow a book from you.","p":"wǒ xiǎng xiàng nǐ jiè yì běn shū."},{"c":"他向大家說明了新的規定。","s":"他向大家说明了新的规定。","es":"Les explicó a todos las nuevas reglas.","en":"He explained the new rules to everyone.","p":"tā xiàng dà jiā shuō míng le xīn de guī dìng."}]},{"id":"4-8-0","b":4,"l":8,"k":"","t":{"es":"De todos modos: 反正","en":"反正 at any rate, anyway","ens":"反正 at any rate, anyway","tc":"反正","sc":"反正"},"d":{"es":"反正 = de todos modos, total. Se usa cuando la situación no cambia, haga lo que se haga.","en":"反正 means 'anyway': whatever happens, the result is the same, so there's no need to worry or argue about it.","tc":"「反正」表示不管怎麼樣，結果都一樣，所以不用在意或不必再討論。","sc":"「反正」表示不管怎么样，结果都一样，所以不用在意或不必再讨论。"},"ex":[{"c":"你不用擔心，反正我們時間很多。","s":"你不用担心，反正我们时间很多。","es":"No te preocupes, total tenemos mucho tiempo.","en":"Don't worry, we have plenty of time anyway.","p":"nǐ bú yòng dān xīn, fǎn zhèng wǒ men shí jiān hěn duō."},{"c":"反正我已經決定了，你說什麼都沒用。","s":"反正我已经决定了，你说什么都没用。","es":"De todos modos ya decidí; nada de lo que digas servirá.","en":"I've already decided anyway; nothing you say will help.","p":"fǎn zhèng wǒ yǐ jīng jué dìng le, nǐ shuō shén me dōu méi yòng."}]},{"id":"4-8-1","b":4,"l":8,"k":"negación negar negativa negation negative 否定 negación negar negativa negation negative 否定","t":{"es":"No solo: 不只","en":"不只 not merely, exceeding","ens":"不只 not merely, exceeding","tc":"不只……還／也……","sc":"不只……还／也……"},"d":{"es":"不只 A，還／也 B = no solo A, sino también B. La parte B añade algo más.","en":"不只 A, 還/也 B means 'not only A, but also B'; B adds something beyond A.","tc":"「不只 A，還／也 B」表示除了 A 以外，B 也是，範圍比 A 更大。","sc":"「不只 A，还／也 B」表示除了 A 以外，B 也是，范围比 A 更大。"},"ex":[{"c":"他不只會說中文，還會說日文。","s":"他不只会说中文，还会说日文。","es":"No solo habla chino, también habla japonés.","en":"He doesn't just speak Chinese; he speaks Japanese, too.","p":"tā bù zhǐ huì shuō zhōng wén, hái huì shuō rì wén."},{"c":"不只小孩喜歡這部電影，大人也很喜歡。","s":"不只小孩喜欢这部电影，大人也很喜欢。","es":"No solo a los niños les gusta esta película; a los adultos también.","en":"It's not only kids who like this movie; adults like it, too.","p":"bù zhǐ xiǎo hái xǐ huān zhè bù diàn yǐng, dà rén yě hěn xǐ huān."}]},{"id":"4-8-2","b":4,"l":8,"k":"","t":{"es":"Inevitable: 難免","en":"難免 inevitably, it is only natural that","ens":"难免 inevitably, it is only natural that","tc":"難免","sc":"难免"},"d":{"es":"難免 = es inevitable, es natural que. Se usa para algo que casi siempre pasa en esa situación.","en":"難免 means 'it's hard to avoid / it's only natural': something is very likely to happen in this situation.","tc":"「難免」表示在這種情況下，很容易發生某件事，幾乎無法避免。","sc":"「难免」表示在这种情况下，很容易发生某件事，几乎无法避免。"},"ex":[{"c":"剛開始學中文，難免會說錯。","s":"刚开始学中文，难免会说错。","es":"Al empezar a aprender chino es inevitable equivocarse al hablar.","en":"When you first start learning Chinese, it's inevitable that you'll make mistakes.","p":"gāng kāi shǐ xué zhōng wén, nán miǎn huì shuō cuò."},{"c":"第一次出國，難免會有點緊張。","s":"第一次出国，难免会有点紧张。","es":"La primera vez que se viaja al extranjero es normal estar un poco nervioso.","en":"Going abroad for the first time, it's natural to feel a bit nervous.","p":"dì yī cì chū guó, nán miǎn huì yǒu diǎn jǐn zhāng."}]},{"id":"4-8-3","b":4,"l":8,"k":"","t":{"es":"Eso sí: 倒是","en":"倒是 on the other hand","ens":"倒是 on the other hand","tc":"倒是","sc":"倒是"},"d":{"es":"倒是 = en cambio, eso sí. Introduce un contraste suave con lo anterior.","en":"倒是 introduces a mild contrast with what came before: 'but, on the other hand'.","tc":"「倒是」表示和前面說的有一點相反或不同，語氣比較輕，意思是「不過……卻……」。","sc":"「倒是」表示和前面说的有一点相反或不同，语气比较轻，意思是「不过……却……」。"},"ex":[{"c":"這家餐廳不大，東西倒是挺好吃的。","s":"这家餐厅不大，东西倒是挺好吃的。","es":"Este restaurante no es grande, pero la comida sí que es bastante rica.","en":"This restaurant isn't big, but the food is actually quite good.","p":"zhè jiā cān tīng bú dà, dōng xi dào shì tǐng hǎo chī de."},{"c":"他中文說得不太好，字倒是寫得很漂亮。","s":"他中文说得不太好，字倒是写得很漂亮。","es":"No habla muy bien chino, pero eso sí, escribe los caracteres muy bonito.","en":"His Chinese isn't great, but his handwriting is really beautiful.","p":"tā zhōng wén shuō de bú tài hǎo, zì dào shì xiě de hěn piào liàng."}]},{"id":"4-8-4","b":4,"l":8,"k":"","t":{"es":"Ahora sí: 這下子","en":"這下子 that being the case, as a consequence","ens":"这下子 that being the case, as a consequence","tc":"這下子","sc":"这下子"},"d":{"es":"這下子 = ahora sí, con esto. Señala la consecuencia de lo que acaba de ocurrir (buena o mala).","en":"這下子 means 'now, with this': it points to the consequence of what just happened, good or bad.","tc":"「這下子」表示因為剛才發生的事，產生了新的結果，可以是好事，也可以是壞事。","sc":"「这下子」表示因为刚才发生的事，产生了新的结果，可以是好事，也可以是坏事。"},"ex":[{"c":"鑰匙不見了，這下子麻煩了！","s":"钥匙不见了，这下子麻烦了！","es":"Se perdieron las llaves, ¡ahora sí estamos en problemas!","en":"The keys are lost, so now we're in trouble!","p":"yuè shi bú jiàn le, zhè xià zi má fán le!"},{"c":"他考上了，這下子爸媽可以放心了。","s":"他考上了，这下子爸妈可以放心了。","es":"Aprobó el examen; ahora sí sus papás pueden estar tranquilos.","en":"He got in, so now his parents can relax.","p":"tā kǎo shàng le, zhè xià zi bà mā kě yǐ fàng xīn le."}]},{"id":"4-8-5","b":4,"l":8,"k":"dirección movimiento direction movement 方向 趨向 complemento resultado potencial complement result potential 補語 結果補語 可能補語 dirección movimiento direction movement 方向 趋向 complemento resultado potencial complement result potential 补语 结果补语 可能补语","t":{"es":"Congeniar: V 得來／不來","en":"Verb Complement 來 personable","ens":"Verb Complement 来 personable","tc":"動詞＋得來／不來","sc":"动词＋得来／不来"},"d":{"es":"Verbo + 得來 / 不來 expresa si algo se lleva bien con uno: 合得來 (llevarse bien), 談得來 (conectar al conversar), 合不來 (no congeniar).","en":"Verb + 得來/不來 says whether you get along with someone or something suits you, as in 合得來, 談得來, 合不來.","tc":"「動詞＋得來／不來」表示跟某人或某件事合不合得上，例如「合得來」「談得來」「合不來」。","sc":"「动词＋得来／不来」表示跟某人或某件事合不合得上，例如「合得来」「谈得来」「合不来」。"},"ex":[{"c":"我跟新室友很談得來。","s":"我跟新室友很谈得来。","es":"Con mi nuevo compañero de cuarto conecto muy bien al conversar.","en":"I really click with my new roommate when we talk.","p":"wǒ gēn xīn shì yǒu hěn tán dé lái."},{"c":"他們兩個個性不同，合不來。","s":"他们两个个性不同，合不来。","es":"Esos dos tienen personalidades distintas y no congenian.","en":"The two of them have different personalities and don't get along.","p":"tā men liǎng ge gè xìng bù tóng, hé bù lái."}]},{"id":"4-8-6","b":4,"l":8,"k":"","t":{"es":"Cuánto más: 何況","en":"何況 let alone, no need to mention","ens":"何况 let alone, no need to mention","tc":"何況","sc":"何况"},"d":{"es":"何況 = y más aún, cuánto más. Para reforzar un argumento con un caso aún más claro.","en":"何況 strengthens an argument with an even clearer case: 'let alone', 'not to mention'.","tc":"「何況」用更明顯的例子來加強前面的說法，意思是「更不用說」「而且」。","sc":"「何况」用更明显的例子来加强前面的说法，意思是「更不用说」「而且」。"},"ex":[{"c":"連大人都搬不動，何況是小孩？","s":"连大人都搬不动，何况是小孩？","es":"Ni los adultos pueden moverlo, ¿cuánto menos un niño?","en":"Even adults can't move it, let alone a child.","p":"lián dà rén dōu bān bú dòng, hé kuàng shì xiǎo hái?"},{"c":"這麼近，何況天氣又好，我們走路去吧。","s":"这么近，何况天气又好，我们走路去吧。","es":"Está tan cerca y además hace buen tiempo; vayamos caminando.","en":"It's so close, and the weather is nice, too, so let's walk.","p":"zhè me jìn, hé kuàng tiān qì yòu hǎo, wǒ men zǒu lù qù ba."}]},{"id":"4-8-7","b":4,"l":8,"k":"","t":{"es":"De lo contrario: 否則","en":"否則 otherwise","ens":"否则 otherwise","tc":"否則","sc":"否则"},"d":{"es":"否則 = de lo contrario, si no. Introduce lo que pasará si no se cumple lo anterior.","en":"否則 means 'otherwise': if the previous condition isn't met, something bad will happen.","tc":"「否則」表示如果前面說的事沒有做到，就會有不好的結果，意思是「不然」。","sc":"「否则」表示如果前面说的事没有做到，就会有不好的结果，意思是「不然」。"},"ex":[{"c":"快一點，否則會趕不上火車。","s":"快一点，否则会赶不上火车。","es":"Date prisa; si no, perderemos el tren.","en":"Hurry up, or we'll miss the train.","p":"kuài yì diǎn, fǒu zé huì gǎn bú shàng huǒ chē."},{"c":"你要多休息，否則身體會受不了。","s":"你要多休息，否则身体会受不了。","es":"Tienes que descansar más; de lo contrario, tu cuerpo no lo resistirá.","en":"You need to rest more; otherwise your body won't be able to take it.","p":"nǐ yào duō xiū xí, fǒu zé shēn tǐ huì shòu bù liǎo."}]},{"id":"4-9-0","b":4,"l":9,"k":"disposición objeto complemento disposal object ba 處置 把字句 disposición objeto complemento disposal object ba 处置 把字句","t":{"es":"Considerar: 把A當做B","en":"把 A 當做 B to treat, take A as B","ens":"把 A 当做 B to treat, take A as B","tc":"把 A 當做 B","sc":"把 A 当做 B"},"d":{"es":"把 A 當做 B = tratar o considerar a A como B.","en":"把 A 當做 B means to treat or regard A as B.","tc":"「把 A 當做 B」表示把 A 看成 B，或用對待 B 的方式對待 A。","sc":"「把 A 当做 B」表示把 A 看成 B，或用对待 B 的方式对待 A。"},"ex":[{"c":"我把他當做自己的弟弟。","s":"我把他当做自己的弟弟。","es":"Lo considero como a mi propio hermano menor.","en":"I think of him as my own younger brother.","p":"wǒ bǎ tā dāng zuò zì jǐ de dì di."},{"c":"很多人把網路當做主要的資訊來源。","s":"很多人把网路当做主要的资讯来源。","es":"Mucha gente considera internet su principal fuente de información.","en":"Many people regard the internet as their main source of information.","p":"hěn duō rén bǎ wǎng lù dāng zuò zhǔ yào de zī xùn lái yuán."}]},{"id":"4-9-1","b":4,"l":9,"k":"","t":{"es":"Bajo, con: 在…下","en":"在…下 under the…, due to the…","ens":"在…下 under the…, due to the…","tc":"在……下","sc":"在……下"},"d":{"es":"在…下 = bajo, con (condición, ayuda o circunstancia): 在…的幫助下, 在這種情況下.","en":"在…下 means 'under / with' a condition, help or circumstance, as in 在…的幫助下 and 在這種情況下.","tc":"「在……下」表示在某種條件、幫助或情況之下，例如「在……的幫助下」「在這種情況下」。","sc":"「在……下」表示在某种条件、帮助或情况之下，例如「在……的帮助下」「在这种情况下」。"},"ex":[{"c":"在朋友的幫助下，我找到了工作。","s":"在朋友的帮助下，我找到了工作。","es":"Con la ayuda de un amigo, encontré trabajo.","en":"With a friend's help, I found a job.","p":"zài péng yǒu de bāng zhù xià, wǒ zhǎo dào le gōng zuò."},{"c":"在這樣的天氣下，比賽還是照常舉行。","s":"在这样的天气下，比赛还是照常举行。","es":"Aun con este clima, el partido se celebra como de costumbre.","en":"Even in this weather, the game is going ahead as usual.","p":"zài zhè yàng de tiān qì xià, bǐ sài hái shì zhào cháng jǔ xíng."}]},{"id":"4-9-2","b":4,"l":9,"k":"","t":{"es":"Usos de 該","en":"The Various Functions of 該","ens":"The Various Functions of 该","tc":"「該」的各種用法","sc":"「该」的各种用法"},"d":{"es":"該 tiene varios usos: «deber» (我該走了), «ya es hora de…» (該…了), y en lenguaje escrito «dicho, el mencionado» (該公司).","en":"該 can mean 'should' (我該走了), 'it's time to…' (該…了), and in written language 'the said / that' (該公司).","tc":"「該」可以表示「應該」（我該走了）、「到了該做某事的時候」（該……了），書面語裡也可以指前面提過的人或事，意思是「這個、那個」（該公司）。","sc":"「该」可以表示「应该」（我该走了）、「到了该做某事的时候」（该……了），书面语里也可以指前面提过的人或事，意思是「这个、那个」（该公司）。"},"ex":[{"c":"太晚了，我該回家了。","s":"太晚了，我该回家了。","es":"Es muy tarde, ya debo irme a casa.","en":"It's too late; I should head home now.","p":"tài wǎn le, wǒ gāi huí jiā le."},{"c":"該公司成立於一九八〇年。","s":"该公司成立于一九八〇年。","es":"Dicha empresa fue fundada en 1980.","en":"The said company was founded in 1980.","p":"gāi gōng sī chéng lì yú yī jiǔ bā líng nián."}]},{"id":"4-9-3","b":4,"l":9,"k":"tiempo momento orden secuencia time order sequence 時間 順序 lugar ubicación dónde existencia hay location place existence where 地點 位置 存在 tiempo momento orden secuencia time order sequence 时间 顺序 lugar ubicación dónde existencia hay location place existence where 地点 位置 存在","t":{"es":"Desde que: 自從…以後","en":"自從…以後 ever since...","ens":"自从…以后 ever since...","tc":"自從……以後","sc":"自从……以后"},"d":{"es":"自從 + tiempo + 以後 = desde que…; la situación empieza en ese momento y continúa hasta ahora.","en":"自從…以後 means 'ever since': a situation starts at some point and has continued until now.","tc":"「自從……以後」表示從某個時間開始，到現在一直是同樣的情況。","sc":"「自从……以后」表示从某个时间开始，到现在一直是同样的情况。"},"ex":[{"c":"自從搬到台北以後，我就很少回老家了。","s":"自从搬到台北以后，我就很少回老家了。","es":"Desde que me mudé a Taipéi, rara vez vuelvo a mi pueblo.","en":"Since I moved to Taipei, I rarely go back to my hometown.","p":"zì cóng bān dào tái běi yǐ hòu, wǒ jiù hěn shǎo huí lǎo jiā le."},{"c":"自從學了中文以後，他交了很多新朋友。","s":"自从学了中文以后，他交了很多新朋友。","es":"Desde que estudió chino, ha hecho muchos amigos nuevos.","en":"Since he started studying Chinese, he has made a lot of new friends.","p":"zì cóng xué le zhōng wén yǐ hòu, tā jiāo le hěn duō xīn péng yǒu."}]},{"id":"4-9-4","b":4,"l":9,"k":"","t":{"es":"Usos de 幾","en":"Summary of the Various Usages of 幾","ens":"Summary of the Various Usages of 几","tc":"「幾」的各種用法","sc":"「几」的各种用法"},"d":{"es":"幾 pregunta «cuántos» (números pequeños), significa «unos cuantos» (幾天) y, tras un número, «y tantos» (十幾個). 好幾 = bastantes.","en":"幾 asks 'how many' (small numbers), means 'a few' (幾天), means 'and some' after a number (十幾個), and 好幾 means 'quite a lot'.","tc":"「幾」可以問「多少」（你要幾個？）、表示不多的數量（幾天），放在數字後面表示零頭（十幾個），「好幾」表示相當多。","sc":"「几」可以问「多少」（你要几个？）、表示不多的数量（几天），放在数字后面表示零头（十几个），「好几」表示相当多。"},"ex":[{"c":"你要買幾個？","s":"你要买几个？","es":"¿Cuántos quieres comprar?","en":"How many do you want to buy?","p":"nǐ yào mǎi jǐ ge?"},{"c":"我已經等了好幾個小時了。","s":"我已经等了好几个小时了。","es":"Ya llevo esperando bastantes horas.","en":"I've been waiting for quite a few hours already.","p":"wǒ yǐ jīng děng le hǎo jǐ ge xiǎo shí le."}]},{"id":"4-9-5","b":4,"l":9,"k":"negación negar negativa negation negative 否定 contraste pero sin embargo contrast but however 對比 轉折 negación negar negativa negation negative 否定 contraste pero sin embargo contrast but however 对比 转折","t":{"es":"No poder evitar: 不禁","en":"不禁 uncontrollably, cannot help but…","ens":"不禁 uncontrollably, cannot help but…","tc":"不禁","sc":"不禁"},"d":{"es":"不禁 + verbo = no poder evitar hacer algo (una reacción involuntaria).","en":"不禁 means 'can't help (doing something)': an involuntary, natural reaction.","tc":"「不禁」表示忍不住做某個動作，是自然、不自覺的反應。","sc":"「不禁」表示忍不住做某个动作，是自然、不自觉的反应。"},"ex":[{"c":"聽到這個好消息，我不禁笑了出來。","s":"听到这个好消息，我不禁笑了出来。","es":"Al oír la buena noticia no pude evitar reírme.","en":"Hearing the good news, I couldn't help laughing.","p":"tīng dào zhè ge hǎo xiāo xí, wǒ bú jìn xiào le chū lái."},{"c":"看到老朋友的照片，他不禁想起了以前的日子。","s":"看到老朋友的照片，他不禁想起了以前的日子。","es":"Al ver la foto de un viejo amigo, no pudo evitar recordar los viejos tiempos.","en":"Seeing a photo of an old friend, he couldn't help remembering the old days.","p":"kàn dào lǎo péng yǒu de zhào piàn, tā bú jìn xiǎng qǐ le yǐ qián de rì zi."}]},{"id":"4-9-6","b":4,"l":9,"k":"","t":{"es":"Todavía: 仍然","en":"仍然 still the same, same as before","ens":"仍然 still the same, same as before","tc":"仍然","sc":"仍然"},"d":{"es":"仍然 = todavía, aun así. La situación no cambia a pesar del tiempo o de las circunstancias.","en":"仍然 means 'still / even so': the situation stays the same despite time or circumstances.","tc":"「仍然」表示經過一段時間或有了變化，情況還是和以前一樣。","sc":"「仍然」表示经过一段时间或有了变化，情况还是和以前一样。"},"ex":[{"c":"過了十年，他仍然住在同一個地方。","s":"过了十年，他仍然住在同一个地方。","es":"Pasaron diez años y él sigue viviendo en el mismo lugar.","en":"Ten years have passed and he still lives in the same place.","p":"guò le shí nián, tā réng rán zhù zài tóng yí ge dì fāng."},{"c":"雖然很累，他仍然堅持把工作做完。","s":"虽然很累，他仍然坚持把工作做完。","es":"Aunque estaba muy cansado, insistió en terminar el trabajo.","en":"Although he was tired, he still insisted on finishing the work.","p":"suī rán hěn lèi, tā réng rán jiān chí bǎ gōng zuò zuò wán."}]},{"id":"4-9-7","b":4,"l":9,"k":"","t":{"es":"En realidad: 究竟","en":"究竟 I wonder","ens":"究竟 I wonder","tc":"究竟","sc":"究竟"},"d":{"es":"究竟 = en realidad, a fin de cuentas. Se usa en preguntas para insistir en la respuesta; es más formal que 到底.","en":"究竟 is used in questions to press for the real answer: 'on earth, exactly'. It's more formal than 到底.","tc":"「究竟」用在疑問句裡，追問真正的答案，意思是「到底」，語氣比「到底」正式。","sc":"「究竟」用在疑问句里，追问真正的答案，意思是「到底」，语气比「到底」正式。"},"ex":[{"c":"你究竟想不想去？","s":"你究竟想不想去？","es":"¿En realidad quieres ir o no?","en":"Do you actually want to go or not?","p":"nǐ jiù jìng xiǎng bù xiǎng qù?"},{"c":"這件事究竟是誰的錯？","s":"这件事究竟是谁的错？","es":"¿De quién es la culpa de esto, a fin de cuentas?","en":"Whose fault is this, in the end?","p":"zhè jiàn shì jiù jìng shì shéi de cuò?"}]},{"id":"4-10-0","b":4,"l":10,"k":"progresivo continuo estar haciendo presente progressive continuous ongoing 進行 持續 progresivo continuo estar haciendo presente progressive continuous ongoing 进行 持续","t":{"es":"Usos de 著","en":"Summary of the Various Functions of 著","ens":"Summary of the Various Functions of 着","tc":"「著」的各種用法","sc":"「着」的各种用法"},"d":{"es":"著 marca un estado que continúa (牆上掛著畫), la manera en que se hace una acción (笑著說) y también una acción de fondo que sigue en curso.","en":"著 can mark a continuing state (牆上掛著畫), the manner of an action (笑著說), or an ongoing background action.","tc":"「著」可以表示狀態持續（牆上掛著畫）、動作的方式（笑著說），也可以表示背景動作正在進行。","sc":"「着」可以表示状态持续（墙上挂着画）、动作的方式（笑着说），也可以表示背景动作正在进行。"},"ex":[{"c":"牆上掛著一幅畫。","s":"墙上挂着一幅画。","es":"En la pared hay colgado un cuadro.","en":"There's a painting hanging on the wall.","p":"qiáng shàng guà zhe yì fú huà."},{"c":"他笑著對我說：「謝謝！」","s":"他笑着对我说：「谢谢！」","es":"Me dijo sonriendo: «¡Gracias!».","en":"He said to me with a smile, 'Thank you!'","p":"tā xiào zhe duì wǒ shuō: 「xiè xiè!」"}]},{"id":"4-10-1","b":4,"l":10,"k":"","t":{"es":"Usos de 中","en":"The Various Meanings of 中","ens":"The Various Meanings of 中","tc":"「中」的各種意思","sc":"「中」的各种意思"},"d":{"es":"中 (zhōng) = en, durante, dentro de; indica algo en proceso (討論中). Leído zhòng significa «acertar, ganar» (中獎).","en":"中 (zhōng) means 'in / during', showing something is in progress (討論中). Read zhòng, it means 'to hit / win' (中獎).","tc":"「中」（ㄓㄨㄥ）表示在某個範圍或過程裡，例如「討論中」；讀成ㄓㄨㄥˋ時是「打中、得到」的意思，例如「中獎」。","sc":"「中」（ㄓㄨㄥ）表示在某个范围或过程里，例如「讨论中」；读成ㄓㄨㄥˋ时是「打中、得到」的意思，例如「中奖」。"},"ex":[{"c":"這個問題還在討論中。","s":"这个问题还在讨论中。","es":"Este asunto todavía está en discusión.","en":"This issue is still under discussion.","p":"zhè ge wèn tí hái zài tǎo lùn zhōng."},{"c":"他中了大獎，高興得跳起來。","s":"他中了大奖，高兴得跳起来。","es":"Ganó el premio mayor y saltó de alegría.","en":"He won the jackpot and jumped for joy.","p":"tā zhōng le dà jiǎng, gāo xìng de tiào qǐ lái."}]},{"id":"4-10-2","b":4,"l":10,"k":"","t":{"es":"Parece que: 似乎","en":"似乎 it seems that, it gives somebody the impression that","ens":"似乎 it seems that, it gives somebody the impression that","tc":"似乎","sc":"似乎"},"d":{"es":"似乎 = parece que. Expresa una impresión o suposición, con tono algo más formal que 好像.","en":"似乎 means 'it seems that': an impression or guess based on what you see or hear, a bit more formal than 好像.","tc":"「似乎」表示根據看到或聽到的情況，覺得好像是這樣，語氣比「好像」稍微正式。","sc":"「似乎」表示根据看到或听到的情况，觉得好像是这样，语气比「好像」稍微正式。"},"ex":[{"c":"他似乎不太高興。","s":"他似乎不太高兴。","es":"Parece que no está muy contento.","en":"He doesn't seem very happy.","p":"tā sì hū bú tài gāo xìng."},{"c":"天氣似乎快要變了。","s":"天气似乎快要变了。","es":"Parece que el clima está por cambiar.","en":"It looks like the weather is about to change.","p":"tiān qì sì hū kuài yào biàn le."}]},{"id":"4-10-3","b":4,"l":10,"k":"","t":{"es":"«Con» formal: 以","en":"Classical Chinese Preposition 以","ens":"Classical Chinese Preposition 以","tc":"書面語介詞「以」","sc":"书面语介词「以」"},"d":{"es":"以 es una preposición de lengua escrita: «con, por medio de». Se ve en 以…為…, 以電話, 以免.","en":"以 is a written-language preposition meaning 'with / by means of', seen in 以…為…, 以電話, 以免.","tc":"「以」是書面語的介詞，意思是「用、憑」，常見於「以……為……」「以電話」「以免」等。","sc":"「以」是书面语的介词，意思是「用、凭」，常见于「以……为……」「以电话」「以免」等。"},"ex":[{"c":"請以電子郵件與我們聯絡。","s":"请以电子邮件与我们联络。","es":"Por favor, contáctenos por correo electrónico.","en":"Please contact us by email.","p":"qǐng yǐ diàn zǐ yóu jiàn yǔ wǒ men lián luò."},{"c":"他以流利的中文介紹了自己。","s":"他以流利的中文介绍了自己。","es":"Se presentó en un chino fluido.","en":"He introduced himself in fluent Chinese.","p":"tā yǐ liú lì de zhōng wén jiè shào le zì jǐ."}]},{"id":"4-10-4","b":4,"l":10,"k":"","t":{"es":"Tener madera: 是…的料","en":"是…的料 to be gifted in…","ens":"是…的料 to be gifted in…","tc":"是……的料","sc":"是……的料"},"d":{"es":"是…的料 = tener madera para, estar hecho para algo (un talento natural). Se usa más en la negación: 不是…的料.","en":"是…的料 means 'cut out for…': a natural talent for something, most often used negatively as 不是…的料.","tc":"「是……的料」表示天生適合做某件事，常用否定形式「不是……的料」。","sc":"「是……的料」表示天生适合做某件事，常用否定形式「不是……的料」。"},"ex":[{"c":"他不是念書的料，可是很會畫畫。","s":"他不是念书的料，可是很会画画。","es":"No tiene madera para estudiar, pero dibuja muy bien.","en":"He's not cut out for studying, but he draws very well.","p":"tā bú shì niàn shū de liào, kě shì hěn huì huà huà."},{"c":"你天生就是當老師的料。","s":"你天生就是当老师的料。","es":"Naciste para ser profesor.","en":"You were born to be a teacher.","p":"nǐ tiān shēng jiù shì dāng lǎo shī de liào."}]},{"id":"4-10-5","b":4,"l":10,"k":"dirección movimiento direction movement 方向 趨向 dirección movimiento direction movement 方向 趋向","t":{"es":"Usos de 下去","en":"Summary of 下去","ens":"Summary of 下去","tc":"「下去」的各種用法","sc":"「下去」的各种用法"},"d":{"es":"下去 después de un verbo puede significar: ir hacia abajo (走下去), seguir haciendo algo (做下去) y, en negativo, no poder continuar (撐不下去).","en":"下去 after a verb can mean going down (走下去), continuing (做下去), or, in the negative, being unable to carry on (撐不下去).","tc":"動詞後面的「下去」可以表示往下走（走下去）、繼續做下去（做下去），否定時表示沒辦法再繼續（撐不下去）。","sc":"动词后面的「下去」可以表示往下走（走下去）、继续做下去（做下去），否定时表示没办法再继续（撑不下去）。"},"ex":[{"c":"他從樓梯走下去了。","s":"他从楼梯走下去了。","es":"Bajó por las escaleras.","en":"He went down the stairs.","p":"tā cóng lóu tī zǒu xià qù le."},{"c":"這個工作太累了，我做不下去了。","s":"这个工作太累了，我做不下去了。","es":"Este trabajo es muy agotador; no puedo seguir con él.","en":"This job is too tiring; I can't keep doing it.","p":"zhè ge gōng zuò tài lèi le, wǒ zuò bú xià qù le."}]},{"id":"4-10-6","b":4,"l":10,"k":"","t":{"es":"«Desde» formal: 自","en":"自 from (formal)","ens":"自 from (formal)","tc":"書面語「自」","sc":"书面语「自」"},"d":{"es":"自 = desde (lengua escrita o formal): 自古以來, 自…起. Equivale a 從 en un registro más formal.","en":"自 is a formal, written word meaning 'from / since', as in 自古以來 and 自…起.","tc":"「自」是書面語，意思是「從」，常見於「自古以來」「自……起」。","sc":"「自」是书面语，意思是「从」，常见于「自古以来」「自……起」。"},"ex":[{"c":"這個習俗自古流傳至今。","s":"这个习俗自古流传至今。","es":"Esta costumbre se ha transmitido desde la antigüedad hasta hoy.","en":"This custom has been passed down from ancient times to the present.","p":"zhè ge xí sú zì gǔ liú chuán zhì jīn."},{"c":"本店自五月一日起調整營業時間。","s":"本店自五月一日起调整营业时间。","es":"A partir del 1 de mayo esta tienda cambia su horario.","en":"Starting May 1, this shop is changing its business hours.","p":"běn diàn zì wǔ yuè yí rì qǐ tiáo zhěng yíng yè shí jiān."}]},{"id":"4-11-0","b":4,"l":11,"k":"contraste pero sin embargo contrast but however 對比 轉折 contraste pero sin embargo contrast but however 对比 转折","t":{"es":"Justo cuando: 偏偏","en":"偏偏 contrary to expectation, against the speaker’s wish, annoyingly","ens":"偏偏 contrary to expectation, against the speaker’s wish, annoyingly","tc":"偏偏","sc":"偏偏"},"d":{"es":"偏偏 = justo, precisamente (contra lo que se desea). Se usa para algo molesto o contrario a la voluntad de alguien.","en":"偏偏 means 'of all things / just when': things turn out contrary to what's wanted, or someone stubbornly does the opposite, often with an annoyed tone.","tc":"「偏偏」表示事情剛好跟希望的相反，或故意跟別人的意見相反，常有一點不高興或無奈的語氣。","sc":"「偏偏」表示事情刚好跟希望的相反，或故意跟别人的意见相反，常有一点不高兴或无奈的语气。"},"ex":[{"c":"我正要出門，偏偏下起雨來了。","s":"我正要出门，偏偏下起雨来了。","es":"Justo cuando iba a salir, se puso a llover.","en":"Just as I was about to go out, it started raining.","p":"wǒ zhèng yào chū mén, piān piān xià qǐ yǔ lái le."},{"c":"大家都說不要去，他偏偏要去。","s":"大家都说不要去，他偏偏要去。","es":"Todos dijeron que no fuera, pero él se empeñó en ir.","en":"Everyone told him not to go, but he insisted on going.","p":"dà jiā dōu shuō bú yào qù, tā piān piān yào qù."}]},{"id":"4-11-1","b":4,"l":11,"k":"","t":{"es":"Como siempre: 照","en":"照 persist","ens":"照 persist","tc":"照（照樣、照常）","sc":"照（照样、照常）"},"d":{"es":"照 + verbo (照樣, 照常) = hacer lo mismo que antes, a pesar del cambio o del obstáculo.","en":"照 + verb (照樣, 照常) means to carry on as before regardless of changes or obstacles.","tc":"「照」加動詞（照樣、照常）表示不管情況有沒有改變，還是照以前的方式做。","sc":"「照」加动词（照样、照常）表示不管情况有没有改变，还是照以前的方式做。"},"ex":[{"c":"下雨也照常上課。","s":"下雨也照常上课。","es":"Aunque llueva, la clase se da como siempre.","en":"Class goes on as usual even when it rains.","p":"xià yǔ yě zhào cháng shàng kè."},{"c":"他被罵了，可是還是照樣遲到。","s":"他被骂了，可是还是照样迟到。","es":"Lo regañaron, pero igual llegó tarde como siempre.","en":"He got scolded, but he still showed up late as usual.","p":"tā bèi mà le, kě shì hái shì zhào yàng chí dào."}]},{"id":"4-11-2","b":4,"l":11,"k":"complemento resultado potencial complement result potential 補語 結果補語 可能補語 complemento resultado potencial complement result potential 补语 结果补语 可能补语","t":{"es":"Raro: 難得","en":"難得 rarely","ens":"难得 rarely","tc":"難得","sc":"难得"},"d":{"es":"難得 = raro, poco frecuente; algo que no ocurre a menudo y por eso se valora. También es adjetivo: «valioso».","en":"難得 means 'rare / seldom': something that doesn't happen often and is therefore valued. It can also be an adjective meaning 'precious'.","tc":"「難得」表示不常有、很少發生，所以特別可貴。也可以當形容詞，意思是「珍貴」。","sc":"「难得」表示不常有、很少发生，所以特别可贵。也可以当形容词，意思是「珍贵」。"},"ex":[{"c":"今天難得有空，我們出去走走吧。","s":"今天难得有空，我们出去走走吧。","es":"Hoy por fin tengo tiempo libre, salgamos a pasear.","en":"For once I have some free time today; let's go for a walk.","p":"jīn tiān nán dé yǒu kòng, wǒ men chū qù zǒu zǒu ba."},{"c":"這麼好的機會很難得，不要錯過。","s":"这么好的机会很难得，不要错过。","es":"Una oportunidad así es poco común; no la dejes pasar.","en":"An opportunity this good is rare; don't miss it.","p":"zhè me hǎo de jī huì hěn nán dé, bú yào cuò guò."}]},{"id":"4-11-3","b":4,"l":11,"k":"","t":{"es":"En ratos libres: 在…之餘","en":"在…之餘 while not otherwise engaged in …, apart from…","ens":"在…之余 while not otherwise engaged in …, apart from…","tc":"在……之餘","sc":"在……之余"},"d":{"es":"在…之餘 = además de / en los ratos libres de (una actividad principal), también se hace otra cosa.","en":"在…之餘 means 'in the time left over from (a main activity)': besides the main thing, you also did something else.","tc":"「在……之餘」表示除了主要的事以外，在剩下的時間裡還做了別的事。","sc":"「在……之余」表示除了主要的事以外，在剩下的时间里还做了别的事。"},"ex":[{"c":"在工作之餘，他學會了彈吉他。","s":"在工作之余，他学会了弹吉他。","es":"En sus ratos libres del trabajo, aprendió a tocar la guitarra.","en":"In his spare time from work, he learned to play the guitar.","p":"zài gōng zuò zhī yú, tā xué huì le tán jí tā."},{"c":"在忙碌之餘，也要記得多休息。","s":"在忙碌之余，也要记得多休息。","es":"Aun con mucho trabajo, recuerda descansar.","en":"Even when you're busy, remember to rest more.","p":"zài máng lù zhī yú, yě yào jì dé duō xiū xí."}]},{"id":"4-11-4","b":4,"l":11,"k":"","t":{"es":"Difícil de: 難以","en":"難以 to find it difficult to…","ens":"难以 to find it difficult to…","tc":"難以","sc":"难以"},"d":{"es":"難以 + verbo = difícil de…. Es formal y se usa con verbos de dos sílabas: 難以相信, 難以想像.","en":"難以 + verb means 'difficult to…'. It is formal and usually pairs with two-syllable verbs, as in 難以相信 and 難以想像.","tc":"「難以」加動詞表示很難做到，語氣正式，常搭配雙音節動詞，例如「難以相信」「難以想像」。","sc":"「难以」加动词表示很难做到，语气正式，常搭配双音节动词，例如「难以相信」「难以想像」。"},"ex":[{"c":"這種感覺難以用言語形容。","s":"这种感觉难以用言语形容。","es":"Este sentimiento es difícil de describir con palabras.","en":"This feeling is hard to put into words.","p":"zhè zhǒng gǎn jué nán yǐ yòng yán yǔ xíng róng."},{"c":"他的話讓人難以相信。","s":"他的话让人难以相信。","es":"Sus palabras son difíciles de creer.","en":"His words are hard to believe.","p":"tā de huà ràng rén nán yǐ xiāng xìn."}]},{"id":"4-11-5","b":4,"l":11,"k":"","t":{"es":"Poco a poco: 漸漸","en":"漸漸 gradually, slowly","ens":"渐渐 gradually, slowly","tc":"漸漸","sc":"渐渐"},"d":{"es":"漸漸 = poco a poco, gradualmente. Describe un cambio lento que va avanzando.","en":"漸漸 means 'gradually': a change happens slowly, step by step.","tc":"「漸漸」表示變化慢慢地、一步一步地發生，意思是「慢慢地」。","sc":"「渐渐」表示变化慢慢地、一步一步地发生，意思是「慢慢地」。"},"ex":[{"c":"天氣漸漸變冷了。","s":"天气渐渐变冷了。","es":"El clima se está poniendo frío poco a poco.","en":"The weather is gradually getting colder.","p":"tiān qì jiàn jiàn biàn lěng le."},{"c":"住久了，我漸漸習慣了這裡的生活。","s":"住久了，我渐渐习惯了这里的生活。","es":"Con el tiempo me fui acostumbrando a la vida aquí.","en":"After living here a while, I gradually got used to life here.","p":"zhù jiǔ le, wǒ jiàn jiàn xí guàn le zhè lǐ de shēng huó."}]},{"id":"4-11-6","b":4,"l":11,"k":"","t":{"es":"Se ve que: 可見","en":"可見 It can thus be concluded that…","ens":"可见 It can thus be concluded that…","tc":"可見","sc":"可见"},"d":{"es":"可見 = se puede ver que, esto demuestra que. Saca una conclusión a partir de lo anterior.","en":"可見 means 'it can be seen that': you draw a conclusion from the facts just mentioned.","tc":"「可見」表示從前面的事實可以得到一個結論，意思是「由此可知」。","sc":"「可见」表示从前面的事实可以得到一个结论，意思是「由此可知」。"},"ex":[{"c":"他每天練習三個小時，可見他有多認真。","s":"他每天练习三个小时，可见他有多认真。","es":"Practica tres horas al día; eso demuestra lo aplicado que es.","en":"He practices three hours every day, which shows how dedicated he is.","p":"tā měi tiān liàn xí sān ge xiǎo shí, kě jiàn tā yǒu duō rèn zhēn."},{"c":"這家店天天大排長龍，可見很受歡迎。","s":"这家店天天大排长龙，可见很受欢迎。","es":"Esta tienda tiene fila larga todos los días; se ve que es muy popular.","en":"This shop has a long line every day, so clearly it's very popular.","p":"zhè jiā diàn tiān tiān dà pái cháng lóng, kě jiàn hěn shòu huān yíng."}]},{"id":"4-11-7","b":4,"l":11,"k":"","t":{"es":"Para X: 對於…而言","en":"對於…而言 as far as… is concerned","ens":"对于…而言 as far as… is concerned","tc":"對於……而言","sc":"对于……而言"},"d":{"es":"對於 X 而言 = para X, en lo que se refiere a X. Es la forma más formal de 對 X 來說.","en":"對於 X 而言 means 'as far as X is concerned': a more formal version of 對 X 來說.","tc":"「對於 X 而言」表示從 X 的角度來看，是「對 X 來說」的比較正式說法。","sc":"「对于 X 而言」表示从 X 的角度来看，是「对 X 来说」的比较正式说法。"},"ex":[{"c":"對於初學者而言，聲調是最難的部分。","s":"对于初学者而言，声调是最难的部分。","es":"Para los principiantes, los tonos son la parte más difícil.","en":"For beginners, the tones are the hardest part.","p":"duì yú chū xué zhě ér yán, shēng diào shì zuì nán de bù fēn."},{"c":"對於很多人而言，健康比賺錢更重要。","s":"对于很多人而言，健康比赚钱更重要。","es":"Para mucha gente, la salud es más importante que ganar dinero.","en":"For many people, health is more important than making money.","p":"duì yú hěn duō rén ér yán, jiàn kāng bǐ zhuàn qián gèng zhòng yào."}]},{"id":"4-12-0","b":4,"l":12,"k":"","t":{"es":"Da igual: 無所謂","en":"無所謂 does not matter","ens":"无所谓 does not matter","tc":"無所謂","sc":"无所谓"},"d":{"es":"無所謂 = da igual, no importa. Se dice cuando a uno le es indiferente la opción.","en":"無所謂 means 'it doesn't matter / I don't mind': you're indifferent to the choice.","tc":"「無所謂」表示怎麼樣都可以，不在意，沒有特別的意見。","sc":"「无所谓」表示怎么样都可以，不在意，没有特别的意见。"},"ex":[{"c":"吃什麼我都無所謂。","s":"吃什么我都无所谓。","es":"Me da igual qué comer.","en":"I don't mind what we eat.","p":"chī shén me wǒ dōu wú suǒ wèi."},{"c":"對他來說，輸贏無所謂。","s":"对他来说，输赢无所谓。","es":"Para él, ganar o perder no importa.","en":"For him, winning or losing doesn't matter.","p":"duì tā lái shuō, shū yíng wú suǒ wèi."}]},{"id":"4-12-1","b":4,"l":12,"k":"","t":{"es":"¿Quién iba a decir?: 誰知道","en":"誰知道 who would have thought…?","ens":"谁知道 who would have thought…?","tc":"誰知道","sc":"谁知道"},"d":{"es":"誰知道 = ¿quién iba a pensar…? (algo inesperado después de lo planeado). También puede significar «quién sabe».","en":"誰知道 means 'who would have thought': something unexpected happens after the plan. It can also mean 'who knows'.","tc":"「誰知道」表示出乎意料，常用在原本的計畫之後，意思是「沒想到」。也可以表示「不知道」。","sc":"「谁知道」表示出乎意料，常用在原本的计划之后，意思是「没想到」。也可以表示「不知道」。"},"ex":[{"c":"本來想去爬山，誰知道突然下起大雨。","s":"本来想去爬山，谁知道突然下起大雨。","es":"Pensábamos ir a la montaña, pero quién iba a decir que de repente llovería a cántaros.","en":"We meant to go hiking, but who would have thought it would suddenly pour.","p":"běn lái xiǎng qù pá shān, shéi zhī dào tú rán xià qǐ dà yǔ."},{"c":"誰知道他到底在想什麼？","s":"谁知道他到底在想什么？","es":"¿Quién sabe qué estará pensando en realidad?","en":"Who knows what he's really thinking?","p":"shéi zhī dào tā dào dǐ zài xiǎng shén me?"}]},{"id":"4-12-2","b":4,"l":12,"k":"","t":{"es":"De A hasta B: 小自…大至…","en":"小自…大至… everything from A to Z","ens":"小自…大至… everything from A to Z","tc":"小自……大至……","sc":"小自……大至……"},"d":{"es":"小自 A，大至 B = desde A (lo más pequeño) hasta B (lo más grande): abarca todo el rango.","en":"小自 A, 大至 B means 'from the smallest A to the biggest B': it covers the whole range.","tc":"「小自 A，大至 B」表示範圍很廣，從最小的 A 到最大的 B 都包括在內。","sc":"「小自 A，大至 B」表示范围很广，从最小的 A 到最大的 B 都包括在内。"},"ex":[{"c":"小自一杯咖啡，大至一棟房子，網路上什麼都買得到。","s":"小自一杯咖啡，大至一栋房子，网路上什么都买得到。","es":"Desde un café hasta una casa, en internet se puede comprar de todo.","en":"From a cup of coffee to a house, you can buy anything online.","p":"xiǎo zì yì bēi kā fēi, dà zhì yí dòng fáng zi, wǎng lù shàng shén me dōu mǎi dé dào."},{"c":"小自個人生活，大至國家大事，他都有自己的看法。","s":"小自个人生活，大至国家大事，他都有自己的看法。","es":"Desde la vida personal hasta los asuntos del país, tiene su propia opinión de todo.","en":"From personal life to affairs of state, he has his own opinion on everything.","p":"xiǎo zì gè rén shēng huó, dà zhì guó jiā dà shì, tā dōu yǒu zì jǐ de kàn fǎ."}]},{"id":"4-12-3","b":4,"l":12,"k":"","t":{"es":"¡Increíble!: 竟然","en":"竟然 to the speaker’s great surprise","ens":"竟然 to the speaker’s great surprise","tc":"竟然","sc":"竟然"},"d":{"es":"竟然 = ¡increíblemente!, ¡quién lo diría! Expresa gran sorpresa del hablante ante algo inesperado.","en":"竟然 expresses the speaker's great surprise that something turned out unexpectedly.","tc":"「竟然」表示說話的人覺得很意外，沒想到事情會這樣。","sc":"「竟然」表示说话的人觉得很意外，没想到事情会这样。"},"ex":[{"c":"他竟然沒有告訴我就搬家了。","s":"他竟然没有告诉我就搬家了。","es":"¡Increíble, se mudó sin decirme nada!","en":"Unbelievably, he moved without telling me.","p":"tā jìng rán méi yǒu gào sù wǒ jiù bān jiā le."},{"c":"這麼簡單的題目，他竟然答錯了。","s":"这么简单的题目，他竟然答错了。","es":"Una pregunta tan fácil, ¡y la respondió mal!","en":"Such an easy question, and he got it wrong!","p":"zhè me jiǎn dān de tí mù, tā jìng rán dá cuò le."}]},{"id":"4-12-4","b":4,"l":12,"k":"","t":{"es":"En teoría: 照理說","en":"照理說 normally","ens":"照理说 normally","tc":"照理說","sc":"照理说"},"d":{"es":"照理說 = en teoría, normalmente. Plantea lo que debería ser lo normal, y suele seguir un contraste.","en":"照理說 means 'normally / in theory': it states what should be the case, and is often followed by a contrast.","tc":"「照理說」表示依照一般的道理，事情應該是這樣，後面常常接著說實際上不是這樣。","sc":"「照理说」表示依照一般的道理，事情应该是这样，后面常常接着说实际上不是这样。"},"ex":[{"c":"照理說，他應該已經到了。","s":"照理说，他应该已经到了。","es":"En teoría, ya debería haber llegado.","en":"In theory, he should have arrived by now.","p":"zhào lǐ shuō, tā yīng gāi yǐ jīng dào le."},{"c":"照理說這個時間不會塞車，可是今天卻塞得很嚴重。","s":"照理说这个时间不会塞车，可是今天却塞得很严重。","es":"Normalmente a esta hora no hay tráfico, pero hoy hay mucho.","en":"Normally there's no traffic at this hour, but today it's really bad.","p":"zhào lǐ shuō zhè ge shí jiān bú huì sāi chē, kě shì jīn tiān què sāi dé hěn yán zhòng."}]},{"id":"4-12-5","b":4,"l":12,"k":"","t":{"es":"Tomar A como B: 以A為B","en":"以A為B to take A as B","ens":"以A为B to take A as B","tc":"以 A 為 B","sc":"以 A 为 B"},"d":{"es":"以 A 為 B = tomar A como B (como modelo, prioridad o base). Es formal.","en":"以 A 為 B means 'take A as B': as a model, priority or basis. It is formal.","tc":"「以 A 為 B」表示把 A 當作 B，例如當作榜樣、重點或基礎，語氣正式。","sc":"「以 A 为 B」表示把 A 当作 B，例如当作榜样、重点或基础，语气正式。"},"ex":[{"c":"這間公司以客戶為第一。","s":"这间公司以客户为第一。","es":"Esta empresa pone al cliente en primer lugar.","en":"This company puts customers first.","p":"zhè jiān gōng sī yǐ kè hù wéi dì yī."},{"c":"他以老師為榜樣，努力學習。","s":"他以老师为榜样，努力学习。","es":"Toma a su profesor como modelo y estudia con esfuerzo.","en":"He takes his teacher as a role model and studies hard.","p":"tā yǐ lǎo shī wéi bǎng yàng, nǔ lì xué xí."}]},{"id":"4-12-6","b":4,"l":12,"k":"","t":{"es":"No importa…: 無論…都…","en":"無論…都… regardless of what…","ens":"无论…都… regardless of what…","tc":"無論……都……","sc":"无论……都……"},"d":{"es":"無論…都… = no importa qué / cómo…, siempre…. Introduce una condición con varias opciones y el mismo resultado.","en":"無論…都… means 'no matter what/how…, always…': the result is the same in every case. 無論 is usually followed by a question word or choices.","tc":"「無論……都……」表示不管是哪一種情況，結果都一樣。「無論」後面通常有疑問詞或選擇。","sc":"「无论……都……」表示不管是哪一种情况，结果都一样。「无论」后面通常有疑问词或选择。"},"ex":[{"c":"無論天氣好不好，他都會去跑步。","s":"无论天气好不好，他都会去跑步。","es":"Haga buen tiempo o no, él siempre sale a correr.","en":"Whether the weather is good or not, he goes running.","p":"wú lùn tiān qì hǎo bù hǎo, tā dōu huì qù pǎo bù."},{"c":"無論你說什麼，我都不會改變主意。","s":"无论你说什么，我都不会改变主意。","es":"Digas lo que digas, no voy a cambiar de opinión.","en":"No matter what you say, I won't change my mind.","p":"wú lùn nǐ shuō shén me, wǒ dōu bú huì gǎi biàn zhǔ yì."}]},{"id":"4-12-7","b":4,"l":12,"k":"","t":{"es":"Claramente: 明明","en":"明明 It should be obvious to everyone that…","ens":"明明 It should be obvious to everyone that…","tc":"明明","sc":"明明"},"d":{"es":"明明 = claramente, a todas luces. Se usa cuando algo es obvio pero lo que se dice o hace lo contradice.","en":"明明 means 'obviously': the facts are clear, yet what is said or done contradicts them, often with a tone of blame or dissatisfaction.","tc":"「明明」表示事實很清楚，可是說的話或做的事卻和事實不一樣，常有責怪或不滿的語氣。","sc":"「明明」表示事实很清楚，可是说的话或做的事却和事实不一样，常有责怪或不满的语气。"},"ex":[{"c":"明明是你自己說要去的，現在怎麼又不去了？","s":"明明是你自己说要去的，现在怎么又不去了？","es":"Fuiste tú mismo quien dijo que iría, ¿cómo es que ahora no vas?","en":"You were the one who said you'd go; why aren't you going now?","p":"míng míng shì nǐ zì jǐ shuō yào qù de, xiàn zài zěn me yòu bú qù le?"},{"c":"他明明知道答案，卻假裝不知道。","s":"他明明知道答案，却假装不知道。","es":"Claramente sabe la respuesta, pero finge que no.","en":"He obviously knows the answer, but he pretends not to.","p":"tā míng míng zhī dào dá àn, què jiǎ zhuāng bù zhī dào."}]},{"id":"4-12-8","b":4,"l":12,"k":"complemento resultado potencial complement result potential 補語 結果補語 可能補語 complemento resultado potencial complement result potential 补语 结果补语 可能补语","t":{"es":"Hacer que: 使得","en":"Causation with 使得","ens":"Causation with 使得","tc":"使得","sc":"使得"},"d":{"es":"使得 = hacer que, provocar. Expresa que un hecho causa un resultado (suele ser un sujeto no humano).","en":"使得 means 'to cause / make': one event causes a result, and the subject is often not a person.","tc":"「使得」表示某件事造成了某個結果，主語常常不是人。","sc":"「使得」表示某件事造成了某个结果，主语常常不是人。"},"ex":[{"c":"這場大雨使得很多航班取消了。","s":"这场大雨使得很多航班取消了。","es":"Esta fuerte lluvia hizo que se cancelaran muchos vuelos.","en":"This heavy rain caused many flights to be canceled.","p":"zhè chǎng dà yǔ shǐ dé hěn duō háng bān qǔ xiāo le."},{"c":"網路的發展使得生活更方便。","s":"网路的发展使得生活更方便。","es":"El desarrollo de internet hizo la vida más cómoda.","en":"The development of the internet has made life more convenient.","p":"wǎng lù de fā zhǎn shǐ dé shēng huó gèng fāng biàn."}]}]};
